/**
 * Tee82 - 골프몬(golfmon.net) 조인 자동등록 올인원 변환기
 * AdGuard 스타일의 컴팩트 모던 UI & 카드형 티타임 뷰 엔진
 */

// 기본 동기화 코드 (사용자 기본 제공 사전 데이터)
const DEFAULT_SYNC_CODE = "";

// 동기화 코드 디코더 (순수 Base64, 하이브리드, URL인코딩, JSON 모두 대응)
function decodeSyncString(str) {
    if (!str || typeof str !== 'string') return null;
    str = str.trim();
    // 1. 순수 Base64 + URL 인코딩 형식
    try {
        const decoded = JSON.parse(decodeURIComponent(atob(str)));
        if (decoded && typeof decoded === 'object') return decoded;
    } catch(e) {}
    // 2. 하이브리드 인코딩 (앞 50글자 Base64 + 뒷부분 URL인코딩)
    try {
        if (str.startsWith("JTdCJTIy")) {
            const b64Part = str.substring(0, 50) + "==";
            const decodedB64 = atob(b64Part);
            const fullUri = decodedB64 + str.substring(50);
            const decoded = JSON.parse(decodeURIComponent(fullUri));
            if (decoded && typeof decoded === 'object') return decoded;
        }
    } catch(e) {}
    // 3. 순수 URI 인코딩 JSON
    try {
        const decoded = JSON.parse(decodeURIComponent(str));
        if (decoded && typeof decoded === 'object') return decoded;
    } catch(e) {}
    // 4. 일반 JSON
    try {
        const decoded = JSON.parse(str);
        if (decoded && typeof decoded === 'object') return decoded;
    } catch(e) {}
    return null;
}

// 기본 사전 로드 및 초기화
const defaultDict = decodeSyncString(DEFAULT_SYNC_CODE) || {};

// 골마켓 전용 기본 골프장명 매핑 테이블
const GOLMARKET_GOLF_NAME_MAP = {
    '골프존진천': '골프존카운티 진천',
    '골프존화랑': '골프존카운티 화랑',
    '골프존송도': '골프존카운티 송도',
    '골프존천안': '골프존카운티 천안',
    '골프존 진천': '골프존카운티 진천',
    '골프존 화랑': '골프존카운티 화랑',
    '골프존 송도': '골프존카운티 송도',
    '골프존 천안': '골프존카운티 천안',
    '골프존카운티진천': '골프존카운티 진천',
    '골프존카운티화랑': '골프존카운티 화랑',
    '골프존카운티송도': '골프존카운티 송도',
    '골프존카운티천안': '골프존카운티 천안',
    '골프존안성H': '골프존카운티 안성H',
    '골프존안성W': '골프존카운티 안성W'
};

function getGolmarketGolfName(golfName) {
    if (!golfName) return '';
    const clean = String(golfName).trim();
    if (GOLMARKET_GOLF_NAME_MAP[clean]) return GOLMARKET_GOLF_NAME_MAP[clean];
    const noSpace = clean.replace(/[\s\-_]/g, '');
    for (const [k, v] of Object.entries(GOLMARKET_GOLF_NAME_MAP)) {
        if (k.replace(/[\s\-_]/g, '') === noSpace) return v;
    }
    if (/골프존.*진천/i.test(clean)) return '골프존카운티 진천';
    if (/골프존.*화랑/i.test(clean)) return '골프존카운티 화랑';
    if (/골프존.*송도/i.test(clean)) return '골프존카운티 송도';
    if (/골프존.*천안/i.test(clean)) return '골프존카운티 천안';
    return clean;
}

// 9대 표준 지역 목록 (매핑사전 및 골프몬 등록 엄격 준수)
const VALID_STANDARD_REGIONS = [
    '경기남부',
    '경기북부',
    '충청',
    '전라',
    '경상',
    '인천경인',
    '경기동부',
    '강원',
    '제주'
];

/**
 * 임의의 지역 문자열을 9대 표준 지역 중 하나로 정규화
 * (경기안성, 경기용인, 경기여주 -> 경기남부 / 경기포천 -> 경기북부 / 강원도 -> 강원 등)
 */
function toStandardRegion(str) {
    if (!str || typeof str !== 'string') return '';
    const clean = str.replace(/[\[\]()]/g, '').trim();
    if (!clean) return '';

    // 1. 이미 9대 표준 지역인 경우 즉시 반환
    if (VALID_STANDARD_REGIONS.includes(clean)) return clean;

    // 2. '경기동부' 우선 검사 (동부 구장 분리)
    if (clean.includes('경기동부') || clean === '동부') return '경기동부';

    // 3. '인천경인'
    if (clean.includes('인천경인') || clean.includes('경인') || clean.includes('인천') || clean.includes('영종') || clean.includes('강화')) return '인천경인';

    // 4. '경기북부' 및 북부 지자체/지역명
    if (clean.includes('경기북부') || clean.includes('경기북') || clean === '북부' ||
        /경기.*(?:포천|파주|양주|동두천|가평|연천|구리|남양주|고양|일산)/.test(clean) ||
        /^(?:포천|파주|양주|동두천|가평|연천|구리|남양주|고양|일산)$/.test(clean)) {
        return '경기북부';
    }

    // 5. '경기남부' 및 남부 지자체/지역명 (경기안성, 경기용인, 경기여주, 경기이천, 경기화성, 안성, 용인, 여주, 이천 등)
    if (clean.includes('경기남부') || clean.includes('경기남') || clean === '남부' || clean === '경기' ||
        /경기.*(?:안성|용인|여주|이천|화성|평택|오산|수원|성남|광주|양평|과천|의왕|군포|안산|안양)/.test(clean) ||
        /^(?:안성|용인|여주|이천|화성|평택|오산|수원|성남|양평|과천|의왕|군포|안산|안양)$/.test(clean)) {
        return '경기남부';
    }

    // 6. '충청' (충남, 충북, 대전, 세종, 진천, 음성, 천안, 아산, 충주, 청주 등)
    if (/충청|충남|충북|대전|세종/.test(clean) ||
        /^(?:진천|음성|감곡|화랑|천안|아산|당진|서산|태안|보령|공주|논산|청주|충주|제천|단양|괴산)$/.test(clean)) {
        return '충청';
    }

    // 7. '강원' (강원도, 춘천, 원주, 강릉, 홍천, 횡성, 평창, 철원 등)
    if (/강원/.test(clean) ||
        /^(?:춘천|원주|강릉|홍천|횡성|평창|속초|삼척|태백|정선|고성|양양|철원|화천|양구|인제)$/.test(clean)) {
        return '강원';
    }

    // 8. '전라' (전남, 전북, 광주광역시, 순천, 여수, 익산, 전주, 군산, 목포, 나주 등)
    if (/전라|전남|전북/.test(clean) ||
        /^(?:순천|여수|목포|나주|익산|군산|전주|담양|화순|무안|영암|해남|광양|정읍|남원)$/.test(clean)) {
        return '전라';
    }

    // 9. '경상' (경남, 경북, 부산, 대구, 울산, 창원, 포항, 구미, 경주, 김천, 안동 등)
    if (/경상|경남|경북|부산|대구|울산/.test(clean) ||
        /^(?:창원|포항|구미|경주|김천|안동|진주|김해|양산|밀양|거제|통영|영천|상주|문경|경산)$/.test(clean)) {
        return '경상';
    }

    // 10. '제주' (제주도, 서귀포)
    if (/제주|서귀포/.test(clean)) {
        return '제주';
    }

    return '';
}

// 사이트별(골프몬, 골팡, 골마켓, 골프락) 매핑 객체 표준화 함수
function normalizeDictEntry(entry, key = '') {
    if (!entry) {
        return {
            region: '',
            golfmon: key,
            golfpang: key,
            golmarket: getGolmarketGolfName(key) || key,
            golfrock: key,
            name: key
        };
    }
    if (typeof entry === 'string') {
        const gm = getGolmarketGolfName(entry) || getGolmarketGolfName(key) || entry;
        return {
            region: '',
            golfmon: entry,
            golfpang: entry,
            golmarket: gm,
            golfrock: entry,
            name: entry
        };
    }
    const baseName = entry.name || entry.golfmon || key;
    const golfmon = entry.golfmon || baseName;
    const golfpang = entry.golfpang || baseName;
    const golmarket = entry.golmarket || getGolmarketGolfName(key) || getGolmarketGolfName(baseName) || baseName;
    const golfrock = entry.golfrock || baseName;
    const rawReg = entry.region || '';
    const stdRegion = toStandardRegion(rawReg) || rawReg;
    return {
        region: stdRegion,
        golfmon: golfmon,
        golfpang: golfpang,
        golmarket: golmarket,
        golfrock: golfrock,
        name: baseName
    };
}

// 통합 영구 저장 함수: localStorage 와 chrome.storage.local 동시 실시간 저장
let dictionary = {};

function saveDictionary() {
    try {
        localStorage.setItem('v2_golfDict', JSON.stringify(dictionary));
    } catch(e) {}
    try {
        if (typeof chrome !== 'undefined' && chrome.storage && chrome.storage.local) {
            chrome.storage.local.set({ v2_golfDict: dictionary });
        }
    } catch(e) {}
}


// 사용자 커스텀 사전이 '그대로' 보존되도록 로드 및 사이트별 필드 정규화
function initDictionary() {
    let saved = null;
    try {
        const str = localStorage.getItem('v2_golfDict');
        if (str) saved = JSON.parse(str);
    } catch(e) {}

    if (saved && typeof saved === 'object' && Object.keys(saved).length > 0) {
        dictionary = {};
        for (const [k, v] of Object.entries(saved)) {
            dictionary[k] = normalizeDictEntry(v, k);
        }
    } else {
        // 저장된 사전이 없을 때만 기본값으로 최초 초기화
        dictionary = {};
        for (const [k, v] of Object.entries(defaultDict)) {
            dictionary[k] = normalizeDictEntry(v, k);
        }
        saveDictionary();
    }

    // chrome.storage.local 비동기 동기화 (기기간/창간 영구 보존)
    try {
        if (typeof chrome !== 'undefined' && chrome.storage && chrome.storage.local) {
            chrome.storage.local.get(['v2_golfDict'], (res) => {
                if (res && res.v2_golfDict && typeof res.v2_golfDict === 'object' && Object.keys(res.v2_golfDict).length > 0) {
                    dictionary = {};
                    for (const [k, v] of Object.entries(res.v2_golfDict)) {
                        dictionary[k] = normalizeDictEntry(v, k);
                    }
                    try { localStorage.setItem('v2_golfDict', JSON.stringify(dictionary)); } catch(e) {}
                }
            });
        }
    } catch(e) {}
}

initDictionary();

// 상태 영구 저장 (팝업 닫았다 열어도 변환 내용 유지)
function saveCurrentTableState() {
    const trs = Array.from(document.querySelectorAll('#dataTable tbody tr'));
    const data = trs.map(tr => {
        const cells = tr.querySelectorAll('td');
        return {
            date: cells[0]?.textContent || '',
            region: cells[1]?.textContent || '',
            golf: cells[2]?.textContent || '',
            time: cells[3]?.textContent || '',
            fee: cells[4]?.textContent || '',
            baseFee: tr.dataset.baseFee || cells[4]?.textContent || '',
            origBaseFee: tr.dataset.origBaseFee || '',
            cady: cells[5]?.textContent || '',
            condition: cells[6]?.textContent || '',
            sizenum: cells[7]?.textContent || '',
            roomType: tr.dataset.roomType || '',
            origRoomType: tr.dataset.origRoomType || tr.dataset.roomType || '',
            manualSeonti: tr.dataset.manualSeonti === 'true',
            isPrepaid: tr.dataset.isPrepaid === 'true',
            isMeal: tr.dataset.isMeal === 'true',
            isSeontiOrDaegi: tr.dataset.isSeontiOrDaegi === 'true' || tr.dataset.roomType === '선티방' || tr.dataset.roomType === '대기방',
            isMapped: tr.dataset.isMapped !== 'false',
            rawGolf: tr.dataset.rawGolf || '',
            golfmonGolf: tr.dataset.golfmonGolf || '',
            golfpangGolf: tr.dataset.golfpangGolf || '',
            golmarketGolf: tr.dataset.golmarketGolf || '',
            golfrockGolf: tr.dataset.golfrockGolf || '',
            hasSlashFee: tr.dataset.hasSlashFee === 'true',
            slashFrontVal: tr.dataset.slashFrontVal || '',
            slashBackVal: tr.dataset.slashBackVal || '',
            origSlashFrontVal: tr.dataset.origSlashFrontVal || '',
            prepaidAmount: tr.dataset.prepaidAmount || '0',
            noticeAdjusted: tr.dataset.noticeAdjusted === 'true',
            noticePrice: tr.dataset.noticePrice || '',
            noticeDiscount: tr.dataset.noticeDiscount || '',
            noticeTagDesc: tr.dataset.noticeTagDesc || '',
            noticeType: tr.dataset.noticeType || '',
            coursePriceAdj: tr.dataset.coursePriceAdj || '',
            source: tr.dataset.source || 'golfrock',
            selected: tr.classList.contains('selected')
        };
    });
    localStorage.setItem('v2_savedTableData', JSON.stringify(data));
}

// 저장된 상태 복원
function restoreSavedTableState() {
    try {
        const savedJson = localStorage.getItem('v2_savedTableData');
        if (!savedJson) return false;
        const data = JSON.parse(savedJson);
        if (!Array.isArray(data) || data.length === 0) return false;

        const tbody = document.getElementById('tableBody');
        if (!tbody) return false;
        tbody.innerHTML = '';

        data.forEach(item => {
            const tr = document.createElement('tr');
            tr.dataset.roomType = item.roomType || '미표시';
            if (item.origRoomType) tr.dataset.origRoomType = item.origRoomType;
            if (item.manualSeonti) tr.dataset.manualSeonti = 'true';
            tr.dataset.isPrepaid = item.isPrepaid ? 'true' : 'false';
            tr.dataset.isMeal = item.isMeal ? 'true' : 'false';
            if (item.isSeontiOrDaegi) tr.dataset.isSeontiOrDaegi = 'true';
            tr.dataset.isMapped = item.isMapped === false ? 'false' : 'true';
            tr.dataset.rawGolf = item.rawGolf || '';
            tr.dataset.baseFee = item.baseFee !== undefined ? item.baseFee : (item.fee || '');
            if (item.origBaseFee) tr.dataset.origBaseFee = item.origBaseFee;
            tr.dataset.golfmonGolf = item.golfmonGolf || item.golf || '';
            tr.dataset.golfpangGolf = item.golfpangGolf || item.golf || '';
            tr.dataset.golmarketGolf = item.golmarketGolf || getGolmarketGolfName(item.rawGolf || item.golf) || item.golf || '';
            tr.dataset.golfrockGolf = item.golfrockGolf || item.golf || '';
            if (item.hasSlashFee) tr.dataset.hasSlashFee = 'true';
            if (item.slashFrontVal) tr.dataset.slashFrontVal = item.slashFrontVal;
            if (item.slashBackVal) tr.dataset.slashBackVal = item.slashBackVal;
            if (item.origSlashFrontVal) tr.dataset.origSlashFrontVal = item.origSlashFrontVal;
            if (item.prepaidAmount) tr.dataset.prepaidAmount = item.prepaidAmount;
            if (item.noticeAdjusted) tr.dataset.noticeAdjusted = 'true';
            if (item.noticePrice) tr.dataset.noticePrice = item.noticePrice;
            if (item.noticeDiscount) tr.dataset.noticeDiscount = item.noticeDiscount;
            if (item.noticeTagDesc) tr.dataset.noticeTagDesc = item.noticeTagDesc;
            if (item.noticeType) tr.dataset.noticeType = item.noticeType;
            if (item.coursePriceAdj) tr.dataset.coursePriceAdj = item.coursePriceAdj;
            tr.dataset.source = item.source || 'golfrock';
            if (item.selected) tr.classList.add('selected');
            const stdRegion = getRegion(item.region, (item.rawGolf || '') + ' ' + (item.golf || ''));
            item.region = stdRegion;

            tr.innerHTML = `
                <td>${item.date}</td>
                <td>${stdRegion}</td>
                <td>${item.golf}</td>
                <td>${item.time}</td>
                <td>${item.fee}</td>
                <td>${item.cady}</td>
                <td>${item.condition}</td>
                <td>${item.sizenum}</td>
            `;
            tbody.appendChild(tr);
        });

        renderCardList();
        return true;
    } catch(e) {
        console.error("Failed to restore saved table state:", e);
        return false;
    }
}

