// 특정구장 가격 일괄 가감 설정 상태 및 헬퍼 함수
// 특정구장 가격 일괄 가감 설정 상태 및 헬퍼 함수
// 구조: [ { course: string, diff: number, hasPart1: boolean, hasPart2: boolean, hasPart3: boolean } ]
let customCoursePriceAdjustments = [];

function normalizeCoursePriceAdjustmentItem(item) {
    if (!item) return null;
    const course = String(item.course || '').trim();
    const diff = parseFloat(item.diff) || 0;
    if (!course || isNaN(diff) || diff === 0) return null;

    const hasP1 = item.hasPart1 ?? true;
    const hasP2 = item.hasPart2 ?? true;
    const hasP3 = item.hasPart3 ?? true;
    const all = (!hasP1 && !hasP2 && !hasP3);

    return {
        course: course,
        diff: diff,
        hasPart1: all ? true : Boolean(hasP1),
        hasPart2: all ? true : Boolean(hasP2),
        hasPart3: all ? true : Boolean(hasP3)
    };
}

function getCourseAdjPartDesc(item) {
    const p1 = item.hasPart1 !== false;
    const p2 = item.hasPart2 !== false;
    const p3 = item.hasPart3 !== false;

    if (p1 && p2 && p3) return '전부';
    if (p1 && p2 && !p3) return '1~2부';
    if (!p1 && p2 && p3) return '2~3부';
    if (p1 && !p2 && p3) return '1,3부';
    if (p1 && !p2 && !p3) return '1부';
    if (!p1 && p2 && !p3) return '2부';
    if (!p1 && !p2 && p3) return '3부';
    return '전부';
}

/**
 * 티타임 시간(문자열 또는 분)을 기준으로 부제(1부, 2부, 3부) 번호(1, 2, 3) 반환
 * - 1부: 오전 05시부터 09시대까지 (10시 이전: < 600분)
 * - 2부: 10시부터 16시대 이전까지 (600분 <= mins < 960분)
 * - 3부: 16시부터 21시대까지 (16시 이후: >= 960분)
 */
function getTimePartNumber(timeStrOrMins) {
    const mins = typeof timeStrOrMins === 'number' ? timeStrOrMins : timeToMinutes(timeStrOrMins);
    if (mins < 10 * 60) return 1;
    if (mins < 16 * 60) return 2;
    return 3;
}

function loadCoursePriceAdjustments() {
    try {
        const saved = localStorage.getItem('v2_coursePriceAdjustments');
        if (saved) {
            const parsed = JSON.parse(saved);
            if (Array.isArray(parsed)) {
                customCoursePriceAdjustments = parsed
                    .map(item => normalizeCoursePriceAdjustmentItem(item))
                    .filter(Boolean);
            }
        }
    } catch (e) {
        customCoursePriceAdjustments = [];
    }
    updateCoursePriceBadgeUI();
}

function saveCoursePriceAdjustments() {
    try {
        localStorage.setItem('v2_coursePriceAdjustments', JSON.stringify(customCoursePriceAdjustments));
    } catch (e) {}
    try {
        if (typeof chrome !== 'undefined' && chrome.storage && chrome.storage.local) {
            chrome.storage.local.set({ v2_coursePriceAdjustments: customCoursePriceAdjustments });
        }
    } catch (e) {}
    updateCoursePriceBadgeUI();
}

function updateCoursePriceBadgeUI() {
    const badge = document.getElementById('coursePriceBadge');
    const wrapper = document.getElementById('coursePriceCountWrapper');
    const modalCount = document.getElementById('coursePriceModalCountText');
    const count = customCoursePriceAdjustments.length;

    if (badge) badge.textContent = count.toString();
    if (wrapper) wrapper.style.display = count > 0 ? 'inline' : 'none';
    if (modalCount) modalCount.textContent = count.toString();
    updateCoursePriceHeaderUI();
}

// 특정구장 가격변경 적용 여부 전역 토글 (체크박스 상태: 기본 true)
let isCoursePriceRulesActive = true;

function initCoursePriceRulesActive() {
    try {
        const saved = localStorage.getItem('v2_isCoursePriceRulesActive');
        if (saved !== null) {
            isCoursePriceRulesActive = (saved === 'true');
        }
    } catch(e) {}
    const chk = document.getElementById('chkEnableCoursePriceRules');
    if (chk) chk.checked = isCoursePriceRulesActive;
    updateCoursePriceHeaderUI();
}

function updateCoursePriceHeaderUI() {
    const group = document.getElementById('coursePriceHeaderBtnGroup');
    const chk = document.getElementById('chkEnableCoursePriceRules');
    const badgeWrapper = document.getElementById('coursePriceCountWrapper');
    const isChecked = chk ? chk.checked : isCoursePriceRulesActive;

    if (group) {
        group.classList.toggle('disabled-course-price', !isChecked);
    }
    if (badgeWrapper) {
        badgeWrapper.style.color = isChecked ? '#2563EB' : '#94A3B8';
    }
}

function setCoursePriceRulesActive(active, notify = true) {
    isCoursePriceRulesActive = active;
    try {
        localStorage.setItem('v2_isCoursePriceRulesActive', active ? 'true' : 'false');
        if (typeof chrome !== 'undefined' && chrome.storage && chrome.storage.local) {
            chrome.storage.local.set({ v2_isCoursePriceRulesActive: active });
        }
    } catch(e) {}
    const chk = document.getElementById('chkEnableCoursePriceRules');
    if (chk) chk.checked = active;
    updateCoursePriceHeaderUI();
    applyAllActiveNoticeRules();
    if (notify) {
        if (active) {
            showToast('🟢 특정구장 가격변경 적용이 활성화되었습니다.');
        } else {
            showToast('⚪ 특정구장 가격변경 적용이 비활성화되었습니다. (원래 금액으로 표시)');
        }
    }
}

function getCoursePriceAdjustment(golfName, rawGolfName = '', golfmonGolfName = '', rowTime = '') {
    if (!isCoursePriceRulesActive) return 0;
    if (!customCoursePriceAdjustments || customCoursePriceAdjustments.length === 0) return 0;
    const cleanTargets = [golfName, rawGolfName, golfmonGolfName]
        .filter(Boolean)
        .map(n => String(n).replace(/[\s\-_()\[\]]/g, '').toLowerCase());

    const partNum = rowTime ? getTimePartNumber(rowTime) : 0;

    const matchedAdjs = [];
    for (const adj of customCoursePriceAdjustments) {
        if (!adj.course) continue;
        const cleanAdj = String(adj.course).replace(/[\s\-_()\[\]]/g, '').toLowerCase();
        if (!cleanAdj) continue;

        const matched = cleanTargets.some(t => t.includes(cleanAdj) || cleanAdj.includes(t)) ||
                        (typeof isCourseMatch === 'function' && isCourseMatch(adj.course, golfName, rawGolfName, golfmonGolfName));
        if (matched) {
            matchedAdjs.push(adj);
        }
    }

    if (matchedAdjs.length === 0) return 0;

    if (partNum > 0) {
        const partMatchedAdjs = matchedAdjs.filter(adj => {
            const hasP1 = adj.hasPart1 !== false;
            const hasP2 = adj.hasPart2 !== false;
            const hasP3 = adj.hasPart3 !== false;
            if (partNum === 1) return hasP1;
            if (partNum === 2) return hasP2;
            if (partNum === 3) return hasP3;
            return true;
        });

        if (partMatchedAdjs.length > 0) {
            // 더 구체적인(체크된 부제 개수가 적은) 규칙 우선 (예: 1~2부 지정 규칙이 전부 지정 규칙보다 우선 적용)
            partMatchedAdjs.sort((a, b) => {
                const countA = (a.hasPart1 ? 1 : 0) + (a.hasPart2 ? 1 : 0) + (a.hasPart3 ? 1 : 0);
                const countB = (b.hasPart1 ? 1 : 0) + (b.hasPart2 ? 1 : 0) + (b.hasPart3 ? 1 : 0);
                return countA - countB;
            });
            return partMatchedAdjs[0].diff;
        }
        return 0; // 해당 부제에 맞는 규칙이 지정되어 있지 않으면 가감 적용 안 함
    }

    return matchedAdjs[0].diff;
}

function parseDiffValue(valStr) {
    if (!valStr) return null;
    const clean = valStr.toString().trim().replace(/만원|만/g, '').replace(/\s+/g, '');
    const val = parseFloat(clean);
    if (isNaN(val) || val === 0) return null;
    return val;
}

function parsePartsFromText(text) {
    if (!text) return null;
    let hasP1 = false, hasP2 = false, hasP3 = false;
    let hasExplicit = false;

    // 1~2부, 1-2부, 1,2부, 1+2부, 1/2부, 1부2부
    if (/1\s*[-~,+/]\s*2\s*부|1부\s*[,+/~-]?\s*2부/.test(text)) {
        hasP1 = true;
        hasP2 = true;
        hasExplicit = true;
    }
    // 2~3부, 2-3부, 2,3부, 2+3부, 2/3부
    if (/2\s*[-~,+/]\s*3\s*부|2부\s*[,+/~-]?\s*3부/.test(text)) {
        hasP2 = true;
        hasP3 = true;
        hasExplicit = true;
    }
    // 1~3부, 1-3부, 전부, 전타임, 전체
    if (/1\s*[-~,+/]\s*3\s*부|전부|전타임|전체/.test(text)) {
        hasP1 = true;
        hasP2 = true;
        hasP3 = true;
        hasExplicit = true;
    }

    if (!hasExplicit) {
        if (/1부/.test(text)) { hasP1 = true; hasExplicit = true; }
        if (/2부/.test(text)) { hasP2 = true; hasExplicit = true; }
        if (/3부/.test(text)) { hasP3 = true; hasExplicit = true; }
    } else {
        if (/3부/.test(text) && !hasP3) hasP3 = true;
        if (/1부/.test(text) && !hasP1) hasP1 = true;
        if (/2부/.test(text) && !hasP2) hasP2 = true;
    }

    return hasExplicit ? { hasPart1: hasP1, hasPart2: hasP2, hasPart3: hasP3 } : null;
}

function parseCoursePriceAdjustmentLine(line, fallbackCourse = '') {
    if (!line || !line.trim()) return null;
    const trimmed = line.trim();

    // 부제(1부, 2부, 3부) 감지
    const partsInfo = parsePartsFromText(trimmed);
    const hasPart1 = partsInfo ? partsInfo.hasPart1 : true;
    const hasPart2 = partsInfo ? partsInfo.hasPart2 : true;
    const hasPart3 = partsInfo ? partsInfo.hasPart3 : true;

    // 금액(가감) 추출 (예: -2만, -2, +1만, +1, 2)
    const diffMatch = trimmed.match(/(?:[:=,]|\s|^)\s*([+-]?\s*\d+(?:\.\d+)?)\s*(?:만|만원)?(?:\s*$|\s*[)\]])/);
    if (!diffMatch) return null;

    const diffVal = parseFloat(diffMatch[1].replace(/\s+/g, ''));
    if (isNaN(diffVal) || diffVal === 0) return null;

    // 구장명 추출
    let courseCand = trimmed
        .replace(diffMatch[0], '')
        .replace(/1\s*[-~,+/]\s*[23]\s*부|2\s*[-~,+/]\s*3\s*부|[1-3]부|전부|전타임|전체/g, '')
        .replace(/^[●■□★◆▶▷*#•\-\s]+/g, '')
        .replace(/(?:연동가|연동|할인|인하|특가|요금|단가|그린피|적용|추가|가감)/g, '')
        .replace(/[\(\)\[\]:=-]/g, '')
        .trim();

    const course = courseCand || fallbackCourse;
    if (!course) return null;

    return {
        course,
        diff: diffVal,
        hasPart1,
        hasPart2,
        hasPart3
    };
}

// 토스트 메시지
function showToast(msg) {
    const toast = document.getElementById('toast');
    if (!toast) return;
    toast.innerText = msg;
    toast.classList.add('show');
    setTimeout(() => toast.classList.remove('show'), 2000);
}

/**
 * 골프장명을 기반으로 9대 표준 지역 추론
 */
function inferRegionFromGolfName(golfName = '') {
    if (!golfName || typeof golfName !== 'string') return '';
    const name = golfName.trim();
    if (!name) return '';

    // 경기동부 구장
    if (name.match(/해솔리아|써닝포인트|이포|양지파인|캐슬렉스|블랙스톤|루트52/i)) return '경기동부';

    // 인천경인 구장
    if (name.match(/인천경인|인천|경인|영종|강화|시흥|아세코|베르힐|솔트베이|드림파크|클럽72|유니아일랜드|인서울|더헤븐|오렌지듄스|김포비공개|골프존.*송도|베어즈베스트/i)) return '인천경인';

    // 경기북부 구장
    if (name.match(/경기북부|파주|포천|양주|동두천|가평|연천|구리|남양주|고양|일산|스마트|한림광릉|광릉|포레스트힐|리앤리|베어크리크|서원밸리|서원힐스|송추|타이거|자유로|참밸리|몽베르|일동레이크|필로스|락가든|레이크우드|샴발라|아도니스|푸른솔포천|티클라우드/i)) return '경기북부';

    // 충청 구장
    if (name.match(/충청|충남|충북|대전|세종|진천|음성|감곡|화랑|천안|아산|당진|서산|태안|보령|공주|논산|청주|충주|제천|단양|괴산|로얄링스|솔라고|대영베이스|대영힐스|플라밍고|세일|중원|임페리얼|킹스데일|속리산|떼제베|그랜드|백제|우정힐스|버디원|아름다운|골프존.*(?:진천|화랑|천안)|클럽디보은|클럽디속리산|마론뉴데이|골든베이|프린세스/i)) return '충청';

    // 강원 구장
    if (name.match(/강원|춘천|원주|강릉|홍천|횡성|벨라스톤|로드힐스|라비에벨|스프링베일|클럽모우|샤인데일|카스카디아|남춘천|라데나|더플레이어스|파가니카|휘슬링락|옥스필드|센추리21|오크밸리|오크크릭|성문안|하이원|블랙밸리|파인리즈|알펜시아|용평|버치힐|샌드파인|메이플비치|설악썬밸리|플라자설악/i)) return '강원';

    // 전라 구장
    if (name.match(/전라|전남|전북|익산|군산|전주|나주|순천|여수|목포|담양|화순|스톤비치|골프존.*순천/i)) return '전라';

    // 경상 구장
    if (name.match(/경상|경남|경북|부산|대구|울산|창원|포항|구미|경주|김천|안동|엠스클럽|클럽디거창/i)) return '경상';

    // 제주 구장
    if (name.match(/제주|서귀포|라온|엘리시안제주|블랙스톤제주|테디밸리|세인트포|핀크스/i)) return '제주';

    // 경기남부 구장 (위 구장들 제외한 나머지 경기권 구장들)
    if (name.match(/경기남부|여주|안성|이천|용인|화성|오산|평택|수원|성남|광주|양평|과천|의왕|군포|안산|안양|세라지오|아리지|사우스스프링스|소피아그린|세현|한원|지산|태광|남여주|자유|리베라|기흥|코리아|골드|골프존.*안성|안성Q|안성W|안성베네스트|360도|신안|화성상록|아시아나|은화삼|비에이비스타|뉴스프링빌|이천마이다스|웰링턴|페럼|금강|솔모로|더반|빅토리아|발리오스|한림용인|플라자용인|진양밸리|윈체스트/i)) return '경기남부';

    return '';
}

// 지역 추출 함수 (매핑사전 1순위, 9대 표준 지역 엄격 보장)
function getRegion(regionCandidate, golfName = '') {
    // 1. 전달받은 지역 후보 정규화 시도
    if (regionCandidate) {
        const std = toStandardRegion(String(regionCandidate));
        if (std && VALID_STANDARD_REGIONS.includes(std)) {
            return std;
        }
    }

    // 2. 골프장명에서 표준 지역 추론 시도
    if (golfName) {
        const inferred = inferRegionFromGolfName(String(golfName));
        if (inferred && VALID_STANDARD_REGIONS.includes(inferred)) {
            return inferred;
        }
    }

    // 3. 만약 후보 텍스트에 일부 키워드가 남아있을 경우 fallback 검사
    if (regionCandidate) {
        const reg = String(regionCandidate);
        if (reg.includes('동부')) return '경기동부';
        if (reg.includes('경인') || reg.includes('인천')) return '인천경인';
        if (reg.includes('북부') || reg.includes('북')) return '경기북부';
        if (reg.includes('남부') || reg.includes('남') || reg.includes('경기')) return '경기남부';
        if (reg.includes('충청') || reg.includes('충')) return '충청';
        if (reg.includes('강원')) return '강원';
        if (reg.includes('전라') || reg.includes('전')) return '전라';
        if (reg.includes('경상') || reg.includes('경')) return '경상';
        if (reg.includes('제주')) return '제주';
    }

    // 4. 최종 기본값은 '경기남부' (9대 표준 지역 외의 값 절대 반환 금지)
    return '경기남부';
}

function getMappedName(originalName, site = 'golfmon') {
    if (!originalName) {
        return { name: '', region: '', golfmon: '', golfpang: '', golmarket: '', golfrock: '', mapped: false };
    }
    const cleanOrig = String(originalName).trim();

    // 1. 완전 일치 (Exact Match)
    let matchedKey = null;
    if (dictionary && dictionary[cleanOrig]) {
        matchedKey = cleanOrig;
    }

    // 2. 공백/특수문자/괄호 제거 정규화 일치
    if (!matchedKey && dictionary && typeof dictionary === 'object') {
        const normOrig = cleanOrig.replace(/[\s\-_()\[\]]/g, '').toLowerCase();
        const noParenOrig = cleanOrig.replace(/\(.*?\)|\[.*?\]/g, '').replace(/[\s\-_]/g, '').toLowerCase();
        const noParenNoCcOrig = noParenOrig.replace(/(?:cc|gc|골프클럽|골프장)$/i, '');

        // 2-1. 공백 제거 후 완전 일치
        for (const k of Object.keys(dictionary)) {
            const normK = k.replace(/[\s\-_()\[\]]/g, '').toLowerCase();
            if (normK === normOrig) {
                matchedKey = k;
                break;
            }
        }

        // 2-1-b. 동일 구장 내 코스 세부 일치 (예: '떼제베(한울)' -> '떼제베(한울/마루)', '클럽72(하늘)' -> '클럽72(하늘/원더)')
        if (!matchedKey && normOrig.length >= 3) {
            for (const k of Object.keys(dictionary)) {
                const normK = k.replace(/[\s\-_()\[\]]/g, '').toLowerCase();
                const noParenNoCcK = k.replace(/\(.*?\)|\[.*?\]/g, '').replace(/[\s\-_]/g, '').replace(/(?:cc|gc|골프클럽|골프장)$/i, '').toLowerCase();
                if (noParenNoCcK && noParenNoCcOrig && (noParenNoCcK === noParenNoCcOrig || noParenNoCcK.startsWith(noParenNoCcOrig) || noParenNoCcOrig.startsWith(noParenNoCcK))) {
                    if (normK.includes(normOrig) || normOrig.includes(normK)) {
                        matchedKey = k;
                        break;
                    }
                }
            }
        }

        // 2-2. 괄호 및 cc 제거 후 일치 (예: '알펜시아700' <=> '알펜시아700(대관령)', '남양주cc' <=> '남양주(9홀)')
        if (!matchedKey) {
            for (const k of Object.keys(dictionary)) {
                const noParenK = k.replace(/\(.*?\)|\[.*?\]/g, '').replace(/[\s\-_]/g, '').toLowerCase();
                const noParenNoCcK = noParenK.replace(/(?:cc|gc|골프클럽|골프장)$/i, '');
                if (noParenNoCcK && noParenNoCcOrig && (noParenNoCcK === noParenNoCcOrig || noParenK === noParenOrig)) {
                    matchedKey = k;
                    break;
                }
            }
        }

        // 2-3. 전방 일치 또는 포함 일치 (예: '클럽72' in '클럽72(하늘/원더/바다/클래식)', '엠스클럽 의성' in '엠스클럽의성')
        if (!matchedKey && noParenNoCcOrig.length >= 2) {
            for (const k of Object.keys(dictionary)) {
                const noParenNoCcK = k.replace(/\(.*?\)|\[.*?\]/g, '').replace(/[\s\-_]/g, '').replace(/(?:cc|gc|골프클럽|골프장)$/i, '').toLowerCase();
                if (noParenNoCcK && (noParenNoCcK.startsWith(noParenNoCcOrig) || noParenNoCcOrig.startsWith(noParenNoCcK) || noParenNoCcK.includes(noParenNoCcOrig) || noParenNoCcOrig.includes(noParenNoCcK))) {
                    matchedKey = k;
                    break;
                }
            }
        }
    }

    if (matchedKey && dictionary[matchedKey]) {
        const item = normalizeDictEntry(dictionary[matchedKey], matchedKey);
        let siteName = item.golfmon;
        if (site === 'golmarket') siteName = item.golmarket;
        else if (site === 'golfpang') siteName = item.golfpang;
        else if (site === 'golfrock') siteName = item.golfrock;
        return {
            name: siteName || item.name || cleanOrig,
            region: item.region || '',
            golfmon: item.golfmon || cleanOrig,
            golfpang: item.golfpang || cleanOrig,
            golmarket: item.golmarket || getGolmarketGolfName(cleanOrig) || cleanOrig,
            golfrock: item.golfrock || cleanOrig,
            mapped: true
        };
    }

    const defGolmarket = getGolmarketGolfName(cleanOrig) || cleanOrig;
    let siteName = cleanOrig;
    if (site === 'golmarket') siteName = defGolmarket;
    return {
        name: siteName,
        region: '',
        golfmon: cleanOrig,
        golfpang: cleanOrig,
        golmarket: defGolmarket,
        golfrock: cleanOrig,
        mapped: false
    };
}

// 선택 항목 카운트 및 AdGuard 스타일 히어로 갱신
function updateSelectedBadge() {
    const selectedCount = document.querySelectorAll('#dataTable tbody tr.selected').length;
    const totalCount = document.querySelectorAll('#dataTable tbody tr').length;
    
    const badge = document.getElementById('selectedCountBadge');
    if (badge) badge.innerText = `${selectedCount}건`;

    const heroSel = document.getElementById('heroSelectedCount');
    const heroStatus = document.getElementById('heroStatusText');
    const heroTotal = document.getElementById('heroTotalCountText');
    const tabCount = document.getElementById('tabCount');

    if (heroSel) heroSel.innerText = selectedCount;
    if (heroStatus) {
        if (totalCount === 0) {
            heroStatus.innerHTML = `대기 중: <span class="count-num">0</span>개`;
        } else {
            heroStatus.innerHTML = `선택: <span class="count-num">${selectedCount}</span>개`;
        }
    }
    if (heroTotal) {
        if (totalCount === 0) {
            heroTotal.innerText = '텍스트를 붙여넣고 매크로를 실행하세요';
        } else {
            heroTotal.innerText = `총 ${totalCount}건 변환됨 (자동 ${selectedCount}건 선택)`;
        }
    }
    if (tabCount) tabCount.innerText = totalCount;

    // 전체선택 / 전체해제 마스터 체크박스 동기화
    const chkSelectAll = document.getElementById('chkSelectAll');
    const textCheckAll = document.getElementById('textCheckAll');
    if (chkSelectAll) {
        if (totalCount === 0) {
            chkSelectAll.checked = false;
            chkSelectAll.indeterminate = false;
            if (textCheckAll) textCheckAll.innerText = '전체선택';
        } else if (selectedCount === totalCount) {
            chkSelectAll.checked = true;
            chkSelectAll.indeterminate = false;
            if (textCheckAll) textCheckAll.innerText = '전체해제';
        } else if (selectedCount === 0) {
            chkSelectAll.checked = false;
            chkSelectAll.indeterminate = false;
            if (textCheckAll) textCheckAll.innerText = '전체선택';
        } else {
            chkSelectAll.checked = false;
            chkSelectAll.indeterminate = true;
            if (textCheckAll) textCheckAll.innerText = '전체해제';
        }
    }

    // 골마켓 등록 버튼 라벨 동적 갱신 (조인용 원클릭 vs 양도용 원클릭)
    const btnGolfmarket = document.getElementById('btnRegisterToGolfmarket');
    if (btnGolfmarket) {
        const isTransferMode = (lastUsedMacroType === 'transfer') ||
            Array.from(document.querySelectorAll('#dataTable tbody tr.selected')).some(tr => tr.dataset.roomType === '양도');
        const spanEl = btnGolfmarket.querySelector('span');
        if (spanEl) {
            spanEl.innerText = totalCount === 0 ? '골마켓 자동등록' : (isTransferMode ? '골마켓 부킹등록' : '골마켓 조인등록');
        }
    }

    // 선택 선티 지정 버튼 라벨 동적 갱신
    const textBatchSeonti = document.getElementById('textBatchSeonti');
    if (textBatchSeonti) {
        const selectedTrs = Array.from(document.querySelectorAll('#dataTable tbody tr.selected'));
        if (selectedTrs.length > 0 && selectedTrs.every(tr => tr.dataset.isSeontiOrDaegi === 'true' || (tr.dataset.roomType || '').includes('선티'))) {
            textBatchSeonti.innerText = '선택 선티해제';
        } else {
            textBatchSeonti.innerText = '선택 선티지정';
        }
    }
}

// 전체체크 / 전체해제 토글 함수
function handleToggleSelectAll() {
    const trs = Array.from(document.querySelectorAll('#dataTable tbody tr'));
    if (trs.length === 0) {
        showToast('선택할 티타임이 없습니다.');
        return;
    }
    const selectedCount = document.querySelectorAll('#dataTable tbody tr.selected').length;
    // 1개라도 선택되어 있으면 전체 해제, 모두 해제되어 있으면 전체 선택
    const targetState = (selectedCount === 0);

    trs.forEach(tr => {
        tr.classList.toggle('selected', targetState);
    });

    syncCardsSelection();
    updateSelectedBadge();
    saveCurrentTableState();

    if (targetState) {
        showToast(`전체 ${trs.length}건이 선택되었습니다.`);
    } else {
        showToast('전체 선택이 해제되었습니다.');
    }
}

// ==========================================
// 비-골프 라인 및 비-그린피 식음/이벤트 공지 필터링 함수군
// ==========================================

// HTML 속성 인젝션 방지 및 특수문자 안전 인코딩
function escapeAttr(str) {
    if (!str) return '';
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;');
}

// 매핑사전에 잘못 등록된 비정상/쓰레기 키 판별 함수 (-, ■, (공지), 【2부】, 13:35분 등)
function isJunkDictKey(key) {
    if (!key || typeof key !== 'string') return true;
    const s = key.trim();
    if (!s) return true;
    // 1. 단일 특수기호 또는 기호만으로 이루어진 경우 (예: "-", "■", "□", "★", "●", "◆", "▶", "·", "#")
    if (/^[-*•·■□▲▼▶▷★●◆#※~_=:;\/\\|+.,!?@^&`'"()[\]{}]+$/.test(s)) return true;
    // 2. 시간 형식만 있는 경우 (예: "13:35분", "13:35", "07:00")
    if (/^\d{1,2}:\d{2}(?:분)?$/.test(s)) return true;
    // 3. 단독 공지/안내/부제 태그 (예: "(공지)", "[공지]", "【2부】", "【1부】", "[3부]")
    if (/^[(\[【{<](?:공지|안내|필독|알림|전체|1부|2부|3부|주중|주말)[)\]】}>]$/i.test(s)) return true;
    // 4. 일반적인 비-골프 안내 라인
    if (isNonGolfLine(s)) return true;
    return false;
}

// 골프 티타임 데이터가 아닌 공지/이벤트/인사말/식음 안내 라인 판별
function isNonGolfLine(line) {
    if (!line || typeof line !== 'string') return false;
    const s = line.trim();
    if (!s) return false;

    // 0. 단일 특수기호 또는 기호만으로 이루어진 경우 (예: "-", "■", "□", "★", "●", "◆", "▶", "·", "#")
    if (/^[-*•·■□▲▼▶▷★●◆#※~_=:;\/\\|+.,!?@^&`'"()[\]{}]+$/.test(s)) {
        return true;
    }

    // 0-1. 단독 공지/안내/부제 괄호 태그 (예: "(공지)", "[공지]", "【2부】", "【1부】", "[3부]" 등)
    if (/^[(\[【{<](?:공지|안내|필독|알림|전체|1부|2부|3부|주중|주말)[)\]】}>]$/i.test(s)) {
        return true;
    }

    // 0-2. 시간만 단독으로 있는 경우 (예: "13:35분", "13:35")
    if (/^\d{1,2}:\d{2}(?:분)?$/.test(s)) {
        return true;
    }

    // 0-3. 구장명 + 지역 대괄호 패턴이 포함된 라인(예: "-신안(회원제) [경기 안성]", "-그린힐 [경기 광주]")은 절대 비-골프 라인이 아님
    if (/\[(?:경기|강원|충청|경상|전라|제주|인천|서울|동부|서부|남부|북부|충북|충남|경북|경남|전북|전남|[가-힣]{2,4}\s*[가-힣]{2,4})\s*\]/i.test(s)) {
        return false;
    }

    // 0-4. 기호 및 대괄호를 제거한 텍스트가 매핑사전 또는 공인 구장명인 경우 무조건 비-골프 라인이 아님 (예: "신안(회원제)", "신안")
    const candCourse = s.replace(/\[.*?\]/g, '').replace(/^[-*•·■□▲▼▶▷★●◆#※~_=:;\/\\|+.,!?@^&`'"()[\]{}<>\s]+/g, '').trim();
    if (candCourse && (typeof isRecognizedGolfCourse === 'function' && isRecognizedGolfCourse(candCourse))) {
        return false;
    }
    if (candCourse && typeof dictionary !== 'undefined' && dictionary && (dictionary[candCourse] || dictionary[candCourse.replace(/[\s\-_()\[\]]/g, '')])) {
        return false;
    }

    // 1. 단독 요일/시간대 단어 (주중, 주말, 평일, 공휴일 등은 구장명이 아님)
    if (/^(?:주중|주말|평일|공휴일)$/i.test(s)) {
        return true;
    }

    // 2. 인사말 및 알림/종결 표현
    if (/^(?:안녕|반갑|감사|수고|좋은\s*하루|공지|안내|필독|알림|전달)/i.test(s) || 
        /(?:안녕하세요|안녕하십니까|반갑습니다|감사합니다|수고하세요|부탁드립니다|진행합니다|안내드립니다|환영합니다|바랍니다)[!~.]*$/i.test(s)) {
        return true;
    }

    // 3. 이벤트 / 식음 / 패키지 안내 문구 (브런치, 모닝박스, 샌드위치 등 그린피 무관 식음/행사)
    if (/(?:브런치\s*박스|모닝\s*박스|브런치|모닝박스|샌드위치|베이커리|토스트|커피\s*리필|식음|조식\s*패키지|식사\s*제공|음료\s*제공|사은품|경품|기념품|이벤트\s*진행)/i.test(s)) {
        return true;
    }

    // 4. 안내 조건 / 주의사항 / 비고 라인 (※, *, #, •, · 등으로 시작하거나 특수 안내 문구)
    if (/^[※*#•·\-]/.test(s)) {
        if (/내장|티업|한정|필수|별도|중복|변경|제외|적용|우천|기예약|비고|회원(?!제)|비회원|운영|카트피|캐디피|그린피|메뉴|구성/i.test(s)) {
            return true;
        }
    }

    // 5. 이벤트 패키지 가격 / 구성 라인 (예: "그린피 + 브런치 박스", "브런치박스 구성 : 샌드위치 + 커피", "1인 150,000원")
    if (/그린피\s*\+\s*/i.test(s) || /구성\s*:\s*/i.test(s) || /^1인\s*([0-9.,]+)\s*(?:만|만원|원)?$/i.test(s)) {
        return true;
    }

    // 6. 날짜 기간 범위 (예: "10/26(월)~10/29(목)", "10/18 ~ 10/22", "기간: 10/18 ~ 10/22") - 단일 티타임 날짜가 아닌 기간
    if (/(\d{1,2})[./\-](\d{1,2}).*?[~-].*?(\d{1,2})[./\-](\d{1,2})/.test(s)) {
        return true;
    }

    // 7. 티업 조건 문구 (예: "주중 07:30 이전 티업 고객", "07:30 이전 내장객", "07:30 이전 티업")
    if (/\d{1,2}:\d{2}\s*(?:이전|이후|경|쯤|대)\s*(?:티업|내장|고객|예약)/i.test(s) || 
        /(?:티업\s*고객|내장객\s*한정|내장\s*필수|이벤트\s*중복)/i.test(s)) {
        return true;
    }

    return false;
}

// 그린피와 무관한 식음/브런치/모닝박스/이벤트 공지인지 판별
function isNonGreenFeeEventNotice(text) {
    if (!text || typeof text !== 'string') return false;

    // 1. 식음 / 식사 / 음료 / 패키지 / 기념품 / 이벤트 관련 대표 키워드
    const eventMealKeywords = /(?:브런치|모닝박스|샌드위치|베이커리|토스트|조식|식음|식사|중식|석식|커피\s*리필|커피\s*(?:제공|증정|무료)|음료\s*(?:제공|증정|무료)|생맥주|안주|치킨|피자|레스토랑|그늘집|사은품|경품|기념품|선물\s*증정|골프공\s*증정|볼\s*증정|홀인원\s*이벤트|모닝박스\s*이벤트|식음\s*이벤트|패키지\s*이벤트|이벤트\s*진행)/i;

    if (!eventMealKeywords.test(text)) return false;

    // 2. 실제 그린피 할인/인하(시간대별/기간별 할인)가 명시되어 있는지 확인
    const hasRealGreenFeeCut = /(?:금액\s*인하|부분선결제\s*금액\s*인하|추가\s*\d+만?\s*할인|\d+만\s*(?:원)?\s*(?:추가\s*)?할인|\d+만\s*DC|\b\d{1,2}:\d{2}\s*(?:~|-)\s*\d{1,2}:\d{2}\s*[-:=])/i.test(text);

    // 실제 그린피 인하/할인 규정이 없는 순수 식음/이벤트/패키지 공지인 경우 제외
    if (!hasRealGreenFeeCut) {
        return true;
    }

    // 만약 "그린피 + 브런치" 형태의 단순 패키지 가격 제시이고, 실제 할인(인하/DC) 단어가 없는 경우
    if (/그린피\s*\+\s*(?:브런치|식사|조식|모닝박스)/i.test(text) && !/할인|인하|DC/i.test(text)) {
        return true;
    }

    return false;
}

// ==========================================
// 구장 공지 금액 자동 조정 관련 함수군
// ==========================================

// 구장명이 될 수 없는 부제, 마감, 날짜, 요일, 일반 명사 필터
function isNonCourseWord(word) {
    if (!word || typeof word !== 'string') return true;
    const s = word.replace(/[\[\]\(\)\*#※■□▣◆◇▲▼▶▷◀◁●○★☆【】<>~_=\-]/g, '').trim();
    if (!s) return true;

    // 1. 부제 관련 (1부, 2부, 3부, 4부, 전부, 전타임, 1부제, 2부제, 3부제, 1부타임 등)
    if (/^[1-4]부(?:제|타임)?$/i.test(s) || /^(?:전부|전타임|야간|주간|새벽|오전|오후|주중|주말|평일|공휴일)$/i.test(s) || /[1-4]부/i.test(s)) {
        return true;
    }

    // 2. 당일 / 마감 / 종료 / 임박 / 특가 관련 (예: "당일3부 마감", "당일마감", "특가")
    if (/^(?:당일|마감|종료|완료|임박|특가|특가요금|할인|인하|잔여|잔여타임|잔여마감|당일마감)$/i.test(s) ||
        /당일\s*[1-4]부/i.test(s) || /.*마감$/i.test(s) || /(?:마감|종료|특가)/i.test(s)) {
        return true;
    }

    // 3. 날짜 및 요일 패턴 (예: "22화", "22(화)", "22일", "10/18", "10.18", "18일", "월요일", "화", "수")
    if (/^\d{1,2}\s*(?:일|일자)?\s*(?:\([가-힣\w]+\)|[월화수목금토일])?$/i.test(s) ||
        /^\d{1,2}\s*[./\-]\s*\d{1,2}/.test(s) ||
        /^\d{1,2}\s*[월화수목금토일]$/i.test(s) ||
        /^(?:월|화|수|목|금|토|일)(?:요일)?$/i.test(s)) {
        return true;
    }

    // 4. 시간 패턴 (예: "6시대", "6시", "07:04", "13:35분")
    if (/^\d{1,2}\s*(?:시대|시\s*대|시타임|시)$/i.test(s) || /^\d{1,2}:\d{2}/.test(s)) {
        return true;
    }

    // 5. 금액 패턴 (예: "8만", "8만원", "70000", "70,000", "12만")
    if (/^[0-9.,]+\s*(?:만|만원|원)?$/i.test(s)) {
        return true;
    }

    // 6. 카카오톡/안내/일반 명사 (예: 댓글, 사진, 스타, 스타트, 대리, 팀장 등)
    if (/^(?:댓글|사진|동영상|파일|안현희대리|대리|팀장|매니저|실장|담당자|골프락|공지|안내|필독|알림|전송|발송|작성|문의|요청|진행|감사|부탁|예약|취소|모집|확정|스타|스타트)$/i.test(s) ||
        /(?:골프락|안현희대리|안현희|대리에게|댓글|사진|동영상|첨부파일|카카오톡)/i.test(s)) {
        return true;
    }

    // 7. 인원/조인 관련 (예: 1인, 대기, 조인, 선입, 현장 등)
    if (/^(?:\d+인|대기|대기중|조인|양도|선입|선입금|선결제|현장|현장결제|그린피|카트피|캐디피|노캐디)$/i.test(s)) {
        return true;
    }

    // 8. 인사말 및 공지 일반 문구
    if (/(?:안녕하세요|반갑습니다|감사합니다|부탁드립니다|확인바랍니다)/i.test(s)) {
        return true;
    }

    return false;
}

// 매핑사전 또는 현재 테이블에 실제 등록된 공인 골프장인지 확인
function isRecognizedGolfCourse(name) {
    if (!name || isNonCourseWord(name)) return false;
    const clean = String(name).trim();
    if (/(?:cc|gc|골프장|골프클럽|컨트리클럽|컨트리|c\.c|g\.c)$/i.test(clean)) return true;
    const norm = clean.replace(/[\s\-_\[\]\(\)]|cc|gc|골프장|골프클럽/gi, '').toLowerCase();
    if (!norm || norm.length < 2) return false;

    // 1. 매핑사전 검사
    const dictSource = (typeof dictionary !== 'undefined' && dictionary && Object.keys(dictionary).length > 0)
        ? dictionary
        : (typeof defaultDict !== 'undefined' ? defaultDict : {});
    for (const [k, v] of Object.entries(dictSource)) {
        const nk = k.replace(/[\s\-_\[\]\(\)]|cc|gc|골프장|골프클럽/gi, '').toLowerCase();
        const nt = (typeof v === 'string' ? v : (v?.name || v?.golfmon || '')).replace(/[\s\-_\[\]\(\)]|cc|gc|골프장|골프클럽/gi, '').toLowerCase();
        if (norm === nk || norm === nt || nk.includes(norm) || nt.includes(norm)) return true;
    }

    // 2. 현재 테이블 검사
    const tableRows = document.querySelectorAll('#dataTable tbody tr');
    for (const tr of tableRows) {
        const g = tr.cells[2]?.textContent.trim();
        const ng = (g || '').replace(/[\s\-_\[\]\(\)]|cc|gc|골프장|골프클럽/gi, '').toLowerCase();
        if (ng && (norm === ng || ng.includes(norm))) return true;
    }

    return false;
}

// HH:MM 형식 또는 한국어 시간("7시", "7시30분", "18시30분") 또는 4자리(0546)/3자리 숫자 형식 시간을 분(0~1440) 단위 정수로 변환
function timeToMinutes(tStr) {
    if (!tStr) return 0;
    const s = String(tStr).trim();
    if (s.includes(':')) {
        const parts = s.split(':');
        const h = parseInt(parts[0], 10) || 0;
        const m = parseInt(parts[1], 10) || 0;
        return h * 60 + m;
    }
    // "7시 30분", "7시30분", "7시", "18시30분"
    const mKor = s.match(/(\d{1,2})\s*시(?:\s*(\d{1,2})\s*분?)?/);
    if (mKor) {
        const h = parseInt(mKor[1], 10) || 0;
        const m = mKor[2] ? (parseInt(mKor[2], 10) || 0) : 0;
        return h * 60 + m;
    }
    const digits = s.replace(/\D/g, '');
    if (digits.length === 4) {
        const h = parseInt(digits.substring(0, 2), 10) || 0;
        const m = parseInt(digits.substring(2, 4), 10) || 0;
        return h * 60 + m;
    } else if (digits.length === 3) {
        const h = parseInt(digits.substring(0, 1), 10) || 0;
        const m = parseInt(digits.substring(1, 3), 10) || 0;
        return h * 60 + m;
    }
    return 0;
}

// 공지 금액 문자열(10.9, 10.9만, 109,000, 109000, 10 등)을 만 단위 float 숫자로 정규화
function normalizeNoticePrice(str) {
    if (!str) return null;
    let s = str.replace(/[,원만!~:]/g, '').trim();
    let val = parseFloat(s);
    if (isNaN(val)) return null;
    // 10000원 이상(예: 109000 -> 10.9)으로 입력된 경우 만 단위로 자동 환산
    if (val >= 10000) {
        val = Math.round((val / 10000) * 100) / 100;
    }
    return val;
}

// 공지 날짜 상세 파싱 (연도, 월, 일 포함 객체 반환)
function parseNoticeDateDetail(line, fallbackMonth = null) {
    if (!line) return null;
    let m = line.match(/(?:(\d{4}|\d{2})\s*년\s*)?(\d{1,2})\s*월\s*(\d{1,2})\s*일?/);
    if (m) {
        const y = m[1] ? (m[1].length === 2 ? 2000 + parseInt(m[1], 10) : parseInt(m[1], 10)) : null;
        const month = parseInt(m[2], 10);
        const day = parseInt(m[3], 10);
        return {
            dateStr: `${month}.${day}`,
            year: y,
            month,
            day
        };
    }
    m = line.match(/(?:^|[^\d])(?:(\d{4}|\d{2})\s*[./\-]\s*)?(\d{1,2})[./\-](\d{1,2})(?:$|[^\d])/);
    if (m) {
        const y = m[1] ? (m[1].length === 2 ? 2000 + parseInt(m[1], 10) : parseInt(m[1], 10)) : null;
        const month = parseInt(m[2], 10);
        const day = parseInt(m[3], 10);
        return {
            dateStr: `${month}.${day}`,
            year: y,
            month,
            day
        };
    }
    // "22화", "22(화)", "22일(화)", "18일" 등 일자+요일 단독 라인 대응
    const mDayOnly = line.trim().match(/^[-*•▶▷□■▣★☆◆◇▲▼\s]*(\d{1,2})\s*(?:일)?\s*(?:\(([월화수목금토일])\)|([월화수목금토일]))?(?:요일)?\s*$/);
    if (mDayOnly) {
        const day = parseInt(mDayOnly[1], 10);
        if (day >= 1 && day <= 31) {
            const now = new Date();
            const month = fallbackMonth || (now.getMonth() + 1);
            return {
                dateStr: `${month}.${day}`,
                year: now.getFullYear(),
                month,
                day
            };
        }
    }
    return null;
}

/// 공지 텍스트 내 단일 날짜 감지 (예: "10월 18일(일)", "10/18", "10.18", "10-18") -> "10.18"
function parseNoticeDate(line) {
    const detail = parseNoticeDateDetail(line);
    return detail ? detail.dateStr : null;
}

// 공지 텍스트 내 기간 범위 감지 (예: "기간: 10/18(일) ~ 10/22(목) [5일간]", "10.18 ~ 10.22", "10월 18일 ~ 10월 22일", "2026.10.18 ~ 2026.10.22")
function parseNoticeDateRange(line) {
    if (!line) return null;
    const m1 = line.match(/(?:(\d{4}|\d{2})\s*[년./\-]\s*)?(\d{1,2})\s*[월./\-]\s*(\d{1,2})\s*(?:일)?(?:\([가-힣\w]+\))?\s*(?:~|-|부터)\s*(?:(\d{4}|\d{2})\s*[년./\-]\s*)?(\d{1,2})\s*[월./\-]\s*(\d{1,2})\s*(?:일)?(?:\([가-힣\w]+\))?/);
    if (m1) {
        const startY = m1[1] ? (m1[1].length === 2 ? 2000 + parseInt(m1[1], 10) : parseInt(m1[1], 10)) : null;
        const startM = parseInt(m1[2], 10);
        const startD = parseInt(m1[3], 10);
        const endY = m1[4] ? (m1[4].length === 2 ? 2000 + parseInt(m1[4], 10) : parseInt(m1[4], 10)) : startY;
        const endM = parseInt(m1[5], 10);
        const endD = parseInt(m1[6], 10);
        return {
            startDate: `${startM}.${startD}`,
            endDate: `${endM}.${endD}`,
            startYear: startY,
            endYear: endY,
            startM, startD, endM, endD,
            text: `${startM}.${startD}~${endM}.${endD}`
        };
    }
    const m2 = line.match(/(?:(\d{4}|\d{2})\s*년\s*)?(\d{1,2})\s*월\s*(\d{1,2})\s*일?(?:\([가-힣\w]+\))?\s*(?:~|-|부터)\s*(\d{1,2})\s*일?(?:\([가-힣\w]+\))?/);
    if (m2) {
        const y = m2[1] ? (m2[1].length === 2 ? 2000 + parseInt(m2[1], 10) : parseInt(m2[1], 10)) : null;
        const startM = parseInt(m2[2], 10);
        const startD = parseInt(m2[3], 10);
        const endD = parseInt(m2[4], 10);
        return {
            startDate: `${startM}.${startD}`,
            endDate: `${startM}.${endD}`,
            startYear: y,
            endYear: y,
            startM, startD, endM: startM, endD,
            text: `${startM}.${startD}~${startM}.${endD}`
        };
    }
    return null;
}

// 특정 티타임 날짜가 공지 날짜 범위에 포함되는지 검사
function isDateInRange(rowDate, dateRange) {
    if (!dateRange) return true;
    const parts = String(rowDate || '').replace(/[^\d.]/g, '').split('.');
    if (parts.length < 2) return false;
    const rowM = parseInt(parts[0], 10);
    const rowD = parseInt(parts[1], 10);
    if (isNaN(rowM) || isNaN(rowD)) return false;

    const rowVal = rowM * 100 + rowD;
    const startVal = dateRange.startM * 100 + dateRange.startD;
    const endVal = dateRange.endM * 100 + dateRange.endD;

    if (startVal <= endVal) {
        return rowVal >= startVal && rowVal <= endVal;
    } else {
        // 연말/연초 걸침 (예: 12.28 ~ 1.5)
        return rowVal >= startVal || rowVal <= endVal;
    }
}

// 공지 텍스트 내 할인 금액 파싱 (예: "혜택: 잔여타임 추가 2만 할인", "2만원 할인", "2만 DC")
function parseNoticeDiscount(line) {
    if (!line) return null;
    if (!/할인|인하|차감|DC|혜택|지원|금액\s*인하/i.test(line)) return null;
    if (line.startsWith('*') || line.startsWith('※') || line.includes('비회원') || line.includes('조건부')) return null;

    const m = line.match(/(?:추가\s*)?([0-9.,]+)\s*(?:만|만원|원)?\s*(?:추가\s*)?(?:할인|인하|차감|DC|혜택|지원)/i) ||
              line.match(/(?:할인|인하|혜택|지원)\s*[:=\-]?\s*(?:추가\s*)?([0-9.,]+)\s*(?:만|만원|원)?/i);
    if (m) {
        const val = normalizeNoticePrice(m[1]);
        if (val !== null && val > 0) return val;
    }
    return null;
}

// 공지 텍스트 내 부제(1부, 2부, 3부) 파싱 (예: "[1부+2부] [4인필수]", "1부, 2부")
function parseNoticeParts(line) {
    if (!line) return null;
    if (!/1부|2부|3부|전부|전타임/.test(line)) return null;

    const hasPart1 = /1부|1\s*,\s*2|1\s*\+\s*2|전부|전타임/.test(line);
    const hasPart2 = /2부|1\s*,\s*2|1\s*\+\s*2|전부|전타임/.test(line);
    const hasPart3 = /3부|전부|전타임/.test(line);

    if (hasPart1 || hasPart2 || hasPart3) {
        return {
            hasPart1,
            hasPart2,
            hasPart3,
            desc: [hasPart1 ? '1부' : '', hasPart2 ? '2부' : '', hasPart3 ? '3부' : ''].filter(Boolean).join('+')
        };
    }
    return null;
}

// 티타임 시간이 해당 부제에 속하는지 판별
// 1부: 오전 11시 이전 (< 11:00, < 660분)
// 2부: 오전 11시 ~ 오후 4시 이전 (11:00 <= time < 16:00, 660 <= mins < 960)
// 3부: 오후 4시 이후 (>= 16:00, >= 960분)
function isTimeInPart(timeMins, parts) {
    if (!parts) return true;
    if (!parts.hasPart1 && !parts.hasPart2 && !parts.hasPart3) return true;

    if (timeMins < 660) {
        return Boolean(parts.hasPart1);
    } else if (timeMins < 960) {
        return Boolean(parts.hasPart2);
    } else {
        return Boolean(parts.hasPart3);
    }
}

// 공지 텍스트 라인에서 구장명 식별 (사전, 기존 테이블, 고정/제휴 구장 목록, 단독 라인 기반)
function detectCourseInLine(line) {
    if (!line) return null;

    // 카카오톡 송신자/시간 헤더 제거 (예: "[골프락 안현희대리] [오후 1:52] ▣ 스프링베일GC ▣")
    let raw = line.replace(/^\[[^\]]+\]\s*\[(?:오전|오후)?\s*\d{1,2}:\d{2}\]\s*/, '').trim();
    if (!raw) return null;

    // 장식용 특수기호 및 괄호 제거
    const clean = raw.replace(/[\[\]\(\)\*#※■□▣◆◇▲▼▶▷◀◁●○★☆【】<>~_=\-]/g, '').trim();
    if (!clean) return null;

    // 안내/공지/인사말/식음/이벤트 문구인 경우 스킵
    if (isNonGolfLine(raw) || isNonGolfLine(clean)) return null;

    // 비-구장 단어(부제: 1부/2부/3부, 마감, 날짜, 요일, 일반 명사 등) 엄격 배제!
    if (isNonCourseWord(raw) || isNonCourseWord(clean)) return null;

    // 안내/공지 문구만 있는 경우 스킵
    const isDisclaimer = /^(?:부분선결제|선결제|금액\s*인하|인하|공지|안내|할인|특가|임박|홈페이지|기존예약|적용|참고|필독|기간|혜택|이벤트|프로모션|발송일|작성일|공지일|전송일)/i.test(clean);
    if (isDisclaimer) return null;

    // 1. 현재 화면 테이블에 이미 있는 구장명과 우선 매칭 (대소문자/공백/cc/gc 무시)
    const tableRows = document.querySelectorAll('#dataTable tbody tr');
    for (const tr of tableRows) {
        const golf = tr.cells[2]?.textContent.trim();
        const rawGolf = tr.dataset.rawGolf || '';
        const normGolf = (golf || '').replace(/[\s\-_\[\]\(\)]|cc|gc|골프장|골프클럽/gi, '').toLowerCase();
        const normRaw = (rawGolf || '').replace(/[\s\-_\[\]\(\)]|cc|gc|골프장|골프클럽/gi, '').toLowerCase();
        const normClean = clean.replace(/[\s\-_\[\]\(\)]|cc|gc|골프장|골프클럽/gi, '').toLowerCase();

        if (normGolf && normClean.length >= 2 && (normClean === normGolf || normClean.includes(normGolf) || normGolf.includes(normClean))) return golf;
        if (normRaw && normClean.length >= 2 && (normClean === normRaw || normClean.includes(normRaw) || normRaw.includes(normClean))) return rawGolf;
    }

    // 2. 매핑사전 키 또는 골프몬명 직접 매칭 (dictionary + defaultDict 동시 대응)
    const normClean = clean.replace(/[\s\-_\[\]\(\)]|cc|gc|골프장|골프클럽/gi, '').toLowerCase();
    const dictSource = (typeof dictionary !== 'undefined' && dictionary && Object.keys(dictionary).length > 0)
        ? dictionary
        : (typeof defaultDict !== 'undefined' ? defaultDict : {});

    if (dictSource && typeof dictSource === 'object') {
        for (const [key, val] of Object.entries(dictSource)) {
            const normKey = key.replace(/[\s\-_\[\]\(\)]|cc|gc|골프장|골프클럽/gi, '').toLowerCase();
            const targetName = typeof val === 'string' ? val : (val?.name || val?.golfmon || '');
            const normTarget = targetName.replace(/[\s\-_\[\]\(\)]|cc|gc|골프장|골프클럽/gi, '').toLowerCase();

            if (normKey && normClean.length >= 2 && (normClean === normKey || normClean.includes(normKey) || normKey.includes(normClean))) {
                return key;
            }
            if (normTarget && normClean.length >= 2 && (normClean === normTarget || normClean.includes(normTarget) || normTarget.includes(normClean))) {
                return key;
            }
        }
    }

    // 3. getMappedName(clean) 매핑 검사
    if (typeof getMappedName === 'function') {
        const mapped = getMappedName(clean);
        if (mapped && mapped.mapped && mapped.name) {
            return mapped.name;
        }
    }

    // 4. 고정/제휴 구장명 목록 매칭
    if (typeof fixedGolfs !== 'undefined' && Array.isArray(fixedGolfs)) {
        for (const g of fixedGolfs) {
            const normG = g.replace(/[\s\-_\[\]\(\)]|cc|gc|골프장|골프클럽/gi, '').toLowerCase();
            if (normG && normClean.length >= 2 && (normClean === normG || normClean.includes(normG) || normG.includes(normClean))) return g;
        }
    }
    if (typeof affiliates !== 'undefined' && Array.isArray(affiliates)) {
        for (const g of affiliates) {
            const normG = g.replace(/[\s\-_\[\]\(\)]|cc|gc|골프장|골프클럽/gi, '').toLowerCase();
            if (normG && normClean.length >= 2 && (normClean === normG || normClean.includes(normG) || normG.includes(normClean))) return g;
        }
    }

    // 5. 공백으로 분리된 첫 단어가 구장명인 경우
    const firstWord = clean.split(/[\s\t]/)[0].trim();
    if (firstWord && firstWord.length >= 2 && !isNonCourseWord(firstWord)) {
        if (typeof dictionary !== 'undefined' && dictionary[firstWord]) return firstWord;
        if (typeof fixedGolfs !== 'undefined' && fixedGolfs.includes(firstWord)) return firstWord;
    }

    // 6. 단독 구장명 라인 추정 (접미사 cc/gc/골프클럽이 있거나 헤더 기호로 장식된 경우)
    const isPureNonCourse = /^\d+$/.test(clean) || 
                            /\d{1,2}[:.]\d{2}/.test(clean) || 
                            /\d{1,2}\s*(?:시대|시\s*대|시타임|시)/.test(clean) || 
                            /\d+\s*만(?:원)?/.test(clean) ||
                            /\d{1,2}\s*[월./\-]\s*\d{1,2}/.test(clean);

    const hasCourseSuffix = /(?:cc|gc|골프장|골프클럽|컨트리클럽|컨트리|c\.c|g\.c)$/i.test(clean);
    const hasHeaderDecoration = /^[■▣◆★●▲▼【]/.test(raw);

    if (!isDisclaimer && !isNonGolfLine(clean) && !isPureNonCourse && !isNonCourseWord(clean) &&
        !/(?:기간|혜택|할인|인하|안내|공지|특가|운영|내장|그린피|예약|적용|조건|부제|중복|홀|캐디|회원(?!제)|비회원|안녕|반갑|감사|이벤트|프로모션|브런치|모닝박스|박스|샌드위치|베이커리|커피|식사|조식|식음|사은품|경품|패키지|진행|발송일|작성일|공지일|전송일)/i.test(clean)) {
        if (hasCourseSuffix) {
            if (clean.length >= 2 && clean.length <= 25) {
                return clean;
            }
        } else if (hasHeaderDecoration) {
            if (clean.length >= 2 && clean.length <= 20) {
                return clean;
            }
        } else if (isRecognizedGolfCourse(clean)) {
            // 접미사/기호가 없어도 매핑사전 또는 테이블에 등록된 공인 구장명인 경우만 허용
            return clean;
        }
    }

    return null;
}

// 구장명 일치 판별 함수 (공백 및 특수문자 제거 후 상호 포함 여부 체크)
function isCourseMatch(noticeCourse, rowGolf, rowRawGolf, rowGolfmonGolf) {
    if (!noticeCourse) return true; // 구장명이 지정되지 않은 공지는 전체 구장 대상
    if (isNonCourseWord(noticeCourse)) return false; // 1부, 2부 등 비-구장 단어는 절대 매칭 금지

    const cleanNotice = String(noticeCourse).replace(/[\s\-_\[\]\(\)]|cc|gc|골프장|골프클럽/gi, '').toLowerCase();
    if (!cleanNotice) return true;

    const noticeDigits = cleanNotice.match(/\d+/g)?.join('') || '';

    const targets = [rowGolf, rowRawGolf, rowGolfmonGolf].filter(Boolean).map(g =>
        String(g).replace(/[\s\-_\[\]\(\)]|cc|gc|골프장|골프클럽/gi, '').toLowerCase()
    );

    return targets.some(t => {
        if (!t) return false;
        // (9홀), (P9) 등의 홀수 표기는 비교용 숫자에서 제외하여 순수 구장 번호만 추출
        const cleanT = t.replace(/\(?p?\d+\s*홀\)?|\(?p\d+\)?/gi, '');
        const tDigits = cleanT.match(/\d+/g)?.join('') || '';

        // 숫자가 포함된 구장(알펜시아700, 클럽72, 루트52, 벨라45 등)의 경우 숫자 일치 필수 검사
        if (noticeDigits) {
            if (tDigits !== noticeDigits) return false;
        } else {
            // 공지 구장명에 숫자가 없는데(예: 알펜시아, 알펜시아회원제) 행 구장명에 숫자(예: 알펜시아700)가 있으면 매칭 방지
            if (tDigits && cleanNotice.length <= cleanT.length) {
                if (cleanNotice !== cleanT) return false;
            }
        }
        return t.includes(cleanNotice) || cleanNotice.includes(t);
    });
}

// 날짜 일치 판별 함수 (10.18 vs 10월 18일 vs 10.18(일) 완벽 호환)
function isDateMatch(noticeDate, rowDate) {
    if (!noticeDate) return true; // 날짜가 지정되지 않은 공지는 전체 날짜 대상
    const nMatch = String(noticeDate).match(/(\d{1,2})[./\-](\d{1,2})/);
    const rMatch = String(rowDate || '').match(/(\d{1,2})[./\-](\d{1,2})/);
    if (nMatch && rMatch) {
        return parseInt(nMatch[1], 10) === parseInt(rMatch[1], 10) &&
               parseInt(nMatch[2], 10) === parseInt(rMatch[2], 10);
    }
    const cleanNotice = String(noticeDate).replace(/[\s\-_/]/g, '.');
    const cleanRow = String(rowDate || '').trim().replace(/[\s\-_/]/g, '.');
    return cleanNotice === cleanRow;
}

// 공지 텍스트 파싱 메인 함수 (특정 시간대 지정형 + 기간/부제별 할인형 + 시대별/부제별 타겟 요금 + 동일적용 지시어 완벽 파싱)
function parseNoticeText(text) {
    if (!text || !text.trim()) return [];
    // 그린피와 무관한 식음/브런치/모닝박스/이벤트 공지는 자동 제외
    if (isNonGreenFeeEventNotice(text)) return [];

    const lines = text.split('\n');
    const rules = [];
    const sameAsDirectives = [];

    // ★ 메시지 단위 단일 대표 구장명 사전 탐색 (카톡 공지는 메시지 하나당 한 구장씩 전달됨)
    let primaryCourse = '';
    for (let i = 0; i < lines.length; i++) {
        let l = lines[i].trim();
        if (!l) continue;
        l = l.replace(/^\[[^\]]+\]\s*\[(?:오전|오후)?\s*\d{1,2}:\d{2}\]\s*/, '').trim();
        if (!l) continue;
        const c = detectCourseInLine(l);
        if (c && !isNonCourseWord(c)) {
            primaryCourse = c;
            break;
        }
    }

    let currentCourse = primaryCourse;
    let currentDate = '';
    let currentYear = null;
    let currentDateRange = null;
    let pendingDiscount = null;
    let pendingParts = null;

    function flushPendingDiscount() {
        if (pendingDiscount !== null && pendingDiscount > 0) {
            rules.push({
                type: 'discount',
                course: currentCourse,
                date: currentDate,
                year: currentYear,
                dateRange: currentDateRange,
                discount: pendingDiscount,
                parts: pendingParts,
                rawLine: `${currentCourse} ${currentDateRange ? currentDateRange.text : (currentDate || '')} 추가 ${pendingDiscount}만 할인 ${pendingParts ? pendingParts.desc : ''}`.trim()
            });
            pendingDiscount = null;
            pendingParts = null;
        }
    }

    for (let i = 0; i < lines.length; i++) {
        let line = lines[i].trim();
        if (!line) continue;

        // 카톡 송신자/시간 헤더 제거 (예: "[골프락 안현희대리] [오후 1:52] ▣ 스프링베일GC ▣")
        line = line.replace(/^\[[^\]]+\]\s*\[(?:오전|오후)?\s*\d{1,2}:\d{2}\]\s*/, '').trim();
        if (!line) continue;

        // 0. 카톡 헤더 및 발송일/작성일 스킵
        if (/^(?:-?\s*발송일|-?\s*작성일|-?\s*공지일|-?\s*등록일|-?\s*전송일)\s*[:=]/i.test(line) ||
            /^(?:-?\s*발송일|-?\s*작성일|-?\s*공지일|-?\s*등록일|-?\s*전송일)\s*:\s*\d{1,2}[./\-]\d{1,2}/i.test(line)) {
            continue;
        }

        // 0-1. 공지 안내문 / 특가 안내 헤더 스킵 (예: "잔여타임 특가", "- 잔여 타임 특가 요금 변경 안내 -", "판매 요금 변경 부탁드립니다.")
        if (/(?:잔여\s*타임\s*특가|특가\s*요금\s*변경\s*안내|판매\s*요금\s*변경|홈페이지와\s*별도|기예약건|중복할인불가|적용부탁드립니다)/i.test(line)) {
            continue;
        }

        // 0-2. 요금 변경 없음/제외 라인 스킵 (예: "(8시대, 11시대 요금 변경x)", "요금 변경없음", "적용 제외")
        if (/(?:변경\s*[xX없]|요금\s*변경\s*[xX없]|적용\s*제외|할인\s*제외|기존\s*요금\s*유지)/i.test(line)) {
            continue;
        }

        // 0-3. 동일 적용 지시어 감지 (예: "(14시타임은 13시대와 동일적용)", "14시대는 13시대와 동일", "14시타임 13시대 동일")
        const sameAsMatch = line.match(/(?:^|[(\s])((?:\d{1,2}\s*(?:시|시대|시타임)?\s*[,/& 및~]\s*)*\d{1,2})\s*시(?:대|타임)?(?:은|는)?\s*(\d{1,2})\s*시(?:대|타임)?(?:와|과)?\s*동일/i);
        if (sameAsMatch) {
            const targetRaw = sameAsMatch[1];
            const sourceHour = parseInt(sameAsMatch[2], 10);
            const targetHours = (targetRaw.match(/\d{1,2}/g) || []).map(n => parseInt(n, 10));
            if (targetHours.length > 0 && !isNaN(sourceHour)) {
                targetHours.forEach(th => {
                    sameAsDirectives.push({
                        targetHour: th,
                        sourceHour: sourceHour,
                        course: currentCourse,
                        date: currentDate,
                        year: currentYear,
                        dateRange: currentDateRange,
                        rawLine: line
                    });
                });
            }
            continue;
        }

        // 1. 구장명 라인 감지 (예: "■  알펜시아700골프클럽", "▣ 스프링베일GC ▣")
        const detectedCourse = detectCourseInLine(line);
        if (detectedCourse && !isNonCourseWord(detectedCourse)) {
            // 카톡 공지는 메시지 하나당 단일 구장이므로, 최초 감지된 primaryCourse를 단일 대표 구장으로 고정 (1부, 2부 등 오염 원천 방지)
            if (!primaryCourse) {
                primaryCourse = detectedCourse;
                currentCourse = detectedCourse;
            }
            continue;
        }

        // 2. 기간 범위 라인 감지 (예: "★10/19(월) ~ 10/22(목)★", "기간: 10/18(일) ~ 10/22(목) [5일간]")
        const parsedRange = parseNoticeDateRange(line);
        if (parsedRange) {
            currentDateRange = parsedRange;
            currentDate = '';
            currentYear = parsedRange.startYear || null;
            continue;
        }

        // 3. 단일 날짜 헤더 라인 확인 (예: "10/18(일)", "▣ 10월18일(일) ▣", "10.18", "10/18", "2026.10.18", "22화", "22일(화)")
        const fallbackM = currentDate ? parseInt(currentDate.split('.')[0], 10) : null;
        const parsedDateDetail = parseNoticeDateDetail(line, fallbackM);
        if (parsedDateDetail && !line.includes(':') && !/\d{1,2}\s*시대/.test(line)) {
            currentDate = parsedDateDetail.dateStr;
            currentYear = parsedDateDetail.year;
            currentDateRange = null;
            continue;
        }

        // 4. 일반 안내문 / 주의사항 / 비-골프 라인 스킵 (구장/날짜/기간 파싱 후 안전하게 스킵)
        if (isNonGolfLine(line) || line.startsWith('※') || line.startsWith('#')) {
            continue;
        }

        // 5. 할인 금액 감지 (예: "혜택: 잔여타임 추가 2만 할인", "2만원 할인")
        const discountVal = parseNoticeDiscount(line);
        if (discountVal !== null) {
            pendingDiscount = discountVal;
            const inlineParts = parseNoticeParts(line);
            if (inlineParts) pendingParts = inlineParts;
            continue;
        }

        // 6. 부제 접두어 또는 단독 부제 라인 검사 (예: "1부 : 6시대: 8만", "3부 : 7만", "[1부+2부]")
        const partPrefixMatch = line.match(/^[-*•▶▷□■▣★☆◆◇▲▼\s]*([123]부|전부|전타임)\s*[:=\-]?\s*(.*)$/);
        if (partPrefixMatch) {
            const partName = partPrefixMatch[1];
            const rest = partPrefixMatch[2].trim();
            const pObj = parseNoticeParts(partName);
            if (pObj) pendingParts = pObj;

            if (!rest) {
                // "1부 :" 단독 라인
                continue;
            }

            // rest 에 시간(: 또는 시)이 없고 금액만 있는 경우 -> 해당 부제 전체 고정 타겟 요금 (예: "3부 : 7만", "3부 : 70,000")
            if (!rest.includes(':') && !/\d{1,2}\s*시/.test(rest)) {
                const priceVal = normalizeNoticePrice(rest);
                if (priceVal !== null) {
                    let startMins = 0;
                    let endMins = 1439;
                    if (partName === '1부') { startMins = 0; endMins = 659; }
                    else if (partName === '2부') { startMins = 660; endMins = 959; }
                    else if (partName === '3부') { startMins = 960; endMins = 1439; }

                    const slashM = rest.match(/([0-9.,]+)\s*(?:만|만원|원)?\s*\/\s*([0-9.,]+)\s*(?:만|만원|원)?/);
                    const slashBackVal = slashM && slashM[2] ? normalizeNoticePrice(slashM[2]) : null;

                    rules.push({
                        type: 'target',
                        course: currentCourse,
                        date: currentDate,
                        year: currentYear,
                        dateRange: currentDateRange,
                        startMins: startMins,
                        endMins: endMins,
                        price: priceVal,
                        slashBackPrice: slashBackVal,
                        parts: pObj,
                        rawLine: line
                    });
                    continue;
                }
            } else {
                // "1부 :  6시대: 8만" 처럼 부제 접두어 뒤에 시간대 요금이 이어지는 경우 -> rest 를 line 으로 재지정하여 아래 시간대 파서로 진입!
                line = rest;
            }
        }

        // 7. 다중 시대 / 연속 시대 범위 동일 요금 패턴 (예: "6시대, 7시대: 8만", "6시~7시대 6만", "6~8시대 7만", "6시, 7시대 8만", "7~13시 13만")
        const hourSep = '(?:\\s*[,/&~-]\\s*|\\s+(?:및|와|과)\\s+)';
        const multiHourRegex = new RegExp('^[-*•▶▷□■▣★☆◆◇▲▼\\s]*((?:\\d{1,2}\\s*(?:시대|시\\s*대|시타임|시)?' + hourSep + ')+\\d{1,2})\\s*(?:시대|시\\s*대|시타임|시)?\\s*[:=\\-]?\\s*([0-9.,]+)\\s*(?:만|만원|원)?(?:\\s*\\/\\s*([0-9.,]+)\\s*(?:만|만원|원)?)?', 'i');
        const multiHourMatch = line.match(multiHourRegex);
        if (multiHourMatch) {
            const hourPartStr = multiHourMatch[1];
            const priceVal = normalizeNoticePrice(multiHourMatch[2]);
            const slashBackVal = multiHourMatch[3] ? normalizeNoticePrice(multiHourMatch[3]) : null;
            if (priceVal !== null) {
                const hours = [];
                // "6~8" 또는 "6시~7시대" 형태의 연속 범위인지 확인
                const rangeHMatch = hourPartStr.match(/(\d{1,2})\s*(?:시대|시\s*대|시타임|시)?\s*[~-]\s*(\d{1,2})/);
                if (rangeHMatch && !hourPartStr.includes(',')) {
                    const startH = parseInt(rangeHMatch[1], 10);
                    const endH = parseInt(rangeHMatch[2], 10);
                    if (!isNaN(startH) && !isNaN(endH) && startH <= endH && startH >= 0 && endH <= 23) {
                        for (let h = startH; h <= endH; h++) {
                            hours.push(h);
                        }
                    }
                }
                if (hours.length === 0) {
                    const nums = (hourPartStr.match(/\d{1,2}/g) || []).map(n => parseInt(n, 10));
                    nums.forEach(n => {
                        if (n >= 0 && n <= 23 && !hours.includes(n)) hours.push(n);
                    });
                }

                if (hours.length > 0) {
                    hours.forEach(h => {
                        rules.push({
                            type: 'target',
                            course: currentCourse,
                            date: currentDate,
                            year: currentYear,
                            dateRange: currentDateRange,
                            startMins: h * 60,
                            endMins: h * 60 + 59,
                            price: priceVal,
                            slashBackPrice: slashBackVal,
                            parts: pendingParts,
                            rawLine: `${h}시대: ${priceVal}만`
                        });
                    });
                    continue;
                }
            }
        }

        // 8. 시대별 요금 패턴 (예: "6시대: 8만", "7시대: 9만", "12시대: 9.5만", "13시대: 9만", "6시 대: 8만", "6시타임: 8만")
        const hourSlotRegex = /(\d{1,2})\s*(?:시대|시\s*대|시타임|시\s*타임)\s*[:=\-]?\s*([0-9.,]+)\s*(?:만|만원|원)?(?:\s*\/\s*([0-9.,]+)\s*(?:만|만원|원)?)?/gi;
        let slotMatch;
        let foundSlot = false;
        while ((slotMatch = hourSlotRegex.exec(line)) !== null) {
            const h = parseInt(slotMatch[1], 10);
            const priceVal = normalizeNoticePrice(slotMatch[2]);
            const slashBackVal = slotMatch[3] ? normalizeNoticePrice(slotMatch[3]) : null;
            if (priceVal !== null && h >= 0 && h <= 23) {
                foundSlot = true;
                rules.push({
                    type: 'target',
                    course: currentCourse,
                    date: currentDate,
                    year: currentYear,
                    dateRange: currentDateRange,
                    startMins: h * 60,
                    endMins: h * 60 + 59,
                    price: priceVal,
                    slashBackPrice: slashBackVal,
                    parts: pendingParts,
                    rawLine: line
                });
            }
        }
        if (foundSlot) continue;

        // 9. 복수 지정 시간 동일 요금 패턴 (예: "07:04, 07:11 12만", "06:43, 07:15, 07:22 12만", "07:04 / 07:11 12만", "07:04 및 07:11 12만")
        const singleTimeToken = '(?:\\d{1,2}:\\d{2}|\\d{1,2}\\s*시(?:\\s*\\d{1,2}\\s*분?)?|\\d{4})';
        const multiTimeRegex = new RegExp('^[-*•▶▷□■▣★☆◆◇▲▼\\s]*((?:' + singleTimeToken + '\\s*[,/&+]\\s*|' + singleTimeToken + '\\s+(?:및|와|과)\\s+)+' + singleTimeToken + ')[^0-9.,]*?([0-9.,]+)\\s*(?:만|만원|원)?(?:\\s*\\/\\s*([0-9.,]+)\\s*(?:만|만원|원)?)?', 'i');
        const multiTimeMatch = line.match(multiTimeRegex);
        if (multiTimeMatch) {
            const timeListStr = multiTimeMatch[1];
            const priceVal = normalizeNoticePrice(multiTimeMatch[2]);
            const slashBackVal = multiTimeMatch[3] ? normalizeNoticePrice(multiTimeMatch[3]) : null;
            if (priceVal !== null) {
                const timeTokens = timeListStr.split(/[,/&+]|\s+및\s+|\s+와\s+|\s+과\s+/).map(s => s.trim()).filter(Boolean);
                let addedAny = false;
                timeTokens.forEach(tStr => {
                    const tMins = timeToMinutes(tStr);
                    const isHourOnly = !tStr.includes(':') && !/\d{1,2}\s*분/.test(tStr);
                    const endMins = isHourOnly ? (tMins + 59) : tMins;
                    rules.push({
                        type: 'target',
                        course: currentCourse,
                        date: currentDate,
                        year: currentYear,
                        dateRange: currentDateRange,
                        startMins: tMins,
                        endMins: endMins,
                        price: priceVal,
                        slashBackPrice: slashBackVal,
                        parts: pendingParts,
                        rawLine: `${tStr} ${priceVal}만`
                    });
                    addedAny = true;
                });
                if (addedAny) continue;
            }
        }

        // 10. 시간 토큰 패턴 정의 (HH:MM, 7시, 7시30분, 7:40분 이후, 8시 이전 등 완벽 지원)
        const timePattern = '(?:\\d{1,2}:\\d{2}|\\d{1,2}\\s*시(?:\\s*\\d{1,2}\\s*분?)?|\\d{4})(?:\\s*분)?';

        // 10-1. 시간 범위 타겟 금액 패턴 (예: "7:40분 이후~8시 이전 현장 15만!", "8시~8:15 현장 16만!", "05:46 ~ 06:07 - 10.9")
        const rangeMatch = line.match(new RegExp('(' + timePattern + ')(?:\\s*이후)?\\s*(?:~|-|부터)\\s*(' + timePattern + ')(?:\\s*이전)?[^0-9.,]*?([0-9.,]+)\\s*(?:만|만원|원)?(?:\\s*\\/\\s*([0-9.,]+)\\s*(?:만|만원|원)?)?', 'i'));
        if (rangeMatch) {
            const startStr = rangeMatch[1];
            const endStr = rangeMatch[2];
            const priceVal = normalizeNoticePrice(rangeMatch[3]);
            const slashBackVal = rangeMatch[4] ? normalizeNoticePrice(rangeMatch[4]) : null;

            if (priceVal !== null) {
                rules.push({
                    type: 'target',
                    course: currentCourse,
                    date: currentDate,
                    year: currentYear,
                    dateRange: currentDateRange,
                    startMins: timeToMinutes(startStr),
                    endMins: timeToMinutes(endStr),
                    price: priceVal,
                    slashBackPrice: slashBackVal,
                    parts: pendingParts,
                    rawLine: line
                });
                continue;
            }
        }

        // 10-2. 특정 시간 이후 패턴 (예: "13:35분 이후 현장 16만!", "13시이후 13만", "13시대 이후 13만")
        const afterMatch = line.match(new RegExp('(' + timePattern + ')\\s*(?:시대)?\\s*(?:이후|부터)[^0-9.,]*?([0-9.,]+)\\s*(?:만|만원|원)?(?:\\s*\\/\\s*([0-9.,]+)\\s*(?:만|만원|원)?)?', 'i'));
        if (afterMatch) {
            const startStr = afterMatch[1];
            const priceVal = normalizeNoticePrice(afterMatch[2]);
            const slashBackVal = afterMatch[3] ? normalizeNoticePrice(afterMatch[3]) : null;
            if (priceVal !== null) {
                rules.push({
                    type: 'target',
                    course: currentCourse,
                    date: currentDate,
                    year: currentYear,
                    dateRange: currentDateRange,
                    startMins: timeToMinutes(startStr),
                    endMins: 1439, // 23:59까지 전체 해당
                    price: priceVal,
                    slashBackPrice: slashBackVal,
                    parts: pendingParts,
                    rawLine: line
                });
                continue;
            }
        }

        // 10-3. 특정 시간 이전 패턴 (예: "07:30 이전 150,000원", "8시 전 6.4만", "8시대 이전 7만")
        const beforeMatch = line.match(new RegExp('(' + timePattern + ')\\s*(?:시대)?\\s*(?:이전|전)[^0-9.,]*?([0-9.,]+)\\s*(?:만|만원|원)?(?:\\s*\\/\\s*([0-9.,]+)\\s*(?:만|만원|원)?)?', 'i'));
        if (beforeMatch) {
            const endStr = beforeMatch[1];
            const priceVal = normalizeNoticePrice(beforeMatch[2]);
            const slashBackVal = beforeMatch[3] ? normalizeNoticePrice(beforeMatch[3]) : null;
            if (priceVal !== null) {
                rules.push({
                    type: 'target',
                    course: currentCourse,
                    date: currentDate,
                    year: currentYear,
                    dateRange: currentDateRange,
                    startMins: 0,
                    endMins: timeToMinutes(endStr),
                    price: priceVal,
                    slashBackPrice: slashBackVal,
                    parts: pendingParts,
                    rawLine: line
                });
                continue;
            }
        }

        // 10-4. 단일 시간 타겟 금액 패턴 (예: "06:43 12만", "07:04 8만", "6:44 3타임 잔여 현장 13만!", "7:05 루나 현장 14만!", "05:46 - 10.9", "7시 9만")
        const singleMatch = line.match(new RegExp('^\\s*(?:[-*•▶▷□■▣★☆◆◇▲▼]\\s*)?(' + timePattern + ')[^0-9.,]*?([0-9.,]+)\\s*(?:만|만원|원)?(?:\\s*\\/\\s*([0-9.,]+)\\s*(?:만|만원|원)?)?', 'i'));
        if (singleMatch) {
            const timeStr = singleMatch[1];
            const priceVal = normalizeNoticePrice(singleMatch[2]);
            const slashBackVal = singleMatch[3] ? normalizeNoticePrice(singleMatch[3]) : null;

            if (priceVal !== null) {
                const tMins = timeToMinutes(timeStr);
                // "7시" 처럼 분 없이 시간만 지정된 경우 해당 시 전체(07:00~07:59) 적용, "7:15" 처럼 분이 있으면 해당 분만 지정
                const isHourOnly = !timeStr.includes(':') && !/\d{1,2}\s*분/.test(timeStr);
                const endMins = isHourOnly ? (tMins + 59) : tMins;

                rules.push({
                    type: 'target',
                    course: currentCourse,
                    date: currentDate,
                    year: currentYear,
                    dateRange: currentDateRange,
                    startMins: tMins,
                    endMins: endMins,
                    price: priceVal,
                    slashBackPrice: slashBackVal,
                    parts: pendingParts,
                    rawLine: line
                });
                continue;
            }
        }
    }

    flushPendingDiscount();

    // Same-As 지시어 최종 처리 (예: "(14시타임은 13시대와 동일적용)")
    if (sameAsDirectives.length > 0) {
        sameAsDirectives.forEach(directive => {
            const { targetHour, sourceHour, course, date, year, dateRange } = directive;
            const srcStart = sourceHour * 60;
            const srcEnd = sourceHour * 60 + 59;
            const matchingRules = rules.filter(r => {
                if (r.type !== 'target') return false;
                if (r.course && course && !isCourseMatch(r.course, course)) return false;
                if (r.date && date && !isDateMatch(r.date, date)) return false;
                return (r.startMins <= srcEnd && r.endMins >= srcStart);
            });

            if (matchingRules.length > 0) {
                matchingRules.forEach(srcRule => {
                    rules.push({
                        type: 'target',
                        course: srcRule.course || course || currentCourse,
                        date: srcRule.date || date || currentDate,
                        year: srcRule.year || year || currentYear,
                        dateRange: srcRule.dateRange || dateRange || currentDateRange,
                        startMins: targetHour * 60,
                        endMins: targetHour * 60 + 59,
                        price: srcRule.price,
                        slashBackPrice: srcRule.slashBackPrice,
                        parts: srcRule.parts,
                        rawLine: `${targetHour}시대: ${srcRule.price}만 (${sourceHour}시대와 동일적용)`
                    });
                });
            }
        });
    }

    // 만약 공지 본문에 구장명이 생략된 경우 현재 화면의 단일 구장명으로 자동 보완
    if (rules.length > 0) {
        if (!primaryCourse) {
            const uniqueCourses = new Set();
            document.querySelectorAll('#dataTable tbody tr').forEach(tr => {
                const g = tr.cells[2]?.textContent.trim();
                if (g) uniqueCourses.add(g);
            });
            if (uniqueCourses.size === 1) {
                primaryCourse = Array.from(uniqueCourses)[0];
            }
        }

        // 모든 규칙의 구장명을 메시지의 단일 대표 구장으로 확정 (1부, 2부 등 비-구장명 완전 차단)
        rules.forEach(r => {
            if (!r.course || isNonCourseWord(r.course)) {
                r.course = primaryCourse;
            } else if (primaryCourse && r.course !== primaryCourse) {
                // 단일 공지 메시지에서는 대표 구장으로 통일
                r.course = primaryCourse;
            }
        });
    }

    // 최종 반환 시 비-구장 단어나 빈 구장명을 가진 규칙은 철저히 제거
    return rules.filter(r => r.course && !isNonCourseWord(r.course));
}

// 활성 공지 규칙 누적 저장소 (구장별 중복/누적 보존)
let activeNoticeRules = [];

// 공지 규칙의 만료 일시(해당 날짜 23:59:59.999 타임스탬프) 계산
function getNoticeRuleExpirationTime(rule) {
    if (!rule) return null;
    const now = new Date();
    const todayY = now.getFullYear();
    const todayM = now.getMonth() + 1; // 1-12

    let targetY = null;
    let targetM = null;
    let targetD = null;

    // 1. 기간 범위가 있는 경우 종료일(endDate) 기준
    if (rule.dateRange && rule.dateRange.endM && rule.dateRange.endD) {
        targetM = parseInt(rule.dateRange.endM, 10);
        targetD = parseInt(rule.dateRange.endD, 10);
        targetY = rule.dateRange.endYear || rule.year || null;
    } else if (rule.date) {
        // 2. 단일 날짜 (예: "10.18", "2026.10.18")
        const parts = String(rule.date).replace(/[^\d.]/g, '').split('.');
        if (parts.length === 3) {
            targetY = parseInt(parts[0], 10);
            targetM = parseInt(parts[1], 10);
            targetD = parseInt(parts[2], 10);
        } else if (parts.length === 2) {
            targetM = parseInt(parts[0], 10);
            targetD = parseInt(parts[1], 10);
            targetY = rule.year || null;
        }
    }

    if (!targetM || !targetD || isNaN(targetM) || isNaN(targetD)) {
        return null;
    }

    // 연도 자동 보정 (명시적 연도가 없는 경우)
    if (!targetY) {
        targetY = todayY;
        // 오늘이 12월이고 공지가 1~2월인 경우 -> 내년(todayY + 1)
        if (todayM === 12 && targetM <= 2) {
            targetY = todayY + 1;
        }
        // 오늘이 1월이고 공지가 11~12월인 경우 -> 작년(todayY - 1)
        else if (todayM === 1 && targetM >= 11) {
            targetY = todayY - 1;
        }
    } else if (targetY < 100) {
        targetY = 2000 + targetY;
    }

    // 해당 날짜의 23:59:59.999 (해당 날짜가 완전히 끝날 때까지 유효)
    const expDate = new Date(targetY, targetM - 1, targetD, 23, 59, 59, 999);
    return expDate.getTime();
}

// 특정 공지 규칙이 이미 만료(공지 날짜가 지난 상태)되었는지 판별
function isNoticeRuleExpired(rule) {
    const expTime = getNoticeRuleExpirationTime(rule);
    if (!expTime) return false;
    return Date.now() > expTime;
}

// 만료된(공지 날짜가 지난) 공지 규칙 자동 정리 및 비-구장/가짜 규칙 정제
function pruneExpiredNoticeRules() {
    if (!Array.isArray(activeNoticeRules) || activeNoticeRules.length === 0) return 0;
    const initialCount = activeNoticeRules.length;
    activeNoticeRules = activeNoticeRules.filter(rule => {
        if (!rule) return false;
        if (!rule.course || isNonCourseWord(rule.course)) return false;
        // 날짜/기간 정보가 전혀 없는 비정상/가짜 규칙 자동 정제 (정상 공지는 반드시 date 또는 dateRange를 가짐)
        if (!rule.date && !rule.dateRange) return false;
        return !isNoticeRuleExpired(rule);
    });
    const prunedCount = initialCount - activeNoticeRules.length;
    if (prunedCount > 0) {
        saveActiveNoticeRules();
    }
    return prunedCount;
}

function loadActiveNoticeRules() {
    try {
        const saved = localStorage.getItem('v2_activeNoticeRules');
        if (saved) {
            const parsed = JSON.parse(saved);
            if (Array.isArray(parsed)) {
                activeNoticeRules = parsed.filter(rule => rule && rule.course && !isNonCourseWord(rule.course) && (rule.date || rule.dateRange));
            }
        }
    } catch(e) {
        activeNoticeRules = [];
    }
    // 날짜 지난 만료 공지 및 비-구장/가짜 규칙 자동 삭제
    pruneExpiredNoticeRules();

    // 카톡 실시간 수집 내역(v2_collectedKakaoNotices)에 저장된 공지 중 누락되거나 오염된 공지 자동 복원
    try {
        const collectedStr = localStorage.getItem('v2_collectedKakaoNotices');
        if (collectedStr) {
            const list = JSON.parse(collectedStr);
            if (Array.isArray(list)) {
                list.forEach(item => {
                    if (item && item.text) {
                        const parsedRules = parseNoticeText(item.text);
                        const validRules = parsedRules.filter(r => (r.date || r.dateRange) && !isNoticeRuleExpired(r));
                        if (validRules.length > 0) {
                            const cNames = new Set(validRules.map(r => r.course).filter(Boolean));
                            // 해당 구장의 기존 규칙 수가 새로 파싱된 유효 규칙 수와 일치하는지 검사 (버그로 오염된 경우 자동 재파싱 갱신)
                            const isAccurate = Array.from(cNames).every(cn => {
                                const existing = activeNoticeRules.filter(ar => isCourseMatch(cn, ar.course, ar.course, ar.course));
                                return existing.length === validRules.length;
                            });
                            if (!isAccurate) {
                                applyNoticeFromText(item.text, true, item.collected_at);
                            }
                        }
                    }
                });
            }
        }
    } catch(e) {}

    return activeNoticeRules;
}

function saveActiveNoticeRules() {
    try {
        localStorage.setItem('v2_activeNoticeRules', JSON.stringify(activeNoticeRules));
    } catch(e) {}
    try {
        if (typeof chrome !== 'undefined' && chrome.storage && chrome.storage.local) {
            chrome.storage.local.set({ v2_activeNoticeRules: activeNoticeRules });
        }
    } catch(e) {}
}

// 공지가격 적용 여부 전역 토글 (체크박스 상태: 기본 true)
let isNoticeRulesActive = true;

function initNoticeRulesActive() {
    try {
        const saved = localStorage.getItem('v2_isNoticeRulesActive');
        if (saved !== null) {
            isNoticeRulesActive = (saved === 'true');
        }
    } catch(e) {}
    const chk = document.getElementById('chkEnableNoticeRules');
    if (chk) chk.checked = isNoticeRulesActive;
    updateNoticeHeaderUI();
}

function updateNoticeHeaderUI() {
    const group = document.getElementById('noticeHeaderBtnGroup');
    const chk = document.getElementById('chkEnableNoticeRules');
    const badgeWrapper = document.getElementById('headerNoticeCountWrapper');
    const isChecked = chk ? chk.checked : isNoticeRulesActive;

    if (group) {
        group.classList.toggle('disabled-notice', !isChecked);
    }
    if (badgeWrapper) {
        badgeWrapper.style.color = isChecked ? '#059669' : '#94A3B8';
    }
}

function setNoticeRulesActive(active, notify = true) {
    isNoticeRulesActive = active;
    try {
        localStorage.setItem('v2_isNoticeRulesActive', active ? 'true' : 'false');
        if (typeof chrome !== 'undefined' && chrome.storage && chrome.storage.local) {
            chrome.storage.local.set({ v2_isNoticeRulesActive: active });
        }
    } catch(e) {}
    const chk = document.getElementById('chkEnableNoticeRules');
    if (chk) chk.checked = active;
    updateNoticeHeaderUI();
    applyAllActiveNoticeRules();
    if (notify) {
        if (active) {
            showToast('🟢 공지가격 적용이 활성화되었습니다.');
        } else {
            showToast('⚪ 공지가격 적용이 비활성화되었습니다. (원래 금액으로 표시)');
        }
    }
}

// 공지 모달 내 적용 중인 공지 칩 UI 렌더링
function renderActiveNoticeChips() {
    // 렌더링 직전 만료 규칙 정리
    pruneExpiredNoticeRules();

    const sec = document.getElementById('activeNoticeSection');
    const listEl = document.getElementById('activeNoticeChipList');
    const countEl = document.getElementById('activeNoticeCount');
    const headerNoticeBadge = document.getElementById('headerNoticeBadge');
    const headerNoticeCountWrapper = document.getElementById('headerNoticeCountWrapper');

    function updateHeaderBadge(count) {
        if (headerNoticeBadge && headerNoticeCountWrapper) {
            if (count > 0) {
                headerNoticeBadge.textContent = count.toString();
                headerNoticeCountWrapper.style.display = 'inline';
            } else {
                headerNoticeCountWrapper.style.display = 'none';
            }
        }
        updateNoticeHeaderUI();
    }

    if (!activeNoticeRules || activeNoticeRules.length === 0) {
        if (sec) sec.style.display = 'none';
        if (listEl) listEl.innerHTML = '';
        if (countEl) countEl.textContent = '0';
        updateHeaderBadge(0);
        return;
    }

    if (!sec || !listEl) {
        updateHeaderBadge(activeNoticeRules.length);
        return;
    }

    sec.style.display = 'block';
    listEl.innerHTML = '';

    // 구장별로 룰 그룹화
    const courseGroups = {};
    activeNoticeRules.forEach(r => {
        const c = r.course || '공지 구장';
        if (!courseGroups[c]) courseGroups[c] = [];
        courseGroups[c].push(r);
    });

    const courses = Object.keys(courseGroups);
    if (countEl) countEl.textContent = courses.length.toString();
    updateHeaderBadge(courses.length);

    courses.forEach(courseName => {
        const list = courseGroups[courseName];
        let desc = '';
        const discountRule = list.find(r => r.type === 'discount');
        if (discountRule) {
            const dRange = discountRule.dateRange ? discountRule.dateRange.text : (discountRule.date || '');
            const pDesc = discountRule.parts ? discountRule.parts.desc : '전부';
            desc = `${dRange ? `${dRange} ` : ''}-${discountRule.discount}만 (${pDesc})`;
        } else {
            const firstDate = list[0]?.date || '';
            desc = `${firstDate ? `${firstDate} ` : ''}${list.length}개 타임`;
        }

        // 만료 유효기간 태그 (예: ~10.18 또는 ~10.22)
        let validUntilStr = '';
        const dates = list.map(r => {
            if (r.dateRange && r.dateRange.endDate) return r.dateRange.endDate;
            if (r.date) return r.date;
            return '';
        }).filter(Boolean);
        if (dates.length > 0) {
            validUntilStr = dates[dates.length - 1];
        }
        const validityTag = validUntilStr ? ` <span style="opacity:0.85; font-size:11px; color:#2563EB;">(~${validUntilStr})</span>` : '';

        // 공지 수신 일시 태그 (예: 🕒 10/16 16:18)
        const receivedAtStr = list[0]?.receivedAt || '';
        const receivedTag = receivedAtStr ? ` <span style="opacity:0.9; font-size:10.5px; color:#D97706; font-weight:600;" title="공지 수신 일시: ${receivedAtStr}">🕒 ${receivedAtStr}</span>` : '';

        const chip = document.createElement('div');
        chip.className = 'active-notice-chip';
        chip.dataset.course = courseName;
        chip.title = `[${courseName}] 클릭 시 공지 전문 보기 (수신: ${receivedAtStr || '최근'})`;
        chip.innerHTML = `
            <span class="chip-content" style="cursor: pointer;">📢 <strong>${courseName}</strong> (${desc})${receivedTag}${validityTag}</span>
            <button type="button" class="chip-del-btn" data-course="${courseName}" title="${courseName} 공지만 해제">✕</button>
        `;

        chip.addEventListener('click', (e) => {
            if (e.target.closest('.chip-del-btn')) {
                const cName = e.target.closest('.chip-del-btn').dataset.course || courseName;
                removeNoticeForCourse(cName);
                return;
            }
            showNoticeDetailModal(courseName);
        });

        listEl.appendChild(chip);
    });
}

// 특정 구장 공지만 제거하고 나머지 구장 공지 유지
function removeNoticeForCourse(courseName) {
    activeNoticeRules = activeNoticeRules.filter(r => {
        if (!r.course) return false;
        if (r.course === courseName || r.course.trim().toLowerCase() === courseName.trim().toLowerCase()) return false;
        return !isCourseMatch(courseName, r.course, r.course, r.course);
    });
    saveActiveNoticeRules();
    applyAllActiveNoticeRules();
    renderActiveNoticeChips();
    showToast(`'${courseName}' 공지가 해제되었습니다.`);
}

// 전체 공지 완전 초기화
function clearAllNotices() {
    activeNoticeRules = [];
    saveActiveNoticeRules();
    revertNoticeRules();
    renderActiveNoticeChips();
}

// 특정 구장의 공지 전문 원문 반환 (저장된 전문 > 카톡 수집 내역 > 규칙 기반 구조화 전문)
function getFullNoticeTextForCourse(courseName) {
    if (!courseName) return '';
    const normTarget = courseName.replace(/[\s\-_\[\]\(\)]|cc|gc|골프장|골프클럽/gi, '').toLowerCase();

    // 1. activeNoticeRules 에서 fullNoticeText 또는 rawNoticeText 탐색
    const matchingRules = activeNoticeRules.filter(r => {
        if (!r.course) return false;
        if (r.course === courseName) return true;
        const normR = r.course.replace(/[\s\-_\[\]\(\)]|cc|gc|골프장|골프클럽/gi, '').toLowerCase();
        return normR === normTarget || normTarget.includes(normR) || normR.includes(normTarget);
    });

    const ruleWithText = matchingRules.find(r => r.fullNoticeText || r.rawNoticeText);
    if (ruleWithText && (ruleWithText.fullNoticeText || ruleWithText.rawNoticeText)) {
        return ruleWithText.fullNoticeText || ruleWithText.rawNoticeText;
    }

    // 2. lastCollectedKakaoNotices 에서 탐색
    if (typeof lastCollectedKakaoNotices !== 'undefined' && Array.isArray(lastCollectedKakaoNotices) && lastCollectedKakaoNotices.length > 0) {
        const matchedItem = lastCollectedKakaoNotices.find(item => {
            if (!item.text) return false;
            const normText = item.text.replace(/[\s\-_\[\]\(\)]|cc|gc|골프장|골프클럽/gi, '').toLowerCase();
            return normText.includes(normTarget) || (item.course && item.course.includes(courseName));
        });
        if (matchedItem && matchedItem.text) {
            return matchedItem.text;
        }
    }

    // 3. 만약 저장된 원문이 없다면, 등록된 규칙들로부터 구조화된 전문 생성
    if (matchingRules.length > 0) {
        const lines = [];
        const r0 = matchingRules[0];
        lines.push(`■ ${courseName}`);
        if (r0.receivedAt) lines.push(`[공지 수신 일시: ${r0.receivedAt}]`);
        if (r0.dateRange) lines.push(`기간: ${r0.dateRange.text}`);
        else if (r0.date) lines.push(`날짜: ${r0.date}`);
        lines.push('');
        matchingRules.forEach(r => {
            if (r.type === 'target') {
                const startH = Math.floor(r.startMins / 60);
                const startM = r.startMins % 60;
                const endH = Math.floor(r.endMins / 60);
                const endM = r.endMins % 60;
                const timeDesc = (r.startMins === r.endMins)
                    ? `${String(startH).padStart(2, '0')}:${String(startM).padStart(2, '0')}`
                    : (r.endMins - r.startMins === 59 && startM === 0)
                        ? `${startH}시대`
                        : `${String(startH).padStart(2, '0')}:${String(startM).padStart(2, '0')} ~ ${String(endH).padStart(2, '0')}:${String(endM).padStart(2, '0')}`;
                lines.push(`${r.date ? `${r.date} ` : ''}${timeDesc} : ${r.price}만${r.slashBackPrice ? ` / ${r.slashBackPrice}만` : ''}`);
            } else if (r.type === 'discount') {
                lines.push(`추가 할인: -${r.discount}만 (${r.parts ? r.parts.desc : '전부'})`);
            }
        });
        return lines.join('\n');
    }

    return `[${courseName}] 등록된 공지 원문을 찾을 수 없습니다.`;
}

// 화면 공지 클릭 시 공지 전문 모달 표시
function showNoticeDetailModal(courseName) {
    const modal = document.getElementById('noticeViewModal');
    if (!modal) return;

    const titleEl = document.getElementById('noticeViewTitle');
    const metaEl = document.getElementById('noticeViewMeta');
    const bodyEl = document.getElementById('noticeViewBody');

    const matchingRules = activeNoticeRules.filter(r => {
        if (!r.course) return false;
        if (r.course === courseName) return true;
        const normR = r.course.replace(/[\s\-_\[\]\(\)]|cc|gc|골프장|골프클럽/gi, '').toLowerCase();
        const normTarget = courseName.replace(/[\s\-_\[\]\(\)]|cc|gc|골프장|골프클럽/gi, '').toLowerCase();
        return normR === normTarget || normTarget.includes(normR) || normR.includes(normTarget);
    });

    const receivedAt = matchingRules[0]?.receivedAt || '최근';
    let validUntil = '';
    const dates = matchingRules.map(r => {
        if (r.dateRange && r.dateRange.endDate) return r.dateRange.endDate;
        if (r.date) return r.date;
        return '';
    }).filter(Boolean);
    if (dates.length > 0) validUntil = dates[dates.length - 1];

    if (titleEl) titleEl.textContent = `${courseName} 공지 전문`;
    if (metaEl) {
        metaEl.innerHTML = `
            <span style="background: #FEF3C7; color: #92400E; padding: 2px 7px; border-radius: 10px; font-weight: 700;">🕒 수신: ${escapeHtml(receivedAt)}</span>
            ${validUntil ? `<span style="background: #DBEAFE; color: #1E40AF; padding: 2px 7px; border-radius: 10px; font-weight: 600;">📅 유효: ~${escapeHtml(validUntil)}</span>` : ''}
            <span style="background: #DCFCE7; color: #166534; padding: 2px 7px; border-radius: 10px; font-weight: 600;">🎯 규칙: ${matchingRules.length}건</span>
        `;
    }

    const fullText = getFullNoticeTextForCourse(courseName);
    if (bodyEl) {
        bodyEl.textContent = fullText;
    }

    // 전문 복사 버튼 연결
    const btnCopy = document.getElementById('btnCopyNoticeViewText');
    if (btnCopy) {
        btnCopy.onclick = () => {
            navigator.clipboard.writeText(fullText).then(() => {
                showToast(`📋 [${courseName}] 공지 전문이 복사되었습니다.`);
            }).catch(() => {
                showToast('복사에 실패했습니다.');
            });
        };
    }

    // 입력창에 넣기 버튼 연결
    const btnPaste = document.getElementById('btnPasteNoticeToInput');
    if (btnPaste) {
        btnPaste.onclick = () => {
            const input = document.getElementById('noticeInputText');
            if (input) {
                input.value = fullText;
                showToast(`📝 [${courseName}] 공지 전문을 입력창에 넣었습니다.`);
                closeNoticeDetailModal();
                const noticeModal = document.getElementById('noticeModal');
                if (noticeModal) noticeModal.style.display = 'flex';
            }
        };
    }

    // 공지 재적용 버튼 연결
    const btnApply = document.getElementById('btnApplyFromNoticeView');
    if (btnApply) {
        btnApply.onclick = () => {
            applyNoticeFromText(fullText, false, receivedAt);
            closeNoticeDetailModal();
        };
    }

    modal.style.display = 'flex';
}

function closeNoticeDetailModal() {
    const modal = document.getElementById('noticeViewModal');
    if (modal) modal.style.display = 'none';
}

// 모든 활성 공지 규칙을 현재 테이블에 일괄 적용 (누적 적용 보장)
function applyAllActiveNoticeRules() {
    // 적용 전 만료된 공지 규칙 자동 정리
    pruneExpiredNoticeRules();

    const tbody = document.getElementById('tableBody');
    if (!tbody) return 0;
    const trs = Array.from(tbody.querySelectorAll('tr'));
    if (trs.length === 0) return 0;

    let appliedTotal = 0;
    const matchedCourses = new Set();

    trs.forEach(tr => {
        const cells = tr.querySelectorAll('td');
        if (cells.length < 5) return;

        // 원본 기준금액 초기 복원 후 매칭
        if (tr.dataset.origBaseFee) {
            tr.dataset.baseFee = tr.dataset.origBaseFee;
        } else {
            tr.dataset.origBaseFee = tr.dataset.baseFee || cells[4].textContent.trim();
        }

        if (tr.dataset.origSlashFrontVal) {
            tr.dataset.slashFrontVal = tr.dataset.origSlashFrontVal;
        } else if (tr.dataset.slashFrontVal) {
            tr.dataset.origSlashFrontVal = tr.dataset.slashFrontVal;
        }

        delete tr.dataset.noticeAdjusted;
        delete tr.dataset.noticePrice;
        delete tr.dataset.noticeDiscount;
        delete tr.dataset.noticeTagDesc;
        delete tr.dataset.noticeType;
        delete tr.dataset.noticeReceivedAt;

        const rowDate = cells[0]?.textContent.trim() || '';
        const rowGolf = cells[2]?.textContent.trim() || '';
        const rowTime = cells[3]?.textContent.trim() || '';
        const rowRawGolf = tr.dataset.rawGolf || rowGolf;
        const rowGolfmonGolf = tr.dataset.golfmonGolf || '';
        const rowTimeMins = timeToMinutes(rowTime);

        const roomType = (tr.dataset.roomType || '').trim();
        const isPrepaid = tr.dataset.isPrepaid === 'true';

        // 선티방 / 대기방 판별 (화면상 선티/대기방 또는 선티/대기 속성을 가진 모든 항목)
        const isSeontiOrDaegi = (
            tr.dataset.isSeontiOrDaegi === 'true' ||
            roomType === '선티방' ||
            roomType === '대기방' ||
            roomType.includes('선티') ||
            roomType.includes('대기') ||
            isPrepaid ||
            /^[123]인$/.test(cells[7]?.textContent.trim() || '')
        );

        // 원본 데이터 기준 선입금 액수 판별 (예: [현장17만+선입1만] -> 1.0, 15만[현장15만] -> 0)
        let rowPrepaidAmount = parseFloat(tr.dataset.prepaidAmount) || 0;
        let hasSlashFee = tr.dataset.hasSlashFee === 'true';
        let slashBackVal = parseFloat(tr.dataset.slashBackVal) || 0;

        // 만약 dataset에 선입금 정보가 비어있다면 원본 텍스트에서 보조 탐색
        if (rowPrepaidAmount <= 0) {
            const inputVal = document.getElementById('inputText')?.value || '';
            if (inputVal) {
                const lines = inputVal.split('\n');
                for (const l of lines) {
                    const cleanT = rowTime.replace(':', '');
                    const lClean = l.replace(':', '');
                    if (lClean.includes(cleanT) || (rowTime.includes(':') && l.includes(rowTime))) {
                        const plusMatch = l.match(/(?:선입(?:금)?|선결제)\s*[:=\-]?\s*([0-9.]+)\s*(?:만|만원)?/i);
                        if (plusMatch) {
                            rowPrepaidAmount = parseFloat(plusMatch[1]) || 1.0;
                            tr.dataset.prepaidAmount = rowPrepaidAmount.toString();
                            break;
                        }
                        const slashMatch = l.match(/([0-9.]+)\s*(?:만|만원)?\s*\/\s*([0-9.]+)\s*(?:만|만원)(?!\s*[인명팀분])/);
                        if (slashMatch) {
                            hasSlashFee = true;
                            slashBackVal = parseFloat(slashMatch[2]) || 0;
                            rowPrepaidAmount = slashBackVal;
                            tr.dataset.hasSlashFee = 'true';
                            tr.dataset.slashBackVal = slashBackVal.toString();
                            tr.dataset.slashFrontVal = slashMatch[1];
                            tr.dataset.origSlashFrontVal = slashMatch[1];
                            tr.dataset.prepaidAmount = rowPrepaidAmount.toString();
                            break;
                        }
                    }
                }
            }
        }

        // 해당 타임이 "선입금이 있는 타임"인지 판별 (원본 데이터에 선입금 명시된 경우)
        const hasPrepaidDeposit = !isSeontiOrDaegi && rowPrepaidAmount > 0;
        const prepaidAddAmount = rowPrepaidAmount;

        // ★ [사용자 요청] 선티방과 대기방은 이미 공지가가 적용되었으니, 공지가를 적용하지마!
        // ★ [사용자 요청] 공지적용 체크박스가 켜져있을 때만 공지가격 적용
        let matchedRule = null;
        if (!isSeontiOrDaegi && isNoticeRulesActive) {
            const candidates = activeNoticeRules.filter(rule => {
                if (rule.course && !isCourseMatch(rule.course, rowGolf, rowRawGolf, rowGolfmonGolf)) {
                    return false;
                }
                if (rule.dateRange) {
                    if (!isDateInRange(rowDate, rule.dateRange)) return false;
                } else if (rule.date) {
                    if (!isDateMatch(rule.date, rowDate)) return false;
                }
                if (rule.type === 'target') {
                    if (rowTimeMins < rule.startMins || rowTimeMins > rule.endMins) return false;
                } else if (rule.type === 'discount') {
                    if (!isTimeInPart(rowTimeMins, rule.parts)) return false;
                }
                return true;
            });

            if (candidates.length > 0) {
                // 특정성(우선순위) 기준 정렬:
                // 1) 좁은 시간 범위 우선 (특정 분 지정: 0분 > 1시간대: 59분 > 부제 전체: 600분)
                // 2) 단일 날짜 우선 (rule.date > rule.dateRange)
                // 3) 타겟 가격(target) 우선 > 단순 할인(discount)
                candidates.sort((a, b) => {
                    const durA = (a.endMins !== undefined && a.startMins !== undefined) ? (a.endMins - a.startMins) : 1440;
                    const durB = (b.endMins !== undefined && b.startMins !== undefined) ? (b.endMins - b.startMins) : 1440;
                    if (durA !== durB) return durA - durB;

                    const dateWeightA = a.date ? 1 : 2;
                    const dateWeightB = b.date ? 1 : 2;
                    if (dateWeightA !== dateWeightB) return dateWeightA - dateWeightB;

                    const typeWeightA = a.type === 'target' ? 1 : 2;
                    const typeWeightB = b.type === 'target' ? 1 : 2;
                    return typeWeightA - typeWeightB;
                });
                matchedRule = candidates[0];
            }
        }

        if (matchedRule) {
            appliedTotal++;
            matchedCourses.add(rowGolf);

            // ★ [사용자 요청] 공지에 나오는 가격은 선입금은 제외하고 얘기하는 것!
            // 선입금이 있는 구장의 경우에는 공지가+선입금을 해야하고, 없는 구장은 공지가대로 가격을 설정!
            if (matchedRule.type === 'target') {
                const noticePrice = matchedRule.price; // 순수 공지가 (선입금 제외 금액)
                let finalVal = noticePrice;
                if (hasPrepaidDeposit) {
                    // 선입금이 있는 구장: 공지가 + 선입금 (예: 현장12만 + 선입1만 = 13만)
                    finalVal = Math.round((noticePrice + prepaidAddAmount) * 100) / 100;
                    tr.dataset.noticeTagDesc = `${noticePrice}만 / ${prepaidAddAmount}만`;
                } else {
                    // 선입금이 없는 구장: 공지가대로 설정 (예: 10만 -> 10만)
                    finalVal = noticePrice;
                    tr.dataset.noticeTagDesc = `${noticePrice}만`;
                }

                tr.dataset.noticeAdjusted = 'true';
                tr.dataset.noticeType = 'target';
                tr.dataset.noticePrice = noticePrice.toString();
                tr.dataset.noticeReceivedAt = matchedRule.receivedAt || '';
                if (hasSlashFee) {
                    tr.dataset.slashFrontVal = noticePrice.toString();
                }

                // 특정구장 가격 가감 적용 (부제별 반영 - 선티/대기방 제외)
                const courseAdj = !isSeontiOrDaegi ? getCoursePriceAdjustment(rowGolf, rowRawGolf, rowGolfmonGolf, rowTime) : 0;
                if (courseAdj !== 0) {
                    finalVal = Math.max(0, Math.round((finalVal + courseAdj) * 100) / 100);
                    tr.dataset.coursePriceAdj = courseAdj.toString();
                } else {
                    delete tr.dataset.coursePriceAdj;
                }

                const finalFeeStr = Number.isInteger(finalVal) ? finalVal.toString() : finalVal.toFixed(1);
                tr.dataset.baseFee = finalFeeStr;
                cells[4].textContent = finalFeeStr;
            } else if (matchedRule.type === 'discount') {
                const discount = matchedRule.discount;
                const origTotal = parseFloat(tr.dataset.origBaseFee || tr.dataset.baseFee) || 0;
                let origFrontPrice = origTotal;
                if (hasPrepaidDeposit) {
                    origFrontPrice = Math.max(0, origTotal - prepaidAddAmount);
                } else if (hasSlashFee && slashBackVal > 0) {
                    origFrontPrice = parseFloat(tr.dataset.origSlashFrontVal || tr.dataset.slashFrontVal) || Math.max(0, origTotal - slashBackVal);
                }

                const discountedFront = Math.max(0, Math.round((origFrontPrice - discount) * 100) / 100);
                let finalVal = discountedFront;
                if (hasPrepaidDeposit) {
                    finalVal = Math.round((discountedFront + prepaidAddAmount) * 100) / 100;
                }

                tr.dataset.noticeAdjusted = 'true';
                tr.dataset.noticeType = 'discount';
                tr.dataset.noticeDiscount = discount.toString();
                tr.dataset.noticeReceivedAt = matchedRule.receivedAt || '';
                const pDesc = matchedRule.parts?.desc ? ` (${matchedRule.parts.desc})` : '';
                tr.dataset.noticeTagDesc = `-${discount}만${pDesc}`;

                // 특정구장 가격 가감 적용 (부제별 반영 - 선티/대기방 제외)
                const courseAdj = !isSeontiOrDaegi ? getCoursePriceAdjustment(rowGolf, rowRawGolf, rowGolfmonGolf, rowTime) : 0;
                if (courseAdj !== 0) {
                    finalVal = Math.max(0, Math.round((finalVal + courseAdj) * 100) / 100);
                    tr.dataset.coursePriceAdj = courseAdj.toString();
                } else {
                    delete tr.dataset.coursePriceAdj;
                }

                const finalFeeStr = Number.isInteger(finalVal) ? finalVal.toString() : finalVal.toFixed(1);
                tr.dataset.baseFee = finalFeeStr;
                cells[4].textContent = finalFeeStr;
            }
        } else {
            // 공지 미적용 대상 (선티방/대기방 또는 공지 조건과 일치하지 않는 일반 타임)
            delete tr.dataset.noticeAdjusted;
            delete tr.dataset.noticeType;
            delete tr.dataset.noticePrice;
            delete tr.dataset.noticeDiscount;
            delete tr.dataset.noticeTagDesc;
            delete tr.dataset.noticeReceivedAt;

            const origTotal = parseFloat(tr.dataset.origBaseFee || tr.dataset.baseFee) || 0;
            let finalVal = origTotal;

            // 특정구장 가격 가감 적용 (부제별 반영 - 선티/대기방 제외)
            const courseAdj = !isSeontiOrDaegi ? getCoursePriceAdjustment(rowGolf, rowRawGolf, rowGolfmonGolf, rowTime) : 0;
            if (courseAdj !== 0) {
                finalVal = Math.max(0, Math.round((finalVal + courseAdj) * 100) / 100);
                tr.dataset.coursePriceAdj = courseAdj.toString();
            } else {
                delete tr.dataset.coursePriceAdj;
            }

            const finalFeeStr = Number.isInteger(finalVal) ? finalVal.toString() : finalVal.toFixed(1);
            tr.dataset.baseFee = finalFeeStr;
            cells[4].textContent = finalFeeStr;
        }
    });

    renderCardList();
    saveCurrentTableState();
    return appliedTotal;
}

// updateLivePrepaidFees 하위 호환 별칭 (사전 복원 및 설정 변경 시 호출)
const updateLivePrepaidFees = applyAllActiveNoticeRules;

// 공지 수신 일시 정규화 (예: "2026-10-16 16:18:23" -> "10/16 16:18", 텍스트 내 카톡 시간/발송일 헤더 탐색 또는 현재 시간)
function resolveNoticeReceivedTime(text, explicitTime = null) {
    // 1. 수집기 등에서 명시적으로 전달받은 수신 시각이 있는 경우
    if (explicitTime) {
        if (typeof explicitTime === 'string') {
            const m = explicitTime.match(/(\d{1,2})[./\-](\d{1,2})\s+(\d{1,2}:\d{2})/);
            if (m) {
                return `${parseInt(m[1], 10)}/${parseInt(m[2], 10)} ${m[3]}`;
            }
            const mIso = explicitTime.match(/(\d{4})-(\d{2})-(\d{2})[T\s](\d{2}:\d{2})/);
            if (mIso) {
                return `${parseInt(mIso[2], 10)}/${parseInt(mIso[3], 10)} ${mIso[4]}`;
            }
            return explicitTime.trim();
        } else if (explicitTime instanceof Date) {
            const m = explicitTime.getMonth() + 1;
            const d = explicitTime.getDate();
            const h = String(explicitTime.getHours()).padStart(2, '0');
            const min = String(explicitTime.getMinutes()).padStart(2, '0');
            return `${m}/${d} ${h}:${min}`;
        }
    }

    // 2. 텍스트 본문 첫머리에서 카톡 헤더 시간 탐색 (예: "[오후 4:18]", "10/16 16:18")
    if (text && typeof text === 'string') {
        const lines = text.split('\n').slice(0, 5);
        for (const l of lines) {
            const kakaoTimeMatch = l.match(/\[(오전|오후)\s*(\d{1,2}):(\d{2})\]/);
            if (kakaoTimeMatch) {
                const isPm = kakaoTimeMatch[1] === '오후';
                let h = parseInt(kakaoTimeMatch[2], 10);
                if (isPm && h < 12) h += 12;
                if (!isPm && h === 12) h = 0;
                const hh = String(h).padStart(2, '0');
                const mm = kakaoTimeMatch[3];
                const now = new Date();
                return `${now.getMonth() + 1}/${now.getDate()} ${hh}:${mm}`;
            }
            const dtMatch = l.match(/(\d{1,2})[./\-](\d{1,2})\s+(\d{1,2}:\d{2})/);
            if (dtMatch) {
                return `${parseInt(dtMatch[1], 10)}/${parseInt(dtMatch[2], 10)} ${dtMatch[3]}`;
            }
        }
    }

    // 3. 기본값: 현재 일시 (월/일 시:분)
    const now = new Date();
    const m = now.getMonth() + 1;
    const d = now.getDate();
    const h = String(now.getHours()).padStart(2, '0');
    const min = String(now.getMinutes()).padStart(2, '0');
    return `${m}/${d} ${h}:${min}`;
}

// 텍스트를 전달받아 공지 파싱 및 누적 등록 & 즉시 적용
function applyNoticeFromText(text, silent = false, receivedTime = null) {
    if (isNonGreenFeeEventNotice(text)) {
        if (!silent) showToast('☕ 브런치/모닝박스 등 식음·이벤트 공지는 그린피 할인 공지가 아니므로 자동 제외되었습니다.');
        return 0;
    }

    const receivedAtStr = resolveNoticeReceivedTime(text, receivedTime);
    const newRules = parseNoticeText(text);
    if (!newRules || newRules.length === 0) {
        if (!silent) showToast('적용할 유효한 공지 규칙을 찾을 수 없습니다.');
        return 0;
    }

    // 각 규칙에 수신 일시 및 타임스탬프, 공지 전문 원문 보존
    newRules.forEach(r => {
        r.receivedAt = receivedAtStr;
        r.receivedTimestamp = Date.now();
        r.fullNoticeText = text;
    });

    // 이미 날짜가 지난 만료 공지인지 검사
    const nonExpiredRules = newRules.filter(r => !isNoticeRuleExpired(r));
    // 사용자가 직접 수동 등록(!silent)한 경우, 과거 날짜 테스트나 수동 작업을 위해 등록 허용
    const rulesToRegister = (nonExpiredRules.length > 0 || silent) ? nonExpiredRules : newRules;
    if (rulesToRegister.length === 0) {
        if (!silent) showToast('⏰ 공지 날짜가 이미 지나 만료된 공지입니다.');
        return 0;
    }

    // 새로 등록할 공지 대상 구장 식별
    const newCourses = new Set(rulesToRegister.map(r => r.course).filter(Boolean));

    // 해당 구장에 대한 기존 공지만 교체 (다른 구장의 기존 공지는 완벽 보존!)
    if (newCourses.size > 0) {
        activeNoticeRules = activeNoticeRules.filter(r => {
            if (!r.course) return false;
            return !Array.from(newCourses).some(nc => isCourseMatch(nc, r.course, r.course, r.course));
        });
    }

    activeNoticeRules.push(...rulesToRegister);
    saveActiveNoticeRules();

    const appliedCount = applyAllActiveNoticeRules();
    renderActiveNoticeChips();

    if (!silent) {
        const courseNames = Array.from(newCourses).join(', ') || '공지 구장';
        const timeInfo = receivedAtStr ? ` [수신: ${receivedAtStr}]` : '';
        if (appliedCount > 0) {
            showToast(`📢 [${courseNames}] 공지가 적용되었습니다!${timeInfo} (해당 날짜까지 자동 저장 유지)`);
        } else {
            showToast(`📢 [${courseNames}] 공지 등록 완료${timeInfo} (해당 날짜까지 저장되며 새 티타임 변환 시 자동 적용)`);
        }
    }

    return appliedCount;
}

function escapeHtml(str) {
    if (!str) return '';
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}

// 공지 금액 적용 취소 및 원래 금액 복구
function revertNoticeRules() {
    activeNoticeRules = [];
    saveActiveNoticeRules();

    const tbody = document.getElementById('tableBody');
    if (!tbody) return;
    const trs = Array.from(tbody.querySelectorAll('tr'));
    let revertCount = 0;

    trs.forEach(tr => {
        if (tr.dataset.noticeAdjusted === 'true' || tr.dataset.origBaseFee) {
            revertCount++;
            const origBase = tr.dataset.origBaseFee || tr.dataset.baseFee;
            tr.dataset.baseFee = origBase;
            if (tr.dataset.origSlashFrontVal) {
                tr.dataset.slashFrontVal = tr.dataset.origSlashFrontVal;
            }
            delete tr.dataset.noticeAdjusted;
            delete tr.dataset.noticePrice;
            delete tr.dataset.noticeDiscount;
            delete tr.dataset.noticeTagDesc;
            delete tr.dataset.noticeType;
            delete tr.dataset.noticeReceivedAt;

            const cells = tr.querySelectorAll('td');
            if (cells.length >= 5) {
                const origVal = parseFloat(origBase);
                if (!isNaN(origVal)) {
                    // 특정구장 가격 가감 적용 복원 (부제별 반영 - 선티/대기방 제외)
                    const roomType = (tr.dataset.roomType || '').trim();
                    const isSeontiOrDaegi = (
                        tr.dataset.isSeontiOrDaegi === 'true' ||
                        roomType === '선티방' ||
                        roomType === '대기방' ||
                        roomType.includes('선티') ||
                        roomType.includes('대기') ||
                        tr.dataset.isPrepaid === 'true'
                    );
                    const rowGolf = cells[2]?.textContent.trim() || '';
                    const rowRawGolf = tr.dataset.rawGolf || rowGolf;
                    const rowGolfmonGolf = tr.dataset.golfmonGolf || '';
                    const rowTime = cells[3]?.textContent.trim() || '';
                    const courseAdj = !isSeontiOrDaegi ? getCoursePriceAdjustment(rowGolf, rowRawGolf, rowGolfmonGolf, rowTime) : 0;
                    let finalVal = origVal;
                    if (courseAdj !== 0) {
                        finalVal = Math.max(0, Math.round((finalVal + courseAdj) * 100) / 100);
                        tr.dataset.coursePriceAdj = courseAdj.toString();
                    } else {
                        delete tr.dataset.coursePriceAdj;
                    }
                    cells[4].textContent = Number.isInteger(finalVal) ? finalVal.toString() : finalVal.toFixed(1);
                } else {
                    cells[4].textContent = origBase;
                }
            }
        }
    });

    renderActiveNoticeChips();
    renderCardList();
    saveCurrentTableState();

    if (revertCount > 0) {
        showToast(`공지 적용 ${revertCount}건이 취소되고 원래 금액으로 복구되었습니다.`);
    } else {
        showToast('공지 적용된 티타임이 없습니다.');
    }
}

// ========================================================
// [골프탑 vs 골프락 판별 기준]
// 사용자 지정 규칙:
// 형식 1: 카카오톡 메시지 형식 (시간 앞에 10/20(화) 17:18 날짜/요일 접두사 필수)
// 형식 2: 잔여타임 표 형식 ([2026-10-20] 잔여타임 / 골프장명\t시간\t현장/선 결제...)
// ★ 이 두 가지 형식만 '골프탑(탑)'으로 인식하고, 나머지는 모두 '골프락(락)'으로 인식!
// ========================================================
function isGolftopFormat(txt) {
    if (!txt) return false;

    // [골프탑 형식 2] 잔여타임 표/웹 형식
    const isFormat2Table = (
        txt.includes('잔여타임') ||
        txt.includes('현장/선 결제') ||
        txt.includes('현장/선결제') ||
        (txt.includes('골프장명') && txt.includes('시간') && txt.includes('\t'))
    );
    if (isFormat2Table) return true;

    // [골프탑 형식 1] 카카오톡 메시지 형식
    // 시간 앞에 '10/20(화) 17:18' 날짜/요일이 붙어있는 형식 (골프락은 시간 앞에 날짜/요일이 붙지 않음!)
    const isFormat1Kakao = /\d{1,2}\/\d{1,2}\([가-힣]\)\s+\d{1,2}:\d{2}/.test(txt);
    if (isFormat1Kakao) return true;

    // [골프탑 형식 3 (구장명 '-' 없고 대기중:3[ 또는 (남남) 등 괄호 표기)]
    // 단, 구장명이 '-'로 시작하는 골프락 서식이 아닐 때만 적용
    if (!/^-\s*[가-힣\w]+/m.test(txt)) {
        if (/대기(?:중)?\s*:\s*\d+\s*\[/.test(txt) || /\([남여]{1,2}\)/.test(txt) || /\[현장\s*\d+(?:\.\d+)?\]/.test(txt)) {
            return true;
        }
    }

    return false;
}

function detectDocumentSource(txt) {
    if (!txt) return 'golfrock';
    // 구장명이 '-'로 시작하는 골프락 구장이 존재하고, 텍스트 전체에 골프탑 형식 1이나 2가 없다면 100% 골프락
    if (/^-\s*[가-힣\w]+/m.test(txt)) {
        if (!isGolftopFormat(txt)) {
            return 'golfrock';
        }
    }
    return isGolftopFormat(txt) ? 'golftop' : 'golfrock';
}

// 메인 데이터 파싱 함수 (순수 파싱 & 미등록 구장 감지)
function parseInputData(type) {
    const text = document.getElementById('inputText')?.value || '';
    const adjustMinsVal = parseInt(document.getElementById('timeAdjust')?.value, 10) || 0;

    const targets = (document.getElementById('targetGolfs')?.value || '').split(',').map(s => s.trim()).filter(Boolean);
    const excludes = (document.getElementById('excludeGolfs')?.value || '').split(',').map(s => s.trim()).filter(Boolean);

    const fChk1 = document.getElementById('chkFilter1').checked;
    const fChk2 = document.getElementById('chkFilter2').checked;
    const fChk3 = document.getElementById('chkFilter3').checked;

    let currentDate = '';
    let currentGolf = '';
    let currentGolfRaw = '';
    let currentRegion = '';
    let currentGolfmon = '';
    let currentGolfpang = '';
    let currentGolmarket = '';
    let currentGolfrock = '';
    let currentMapped = true;
    const docDefaultSource = detectDocumentSource(text);
    let currentSource = docDefaultSource;
    let currentCourseStartsWithDash = false;

    const rowDataList = [];
    const lines = text.split('\n');

    for (let i = 0; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;

        // 테이블 컬럼 헤더 라인 스킵
        if (line.includes('골프장명') && (line.includes('시간') || line.includes('현장결제') || line.includes('현장/선 결제') || line.includes('현장/선결제'))) {
            currentSource = 'golftop';
            continue;
        }

        // 비-골프 라인(공지/이벤트/식음/인사말 등) 스킵
        if (isNonGolfLine(line)) continue;

        // 공지 시간 범위 라인 (예: "05:46 ~ 06:07 - 10.9") 및 공지 안내 문구는 일반 티타임 생성 대상에서 스킵
        if (line.match(/\d{1,2}:\d{2}\s*(?:~|-|부터)\s*\d{1,2}:\d{2}/) || 
            line.includes('부분선결제') || line.includes('금액 인하') || line.includes('기존예약제외') || line.includes('홈페이지와 별도')) {
            continue;
        }

        // [Format 2 & 3] [YYYY-MM-DD] 또는 [MM-DD] 헤더 스킵 및 날짜 추출
        let dateBracketMatch = line.match(/^\[(\d{4})[-./](\d{1,2})[-./](\d{1,2})\]/) || line.match(/^\[(\d{1,2})[-./](\d{1,2})\]/);
        if (dateBracketMatch) {
            if (dateBracketMatch[3]) {
                currentDate = `${parseInt(dateBracketMatch[2], 10)}.${parseInt(dateBracketMatch[3], 10)}`;
            } else {
                currentDate = `${parseInt(dateBracketMatch[1], 10)}.${parseInt(dateBracketMatch[2], 10)}`;
            }
            if (line.includes('잔여타임')) {
                currentSource = 'golftop';
                const courseAfterBracket = line.replace(/^\[.*?\]/, '').replace(/잔여타임.*/, '').trim();
                if (courseAfterBracket && !isNonGolfLine(courseAfterBracket)) {
                    currentGolfRaw = courseAfterBracket;
                    const mapObj = getMappedName(currentGolfRaw);
                    currentGolf = mapObj.name;
                    currentGolfmon = mapObj.golfmon;
                    currentGolfpang = mapObj.golfpang;
                    currentGolmarket = mapObj.golmarket;
                    currentGolfrock = mapObj.golfrock;
                    currentMapped = mapObj.mapped;
                    const dictRegion = (mapObj.mapped && mapObj.region) ? mapObj.region : (mapObj.region || '');
                    currentRegion = getRegion(dictRegion, currentGolfRaw + ' ' + currentGolf);
                }
            }
            continue;
        }

        // [Format 1 및 각종 날짜 헤더] ▶10.14(수), □■□■10.14(수)□■□■, 10.14(수), 10.14 등
        if (!line.match(/(?:^|[\s\t])\d{1,2}:\d{2}(?:$|[\s\t])/)) {
            let dateGeneral = line.match(/(\d{1,2})[./](\d{1,2})(?:\([가-힣\w]+\))?/);
            if (dateGeneral) {
                if (line.includes('□') || line.includes('■') || line.includes('▶') || line.includes('▷') || line.includes('★') || line.includes('●') || line.match(/^[^\w가-힣]*\d{1,2}[./]\d{1,2}/)) {
                    currentDate = `${parseInt(dateGeneral[1], 10)}.${parseInt(dateGeneral[2], 10)}`;
                    continue;
                }
            }
        }

        // 시간 패턴 검출
        const timeMatch = line.match(/(?:^|[\s\t])(\d{1,2}:\d{2})(?:$|[\s\t])/);
        let isNewLineFormat = false;
        let rawTimeStr = '';
        let roomType = '미표시';
        let waitPax = null;
        let genderInfo = '';
        let rowDate = currentDate;

        if (!timeMatch) {
            if (line.trim().startsWith('-')) {
                currentSource = 'golfrock';
                currentCourseStartsWithDash = true;
            } else {
                currentCourseStartsWithDash = false;
                if (docDefaultSource === 'golftop') {
                    currentSource = 'golftop';
                }
            }
            const cleanLine = line.replace(/^[-*•·■□▲▼▶▷★●◆#※~_=\s]+/, '').trim();
            if (isNonGolfLine(cleanLine)) continue;
            if (/^(?:노캐디|마샬|운전캐디|드라이빙캐디|특수캐디|신입캐디|교육생캐디|캐디|카포|카트포함)$/i.test(cleanLine) || /^\d+인(?:\(.*\))?$/.test(cleanLine)) continue;

            // 1. 대괄호 [ ... ] 및 앞선 특수기호 제거하여 순수 구장명 추출
            // (주의: 소괄호 ()는 '떼제베(누리/가람)' 등 코스 구분을 위한 필수 구장명이므로 무조건 제거하지 않고 보존!)
            let pureCourseName = cleanLine
                .replace(/\[.*?\]/g, '')
                .replace(/^[-*•▶▷□■●★\s]+/g, '')
                .trim();

            if (!pureCourseName) {
                pureCourseName = cleanLine.split(/[\s\t]/)[0].trim();
            }

            if (isNonGolfLine(pureCourseName)) continue;

            // 2. 대괄호 [지역] 추출 (예: [충북 청주], [경기북부], [강원도], [경상도] 등)
            let explicitRegion = '';
            const regionBracketMatch = cleanLine.match(/\[([가-힣\w\s]+)\]/);
            if (regionBracketMatch) {
                const rCand = regionBracketMatch[1].trim();
                const stdCand = toStandardRegion(rCand);
                if (stdCand) {
                    explicitRegion = stdCand;
                } else if (/경기|강원|충청|경상|전라|제주|북부|남부|동부|서부|인천|충북|충남|경북|경남|전북|전남/.test(rCand)) {
                    explicitRegion = getRegion(rCand, pureCourseName);
                }
            }

            currentGolfRaw = pureCourseName;
            const mapObj = getMappedName(currentGolfRaw);
            currentGolf = mapObj.name;
            currentGolfmon = mapObj.golfmon;
            currentGolfpang = mapObj.golfpang;
            currentGolmarket = mapObj.golmarket;
            currentGolfrock = mapObj.golfrock;
            currentMapped = mapObj.mapped;
            // 매핑사전의 지역이 최우선(1순위), 매핑사전에 없을 때만 원문 대괄호 지역 및 구장명 추론 반영
            const dictRegion = (mapObj.mapped && mapObj.region) ? mapObj.region : (mapObj.region || '');
            currentRegion = getRegion(dictRegion || explicitRegion, currentGolfRaw + ' ' + currentGolf);
            continue;
        }

        // --- timeMatch가 있는 경우 (티타임 라인) ---
        rawTimeStr = timeMatch[1];
        let subLinesText = '';

        // 시간 앞의 텍스트 분석 (날짜 및 인라인 구장명)
        const timeIndex = line.indexOf(rawTimeStr);
        const prefix = (timeIndex > 0 ? line.substring(0, timeIndex) : '').trim();

        // 1. 날짜 추출 (prefix 내부에서 10/16, 10.16, 10-16 등)
        const dateMatch = prefix.match(/(\d{1,2})[./\-](\d{1,2})(?:\([가-힣\w]+\))?/);
        if (dateMatch) {
            rowDate = `${parseInt(dateMatch[1], 10)}.${parseInt(dateMatch[2], 10)}`;
            currentDate = rowDate; // 날짜 갱신
        }

        // 2. prefix 내부에 구장명이 포함되어 있는지 검사 (날짜 및 대괄호 제거 후 남은 텍스트)
        if (prefix) {
            let candidateCourse = prefix
                .replace(/\d{1,2}[./\-]\d{1,2}(?:\([가-힣\w]+\))?/g, '')
                .replace(/\[.*?\]/g, '')
                .replace(/\([월화수목금토일]\)/g, '')
                .replace(/^[-*•▶▷□■●★\s]+/g, '')
                .trim();

            // 후보 단어가 있고, 비-골프 단어나 시간(:)이 아니라면 구장명으로 반영
            if (candidateCourse && !candidateCourse.includes(':') && !isNonGolfLine(candidateCourse)) {
                // 선티, 대기 등의 방 구분 키워드 단독인 경우는 구장명이 아님
                if (!/^(?:선티|선티방|대기|대기방|조인|양도)$/.test(candidateCourse)) {
                    isNewLineFormat = true;
                    currentGolfRaw = candidateCourse;
                    const mapObj = getMappedName(currentGolfRaw);
                    currentGolf = mapObj.name;
                    currentGolfmon = mapObj.golfmon;
                    currentGolfpang = mapObj.golfpang;
                    currentGolmarket = mapObj.golmarket;
                    currentGolfrock = mapObj.golfrock;
                    currentMapped = mapObj.mapped;
                    let inlineRegion = '';
                    const rMatch = prefix.match(/\[([가-힣\w\s]+)\]/);
                    if (rMatch) {
                        inlineRegion = toStandardRegion(rMatch[1].trim()) || rMatch[1].trim();
                    }
                    const dictRegion = (mapObj.mapped && mapObj.region) ? mapObj.region : (mapObj.region || '');
                    currentRegion = getRegion(dictRegion || inlineRegion, currentGolfRaw + ' ' + currentGolf);
                }
            }
        }

        if (line.includes('선티') || line.includes('대기')) roomType = '선티방';

        // 부속 줄 파싱 (다음 줄이 현재 티타임의 대기/인원/옵션 부속 정보인 경우만 안전하게 소비)
        while (i + 1 < lines.length) {
            let nextLine = lines[i + 1].trim();
            // 1. 빈 줄이 나오면 현재 티타임/섹션 종료 -> 즉시 중단 (절대로 다음 섹션으로 건너뛰지 않음)
            if (!nextLine) break;

            // 2. 비-골프 라인, 날짜 헤더 기호, 시간 패턴이 있으면 다음 블록/타임 -> 즉시 중단
            if (isNonGolfLine(nextLine)) break;
            if (nextLine.includes('□■') || nextLine.includes('■□') || nextLine.includes('★') || nextLine.includes('●') || nextLine.includes('◆')) break;
            if ((nextLine.includes('▶') || nextLine.includes('▷')) && !/(?:노캐디|마샬|운전|캐디|식사|카포|카트|선입|현장|대기|\d+인)/i.test(nextLine)) break;
            if (/(?:^|[\s\t])\d{1,2}:\d{2}(?:$|[\s\t])/.test(nextLine)) break;

            // 3. 지역 대괄호([경기북부], [강원도], [충청도], [경상도] 등)가 있으면 새로운 구장 헤더 -> 즉시 중단
            if (/\[(?:경기|강원|충청|경상|전라|제주|북부|남부|동부|서부|인천|충북|충남|경북|경남|전북|전남)/.test(nextLine)) break;

            // 4. 인원/대기/성별 패턴 검사
            let nextPaxMatch = nextLine.match(/^(\d+)인(?:\/([^\s(/]+))?(?:\((.*?)\))?/) || 
                               nextLine.match(/^대기(?:중)?\s*[:\s]?\s*(\d+)/) || 
                               nextLine.match(/^\[\s*(\d+)인(?:\/([^\s(/]+))?\s*\]/) ||
                               nextLine.match(/^\[\s*대기(?:중)?\s*[:\s]?\s*(\d+)\s*\]/) ||
                               nextLine.match(/^(\d+)인$/);

            if (nextPaxMatch) {
                waitPax = parseInt(nextPaxMatch[1], 10);
                genderInfo = nextPaxMatch[2] || nextPaxMatch[3] || '';
                subLinesText += ' ' + nextLine;
                i++;
                continue;
            }

            // 5. 캐디/카트/식사/선입금 등 부속 옵션 및 비고 라인인지 검사
            const isOptionLine = /^(?:노캐디|마샬|운전캐디|드라이빙캐디|특수캐디|신입캐디|교육생캐디|캐디|카포|카트포함|식사포함|조식포함|모닝박스|모닝식사|식사제공|선입|선입금|현장|현장결제|비고)/i.test(nextLine) ||
                                 /^[※*#•·\-▶▷]\s*(?:비고|참고|특이사항|노캐디|카포|캐디피|카트피|식사|조식)/i.test(nextLine) ||
                                 /^(?:남여|부부|커플|남자만|여자만|남성만|여성만)/i.test(nextLine);

            if (isOptionLine) {
                subLinesText += ' ' + nextLine;
                i++;
                continue;
            }

            // 6. 위 부속 조건에 해당하지 않는 라인은 새로운 구장 헤더나 다른 텍스트이므로 절대 소비하지 않고 즉시 메인 루프로 반환
            break;
        }

        if (waitPax === null) {
            let inlineMatch = line.match(/대기중\s*[:\s]?\s*(\d+)/) || line.match(/대기\s*[:\s]?\s*(\d+)/) || line.match(/대기\s*(\d+)인/) || line.match(/(\d+)인\s*\((.*?)\)/);
            if (inlineMatch) {
                waitPax = parseInt(inlineMatch[1], 10);
                if (inlineMatch[2]) genderInfo = inlineMatch[2];
            }
        }

        // 구장 필터링
        if (targets.length > 0 && !targets.some(t => currentGolf.includes(t) || currentGolfRaw.includes(t))) continue;
        if (excludes.length > 0 && excludes.some(t => currentGolf.includes(t) || currentGolfRaw.includes(t))) continue;

        const timeParts = rawTimeStr.split(':');
        let currentMins = parseInt(timeParts[0], 10) * 60 + parseInt(timeParts[1], 10);

        let partMatched = false;
        if (currentMins < 10 * 60) { if (fChk1) partMatched = true; }
        else if (currentMins < 16 * 60) { if (fChk2) partMatched = true; }
        else { if (fChk3) partMatched = true; }
        if (!partMatched) continue;

        let shiftedMins = currentMins - adjustMinsVal;
        if (shiftedMins < 0) shiftedMins += 24 * 60;
        let hr = Math.floor(shiftedMins / 60);
        let mn = shiftedMins % 60;
        let timeInt = (hr < 10 ? '0' + hr : '' + hr) + (mn < 10 ? '0' + mn : '' + mn);

        // 그린피 파싱
        const fullCheckText = line + ' ' + subLinesText;
        let fee = '';
        let feeVal = null;
        let isPrepaid = false;
        let hasSlashFee = false;
        let slashFrontVal = 0;
        let slashBackVal = 0;

        // 1. [요금확인 / 9.9만] 처럼 앞이 '요금확인'이고 뒤에만 금액이 있는 경우
        let feeConfirmMatch = line.match(/요금확인\s*\/\s*([0-9.]+)\s*(?:만|만원)?/) || 
                              subLinesText.match(/요금확인\s*\/\s*([0-9.]+)\s*(?:만|만원)?/);
        if (feeConfirmMatch) {
            feeVal = parseFloat(feeConfirmMatch[1]);
            fee = feeVal.toString();
            // '선입' 또는 '선입금' 단어가 실제로 명시된 경우만 선입금 체크 (요금확인은 선입금이 아님)
            isPrepaid = /선입|선입금/.test(fullCheckText) && !fullCheckText.includes('현장');
        }

        // 2. [현장9만+선입1만] 처럼 현장과 선입이 함께 있는 경우 -> 두 금액 합산(또는 대괄호 앞 총금액), 선입금 체크 안 함!
        if (feeVal === null) {
            let preTotalMatch = line.match(/([0-9.]+)\s*(?:만|만원)\s*\[(?:[^\]]*현장[^\]]*선입|[^\]]*선입[^\]]*현장)[^\]]*\]/) ||
                                subLinesText.match(/([0-9.]+)\s*(?:만|만원)\s*\[(?:[^\]]*현장[^\]]*선입|[^\]]*선입[^\]]*현장)[^\]]*\]/);
            let plusMatch = line.match(/(?:현장\s*([0-9.]+)\s*만?\s*\+\s*선입\s*([0-9.]+)\s*만?|선입\s*([0-9.]+)\s*만?\s*\+\s*현장\s*([0-9.]+)\s*만?)/) ||
                            subLinesText.match(/(?:현장\s*([0-9.]+)\s*만?\s*\+\s*선입\s*([0-9.]+)\s*만?|선입\s*([0-9.]+)\s*만?\s*\+\s*현장\s*([0-9.]+)\s*만?)/);

            if (plusMatch) {
                let v1 = parseFloat(plusMatch[1] || plusMatch[3]) || 0;
                let v2 = parseFloat(plusMatch[2] || plusMatch[4]) || 0;
                feeVal = Math.round((v1 + v2) * 100) / 100;
                fee = feeVal.toString();
                isPrepaid = false;
            } else if (preTotalMatch) {
                feeVal = parseFloat(preTotalMatch[1]);
                fee = feeVal.toString();
                isPrepaid = false;
            }
        }

        // 3. [13.9만 / 1만] 처럼 슬래시로 현장결제와 선결제가 나뉜 경우 -> 두 금액 합산, 현장결제가 있으므로 선입금 체크 안 함!
        // ※ 주의: [14만 / 1인], [14만/1인대기], [14만 / 3인] 등 슬래시 뒤가 인원수인 경우 금액 합산 대상에서 철저히 제외
        if (feeVal === null) {
            let slashFeeMatch = line.match(/([0-9.]+)\s*(?:만|만원)?\s*\/\s*([0-9.]+)\s*(?:만|만원)(?!\s*[인명팀분])/) || 
                                line.match(/\[\s*([0-9.]+)\s*(?:만|만원)?\s*\/\s*([0-9.]+)\s*(?:만|만원)?\s*\]/) ||
                                subLinesText.match(/([0-9.]+)\s*(?:만|만원)?\s*\/\s*([0-9.]+)\s*(?:만|만원)(?!\s*[인명팀분])/);
            if (slashFeeMatch) {
                let frontVal = parseFloat(slashFeeMatch[1]) || 0;
                let backVal = parseFloat(slashFeeMatch[2]) || 0;
                feeVal = Math.round((frontVal + backVal) * 100) / 100;
                fee = feeVal.toString();
                isPrepaid = false; // 앞쪽 현장결제가 있으므로 선입금 체크 안 함!
                hasSlashFee = true;
                slashFrontVal = frontVal;
                slashBackVal = backVal;
            }
        }

        // 4. [선입9.9만] 처럼 현장결제 없이 '선입 금액만' 단독으로 있는 경우 -> 선입금 전용!
        if (feeVal === null) {
            let prepaidOnlyBracket = line.match(/\[\s*선입\s*([0-9.]+)\s*(?:만|만원)?\s*\]/) ||
                                     subLinesText.match(/\[\s*선입\s*([0-9.]+)\s*(?:만|만원)?\s*\]/);
            if (prepaidOnlyBracket && !fullCheckText.includes('현장')) {
                feeVal = parseFloat(prepaidOnlyBracket[1]);
                fee = feeVal.toString();
                isPrepaid = true;
            }
        }

        // 5. 일반 단일 금액 (예: "06:33 9.9만[현장9.9만]", "07:07 17.9만", "5.9만")
        if (feeVal === null) {
            let pureLine = line.replace(/(\d{1,2}:\d{2})/, '');
            let singleFeeMatch = pureLine.match(/([0-9.]+)\s*(?:만|만원)/) || 
                                 subLinesText.match(/([0-9.]+)\s*(?:만|만원)/);
            if (singleFeeMatch) {
                feeVal = parseFloat(singleFeeMatch[1]);
                fee = feeVal.toString();

                // 단일 금액에서 오직 '선입' 단어만 있고 '현장'이 없는 경우만 선입금 체크
                let hasPrepaidWord = /\[\s*선입|선입금\s*[0-9.]|선입\s*[0-9.]/.test(fullCheckText);
                let hasOnsiteWord = fullCheckText.includes('현장');
                if (hasPrepaidWord && !hasOnsiteWord) {
                    isPrepaid = true;
                } else {
                    isPrepaid = false;
                }
            }
        }

        // 카트포함 차감 로직
        if (feeVal !== null && (fullCheckText.includes('카트포함') || fullCheckText.includes('카포'))) {
            let deduct = 2.5;
            if (currentGolf.includes('양평TPC') || currentGolfRaw.includes('양평TPC')) {
                deduct = 3.0;
            }
            feeVal = Math.max(0, feeVal - deduct);
            fee = Number.isInteger(feeVal) ? feeVal.toString() : feeVal.toFixed(1);
        }

        // 원본 데이터에서 선입금 액수 추출 (공지가 변환 시 가산용: 예: [현장17만+선입1만] -> 1.0, 15만[현장15만] -> 0)
        let rowPrepaidAmount = 0;
        const prepaidWordMatch = fullCheckText.match(/(?:선입(?:금)?|선결제)\s*[:=\-]?\s*([0-9.]+)\s*(?:만|만원)?/i);
        if (prepaidWordMatch) {
            rowPrepaidAmount = parseFloat(prepaidWordMatch[1]) || 1.0;
        } else if (hasSlashFee && slashBackVal > 0) {
            rowPrepaidAmount = slashBackVal;
        } else if (/(?:선입|선입금|선결제)/.test(fullCheckText) && !fullCheckText.includes('현장')) {
            rowPrepaidAmount = 1.0;
        }

        // 선입금 추가 전 기준 금액 보관 (선입금 체크해제 시 원복용)
        const baseFeeVal = feeVal;
        const baseFeeStr = feeVal !== null ? (Number.isInteger(feeVal) ? feeVal.toString() : feeVal.toFixed(1)) : (fee || '');

        // 캐디 판별 (신입->교육생캐디, 드라이빙/특수->운전캐디)
        let cady = '캐디';
        if (fullCheckText.includes('마샬')) cady = '마샬';
        else if (fullCheckText.includes('운전') || fullCheckText.includes('드라이빙') || fullCheckText.includes('특수')) cady = '운전캐디';
        else if (fullCheckText.includes('신입') || fullCheckText.includes('교육생')) cady = '교육생캐디';
        else if (fullCheckText.includes('노캐디') || noCaddys.some(nc => currentGolf.includes(nc) || currentGolfRaw.includes(nc))) {
            cady = '노캐디';
        }

        // 조인조건 판별: '무관', '남자', '여자', '부부/커플' (기본값: '무관')
        let joinCondition = '무관';
        if (fullCheckText.includes('여여불가') || fullCheckText.includes('남여불가') || fullCheckText.includes('남녀불가') || fullCheckText.includes('남남불가')) {
            joinCondition = '무관';
        } else if (fullCheckText.includes('남여만') || fullCheckText.includes('남녀만') || fullCheckText.includes('부부/커플') || fullCheckText.includes('부부') || fullCheckText.includes('커플')) {
            joinCondition = '부부/커플';
        } else if (fullCheckText.includes('남자만') || fullCheckText.includes('남성만') || fullCheckText.includes('남자 전용') || fullCheckText.includes('남성 전용') || fullCheckText.includes('남남만')) {
            joinCondition = '남자';
        } else if (fullCheckText.includes('여자만') || fullCheckText.includes('여성만') || fullCheckText.includes('여자 전용') || fullCheckText.includes('여성 전용') || fullCheckText.includes('여여만')) {
            joinCondition = '여자';
        } else {
            joinCondition = '무관';
        }

        // 식사포함 여부 판별 (식사포함, 조식포함, 중식포함, 석식포함, 식사제공, 조식제공, 모닝식사, 모닝박스 등)
        let isMeal = false;
        if (/식사포함|조식포함|중식포함|석식포함|식사제공|조식제공|식음제공|모닝박스포함|모닝박스제공|모닝식사|식포\b/i.test(fullCheckText) ||
            /(?:^|[\s/▶▷\[(])(?:식사|조식)(?:[)\]\s/]|$)/.test(fullCheckText)) {
            if (!fullCheckText.includes('식사불가') && !fullCheckText.includes('식사미포함') && !fullCheckText.includes('식사 미포함')) {
                isMeal = true;
            }
        }

        // 요청 인원 계산 (총 4인 기준: 대기 중인 인원을 뺀 나머지 인원 요청)
        // 대기 3인 -> 1인 요청 (4 - 3 = 1)
        // 대기 2인 -> 2인 요청 (4 - 2 = 2)
        // 대기 1인 -> 3인 요청 (4 - 1 = 3)
        // 대기 없음/양도 -> 4인 요청 (기본값)
        let waitCount = null;

        let explicitWaitMatch = fullCheckText.match(/대기(?:중)?\s*[:\s]?\s*(\d+)인?/) ||
                                fullCheckText.match(/(\d+)인\s*대기/);
        if (explicitWaitMatch) {
            waitCount = parseInt(explicitWaitMatch[1], 10);
            roomType = '선티방';
        } else if (waitPax !== null) {
            waitCount = waitPax;
            roomType = '선티방';
        } else {
            let paxMatch = fullCheckText.match(/(?:^|[\s\t(\[/])(\d+)인(?=[)\s\t/\]]|$)/);
            if (paxMatch) {
                let p = parseInt(paxMatch[1], 10);
                if (p >= 1 && p <= 3) {
                    waitCount = p;
                    roomType = '선티방';
                }
            }
        }

        // 조인 인원 존재 여부 판별 (1~3인 대기, 선티방, 대기/조인 문구 등)
        const hasJoinPax = Boolean(
            explicitWaitMatch ||
            (waitPax !== null && waitPax > 0 && waitPax < 4) ||
            (waitCount !== null && waitCount > 0 && waitCount < 4) ||
            roomType === '선티방' ||
            roomType === '대기방' ||
            fullCheckText.includes('대기') ||
            fullCheckText.includes('선티') ||
            fullCheckText.includes('조인') ||
            /(?:^|[\s\t(\[/])([1-3])인(?=[)\s\t/\]]|$)/.test(fullCheckText)
        );

        // 양도용 원클릭인 경우: 조인 인원이 없는 순수 양도(4인 전체) 건만 선별!
        if (type === 'transfer' && hasJoinPax) {
            continue;
        }

        let reqPax = 4;
        if (type === 'transfer') {
            reqPax = 4;
            roomType = '양도';
        } else {
            if (waitCount === 3) reqPax = 1;
            else if (waitCount === 2) reqPax = 2;
            else if (waitCount === 1) reqPax = 3;
            else reqPax = 4;
        }

        let sizenum = `${reqPax}인`;

        // ★ [사용자 규칙] 인원이 있는 건(1인, 2인, 3인 또는 대기/조인 인원)은 모두 무조건 '선티방'!
        const hasPersonnel = (reqPax >= 1 && reqPax <= 3) || (waitCount !== null && waitCount > 0 && waitCount < 4) || (waitPax !== null && waitPax > 0 && waitPax < 4) || hasJoinPax;
        if (hasPersonnel && type !== 'transfer') {
            roomType = '선티방';
        }

        // 선티, 대기티 판별: 선티는 금액에 선입금이 이미 적용되어 있으므로 공지가 변환 대상에서 제외
        const isSeontiOrDaegi = (
            roomType === '선티방' ||
            roomType.includes('선티') ||
            roomType.includes('대기') ||
            fullCheckText.includes('선티') ||
            fullCheckText.includes('대기') ||
            isPrepaid ||
            hasPersonnel
        );

        // 기본 표시 금액 (선입금 가산 토글 제거됨: 원본 데이터 기반 파싱 금액 그대로 사용)
        let feeDisplay = fee;

        // 특정구장 가격 변경 가감 사전 적용 (변환 시 즉시 반영 - 선티/대기방 제외)
        const initialCourseAdj = !isSeontiOrDaegi ? getCoursePriceAdjustment(currentGolf, currentGolfRaw, currentGolfmon, timeInt) : 0;
        if (initialCourseAdj !== 0 && feeVal !== null) {
            const currentNum = parseFloat(feeDisplay) || feeVal;
            const adjNum = Math.max(0, Math.round((currentNum + initialCourseAdj) * 100) / 100);
            feeDisplay = Number.isInteger(adjNum) ? adjNum.toString() : adjNum.toFixed(1);
        }

        // 출처 판별 (골프탑 2가지 형식만 'golftop', 그 외에는 'golfrock')
        let rowSource = currentSource || docDefaultSource;
        const fullCheck = line + ' ' + subLinesText;

        // 1. 구장명이 '-'로 시작하면 무조건 골프락! (+선입이 있어도 무조건 골프락)
        if (currentCourseStartsWithDash || currentGolfRaw.startsWith('-')) {
            rowSource = 'golfrock';
        } 
        // 2. 골프탑 2가지 형식(카톡 10/20(화) 17:18 날짜 접두사 또는 잔여타임 표 형식) 검사
        else if (
            /\d{1,2}\/\d{1,2}\([가-힣]\)\s+\d{1,2}:\d{2}/.test(fullCheck) ||
            hasSlashFee || 
            fullCheck.includes('잔여타임') ||
            fullCheck.includes('현장/선 결제') ||
            fullCheck.includes('현장/선결제') ||
            /Bella|Monti|Challenger|Champion/i.test(fullCheck)
        ) {
            rowSource = 'golftop';
        } 
        // 3. 골프탑 형식 3 (구장명 '-' 없고 대기중:숫자[ 또는 (남남) 등)
        else if (
            /대기(?:중)?\s*:\s*\d+\s*\[/.test(fullCheck) || 
            /\([남여]{1,2}\)/.test(fullCheck) || 
            /\[현장\s*\d+(?:\.\d+)?\]/.test(fullCheck)
        ) {
            rowSource = 'golftop';
        } else {
            rowSource = currentSource || docDefaultSource || 'golfrock';
        }

        // 테이블 행(TR) 생성
        const tr = document.createElement('tr');
        tr.dataset.source = rowSource;
        tr.dataset.roomType = roomType;
        tr.dataset.origRoomType = roomType;
        tr.dataset.isPrepaid = isPrepaid ? 'true' : 'false';
        tr.dataset.isMeal = isMeal ? 'true' : 'false';
        tr.dataset.isSeontiOrDaegi = isSeontiOrDaegi ? 'true' : 'false';
        tr.dataset.isMapped = currentMapped ? 'true' : 'false';
        tr.dataset.rawGolf = currentGolfRaw;
        tr.dataset.golfmonGolf = currentGolfmon;
        tr.dataset.golfpangGolf = currentGolfpang;
        tr.dataset.golmarketGolf = currentGolmarket;
        tr.dataset.golfrockGolf = currentGolfrock;
        tr.dataset.baseFee = baseFeeStr;
        tr.dataset.origBaseFee = baseFeeStr;
        tr.dataset.hasSlashFee = hasSlashFee ? 'true' : 'false';
        tr.dataset.slashFrontVal = slashFrontVal.toString();
        tr.dataset.slashBackVal = slashBackVal.toString();
        tr.dataset.prepaidAmount = rowPrepaidAmount.toString();
        if (initialCourseAdj !== 0) {
            tr.dataset.coursePriceAdj = initialCourseAdj.toString();
        }

        const finalDate = rowDate || currentDate;
        tr.innerHTML = `
            <td>${finalDate}</td>
            <td>${currentRegion}</td>
            <td>${currentGolf}</td>
            <td>${timeInt}</td>
            <td>${feeDisplay}</td>
            <td>${cady}</td>
            <td>${joinCondition}</td>
            <td>${sizenum}</td>
        `;

        rowDataList.push({
            date: finalDate,
            region: currentRegion,
            golf: currentGolf,
            rawGolf: currentGolfRaw,
            golfmonGolf: currentGolfmon,
            golfpangGolf: currentGolfpang,
            golmarketGolf: currentGolmarket,
            golfrockGolf: currentGolfrock,
            isMapped: currentMapped,
            time: timeInt,
            fee: feeDisplay,
            baseFee: baseFeeStr,
            origBaseFee: baseFeeStr,
            hasSlashFee: hasSlashFee,
            slashFrontVal: slashFrontVal,
            slashBackVal: slashBackVal,
            prepaidAmount: rowPrepaidAmount,
            cady: cady,
            condition: joinCondition,
            sizenum: sizenum,
            isMeal: isMeal,
            roomType: roomType,
            origRoomType: roomType,
            isSeontiOrDaegi: isSeontiOrDaegi,
            coursePriceAdj: initialCourseAdj !== 0 ? initialCourseAdj.toString() : '',
            source: rowSource,
            tr: tr
        });
    }

    // 날짜 및 시간순 정렬
    rowDataList.sort((a, b) => {
        const dA = a.date.split('.'), dB = b.date.split('.');
        const mA = parseInt(dA[0], 10) || 0, mB = parseInt(dB[0], 10) || 0;
        if (mA !== mB) return mA - mB;
        const dayA = parseInt(dA[1], 10) || 0, dayB = parseInt(dB[1], 10) || 0;
        if (dayA !== dayB) return dayA - dayB;
        return (a.time || '').localeCompare(b.time || '');
    });

    // 미등록 구장 목록 추출 (유효한 티타임 행을 생성한 구장 중 사전에 미등록된 구장)
    const unmappedCourses = [];
    const seen = new Set();
    rowDataList.forEach(r => {
        if (!r.isMapped && r.rawGolf && !seen.has(r.rawGolf)) {
            seen.add(r.rawGolf);
            unmappedCourses.push(r.rawGolf);
        }
    });

    return { rowDataList, unmappedCourses };
}

// 날짜 비교 헬퍼 함수
function compareDateStrings(dAStr, dBStr) {
    if (!dAStr && !dBStr) return 0;
    if (!dAStr) return 1;
    if (!dBStr) return -1;
    const dA = dAStr.split('.'), dB = dBStr.split('.');
    const mA = parseInt(dA[0], 10) || 0, mB = parseInt(dB[0], 10) || 0;
    if (mA !== mB) return mA - mB;
    const dayA = parseInt(dA[1], 10) || 0, dayB = parseInt(dB[1], 10) || 0;
    return dayA - dayB;
}

let currentSortType = 'time'; // 'time' or 'golf'
let currentSortDir = 'asc';   // 'asc' or 'desc'

function updateSortBarUI() {
    const btnGolf = document.getElementById('btnSortGolf');
    const btnTime = document.getElementById('btnSortTime');
    const arrowGolf = document.getElementById('arrowSortGolf');
    const arrowTime = document.getElementById('arrowSortTime');

    if (btnGolf && arrowGolf) {
        if (currentSortType === 'golf') {
            btnGolf.classList.add('active');
            arrowGolf.innerText = currentSortDir === 'asc' ? '▲ ㄱ-ㅎ' : '▼ ㅎ-ㄱ';
        } else {
            btnGolf.classList.remove('active');
            arrowGolf.innerText = '⇅';
        }
    }

    if (btnTime && arrowTime) {
        if (currentSortType === 'time') {
            btnTime.classList.add('active');
            arrowTime.innerText = currentSortDir === 'asc' ? '▲ 이른순' : '▼ 늦은순';
        } else {
            btnTime.classList.remove('active');
            arrowTime.innerText = '⇅';
        }
    }
}

function sortTableAndCards(type) {
    const tbody = document.getElementById('tableBody');
    if (!tbody) return;
    const trs = Array.from(tbody.querySelectorAll('tr'));
    if (trs.length === 0) {
        showToast('정렬할 티타임이 없습니다.');
        return;
    }

    if (currentSortType === type) {
        // 동일 정렬 항목 다시 클릭 -> 방향 반전
        currentSortDir = (currentSortDir === 'asc') ? 'desc' : 'asc';
    } else {
        // 다른 정렬 항목 클릭 -> 기본 오름차순(asc) 시작
        currentSortType = type;
        currentSortDir = 'asc';
    }

    trs.sort((a, b) => {
        const dateA = a.cells[0]?.textContent.trim() || '';
        const dateB = b.cells[0]?.textContent.trim() || '';
        const golfA = a.cells[2]?.textContent.trim() || '';
        const golfB = b.cells[2]?.textContent.trim() || '';
        const timeA = (a.cells[3]?.textContent.trim() || '').replace(':', '');
        const timeB = (b.cells[3]?.textContent.trim() || '').replace(':', '');

        if (currentSortType === 'golf') {
            // 1순위: 구장명 (한 번 누르면 ㄱㄴㄷ 순, 한 번 더 누르면 역순)
            const cmpGolf = golfA.localeCompare(golfB, 'ko');
            if (cmpGolf !== 0) {
                return currentSortDir === 'asc' ? cmpGolf : -cmpGolf;
            }
            // 2순위: 날짜 (오름차순)
            const cmpDate = compareDateStrings(dateA, dateB);
            if (cmpDate !== 0) return cmpDate;
            // 3순위: 시간 (오름차순)
            return (parseInt(timeA, 10) || 0) - (parseInt(timeB, 10) || 0);
        } else {
            // 1순위: 날짜 (날짜별 묶음 유지)
            const cmpDate = compareDateStrings(dateA, dateB);
            if (cmpDate !== 0) return cmpDate;
            // 2순위: 시간 (한 번 누르면 이른 시간부터, 한 번 더 누르면 늦은 시간부터)
            const tA = parseInt(timeA, 10) || 0;
            const tB = parseInt(timeB, 10) || 0;
            if (tA !== tB) {
                return currentSortDir === 'asc' ? (tA - tB) : (tB - tA);
            }
            // 3순위: 구장명 (가나다순)
            return golfA.localeCompare(golfB, 'ko');
        }
    });

    trs.forEach(tr => tbody.appendChild(tr));
    renderCardList();
    saveCurrentTableState();
    updateSortBarUI();

    if (currentSortType === 'golf') {
        showToast(currentSortDir === 'asc' ? '⛳ 구장명 가나다순(ㄱ→ㅎ) 정렬' : '⛳ 구장명 역순(ㅎ→ㄱ) 정렬');
    } else {
        showToast(currentSortDir === 'asc' ? '⏰ 이른 시간순 정렬' : '⏰ 늦은 시간순 정렬');
    }
}

function applyParsedData(parsed, type) {
    const tbody = document.getElementById('tableBody');
    if (!tbody) return;
    tbody.innerHTML = '';

    parsed.rowDataList.forEach(item => tbody.appendChild(item.tr));
    applyAllActiveNoticeRules();
    currentSortType = 'time';
    currentSortDir = 'asc';
    updateSortBarUI();
    renderCardList();
    saveCurrentTableState();
    if (type === 'transfer') {
        showToast(`총 ${parsed.rowDataList.length}건의 양도 건이 선별되었습니다. (조인 건 제외)`);
    } else {
        showToast(`총 ${parsed.rowDataList.length}건이 변환되었습니다.`);
    }
}

function processData(type) {
    const parsed = parseInputData(type);
    applyParsedData(parsed, type);
    return parsed;
}

// 티타임 카드 렌더링 함수 (AdGuard 스타일 컴팩트 모바일 뷰 & 드래그 다중 선택 지원)
let isCardDragging = false;
let dragTargetState = false;
let lastHoveredIndex = null;

function renderCardList() {
    const cardContainer = document.getElementById('cardList');
    if (!cardContainer) return;
    cardContainer.innerHTML = '';
    const trs = Array.from(document.querySelectorAll('#dataTable tbody tr'));

    if (trs.length === 0) {
        cardContainer.innerHTML = `
            <div class="empty-state">
                <div class="empty-icon">⛳</div>
                <div class="empty-title">변환된 티타임이 없습니다</div>
                <div class="empty-desc">위 입력창에 티타임을 붙여넣고<br>[조인용 원클릭]을 실행해주세요.</div>
            </div>`;
        updateSelectedBadge();
        return;
    }

    trs.forEach((tr, idx) => {
        const cells = tr.querySelectorAll('td');
        const date = cells[0]?.textContent || '';
        const region = cells[1]?.textContent || '';
        const golf = cells[2]?.textContent || '';
        const time = cells[3]?.textContent || '';
        const fee = cells[4]?.textContent || '';
        const cady = cells[5]?.textContent || '';
        const condition = cells[6]?.textContent || '';
        const sizenum = cells[7]?.textContent || '';
        const isSelected = tr.classList.contains('selected');
        const roomType = tr.dataset.roomType || '';
        const isMapped = tr.dataset.isMapped !== 'false';
        const isNoticeAdjusted = tr.dataset.noticeAdjusted === 'true';
        const noticePrice = tr.dataset.noticePrice || '';
        const noticeTagDesc = tr.dataset.noticeTagDesc || '';
        const hasSlashFee = tr.dataset.hasSlashFee === 'true';
        const slashBackVal = tr.dataset.slashBackVal || '';
        const noticeReceivedAt = tr.dataset.noticeReceivedAt || '';
        let noticeTagHtml = '';
        if (isNoticeAdjusted) {
            const timeBadge = noticeReceivedAt ? ` <span style="font-size:9.5px; opacity:0.85;">🕒 ${noticeReceivedAt}</span>` : '';
            const timeTooltip = noticeReceivedAt ? ` [수신: ${noticeReceivedAt}]` : '';

            if (noticeTagDesc) {
                noticeTagHtml = `<span class="card-tag notice-tag" data-course="${escapeAttr(golf)}" style="cursor: pointer;" title="공지 자동 적용${timeTooltip}: 클릭 시 공지 전문 보기">📢 공지 ${noticeTagDesc}${timeBadge}</span>`;
            } else if (noticePrice) {
                if (hasSlashFee && slashBackVal) {
                    noticeTagHtml = `<span class="card-tag notice-tag" data-course="${escapeAttr(golf)}" style="cursor: pointer;" title="공지 금액 ${noticePrice}만 + 선결제 ${slashBackVal}만${timeTooltip}: 클릭 시 공지 전문 보기">📢 공지 ${noticePrice}만 / ${slashBackVal}만${timeBadge}</span>`;
                } else {
                    noticeTagHtml = `<span class="card-tag notice-tag" data-course="${escapeAttr(golf)}" style="cursor: pointer;" title="공지 금액 ${noticePrice}만 자동 적용${timeTooltip}: 클릭 시 공지 전문 보기">📢 공지 ${noticePrice}만${timeBadge}</span>`;
                }
            }
        }

        const coursePriceAdj = parseFloat(tr.dataset.coursePriceAdj) || 0;
        let courseAdjTagHtml = '';
        if (coursePriceAdj !== 0) {
            const sign = coursePriceAdj > 0 ? `+${coursePriceAdj}` : `${coursePriceAdj}`;
            const partNum = getTimePartNumber(time);
            const partLabel = `${partNum}부`;
            courseAdjTagHtml = `<span class="card-tag course-adj-tag" title="특정구장 가격조정 [${partLabel}] (${sign}만 적용)">🎯 ${partLabel} ${sign}만</span>`;
        }

        // 가격 인하 감지 (이전 등록 이력 대비 또는 공지/특정구장 할인 적용 대비)
        const currentFeeNum = parseFloat((fee || '').toString().replace(/[^\d.]/g, '')) || 0;
        const histKey1 = makeHistoryKey(date, golf, time);
        const histKey2 = makeHistoryKey(date, tr.dataset.rawGolf, time);
        const histRecord = registeredHistory[histKey1] || registeredHistory[histKey2];

        let prevFee = null;
        let priceDiff = 0;
        let isPriceDropped = false;

        if (histRecord && typeof histRecord.fee === 'number' && histRecord.fee > currentFeeNum && currentFeeNum > 0) {
            prevFee = histRecord.fee;
            priceDiff = Math.round((currentFeeNum - prevFee) * 10) / 10;
            isPriceDropped = true;
        } else if (tr.dataset.baseFee && parseFloat(tr.dataset.baseFee) > currentFeeNum && currentFeeNum > 0) {
            prevFee = parseFloat(tr.dataset.baseFee);
            priceDiff = Math.round((currentFeeNum - prevFee) * 10) / 10;
            isPriceDropped = true;
        } else if (parseFloat(tr.dataset.coursePriceAdj) < 0) {
            const adj = parseFloat(tr.dataset.coursePriceAdj);
            prevFee = Math.round((currentFeeNum - adj) * 10) / 10;
            priceDiff = adj;
            isPriceDropped = true;
        }

        let priceDropTagHtml = '';
        if (isPriceDropped && prevFee !== null) {
            tr.dataset.isPriceDropped = 'true';
            tr.dataset.prevFee = prevFee.toString();
            tr.dataset.priceDiff = priceDiff.toString();
            const sign = priceDiff > 0 ? `+${priceDiff}` : `${priceDiff}`;
            priceDropTagHtml = `<span class="card-tag price-dropped" title="이전 등록/기준가 ${prevFee}만 ➔ 현재 ${fee}만 (${sign}만 인하)">📉 ${prevFee}만➔${fee}만 (${sign}만)</span>`;
        } else {
            delete tr.dataset.isPriceDropped;
            delete tr.dataset.prevFee;
            delete tr.dataset.priceDiff;
        }

        const card = document.createElement('div');
        card.className = 'tee-card' + (isSelected ? ' selected' : '');
        card.dataset.index = idx;

        let regionBg = '#EDE9FE';
        let regionColor = '#5C479C';
        if (region.includes('남부')) { regionBg = '#FEF3C7'; regionColor = '#92400E'; }
        else if (region.includes('북부')) { regionBg = '#DBEAFE'; regionColor = '#1E40AF'; }
        else if (region.includes('동부')) { regionBg = '#DCFCE7'; regionColor = '#166534'; }
        else if (region.includes('인천') || region.includes('경인')) { regionBg = '#E0E7FF'; regionColor = '#3730A3'; }
        else if (region.includes('충청')) { regionBg = '#F3E8FF'; regionColor = '#6B21A8'; }
        else if (region.includes('강원')) { regionBg = '#E0F2FE'; regionColor = '#0369A1'; }
        else if (region.includes('전라')) { regionBg = '#FFEDD5'; regionColor = '#9A3412'; }
        else if (region.includes('경상')) { regionBg = '#FEE2E2'; regionColor = '#991B1B'; }
        else if (region.includes('제주')) { regionBg = '#CCFBF1'; regionColor = '#115E59'; }

        const isSeonti = (
            tr.dataset.isSeontiOrDaegi === 'true' ||
            roomType === '선티방' ||
            roomType.includes('선티') ||
            tr.dataset.isPrepaid === 'true' ||
            /^[123]인$/.test(sizenum)
        );
        const isMeal = tr.dataset.isMeal === 'true';
        const source = tr.dataset.source || 'golfrock';

        card.innerHTML = `
            <div class="card-check">
                <input type="checkbox" ${isSelected ? 'checked' : ''} tabindex="-1">
            </div>
            <div class="card-main">
                <div class="card-row-top">
                    <div class="card-title-group">
                        <span class="card-golf">${golf}</span>
                        ${date ? `<span class="card-date">${date}</span>` : ''}
                        ${!isMapped ? `<span class="card-tag unmapped-tag" title="매핑사전에 미등록된 구장 (자동선택 제외)">⚠️ 미등록</span>` : ''}
                    </div>
                    <div class="card-meta-group">
                        ${region ? `<span class="card-region" style="background:${regionBg}; color:${regionColor};">${region}</span>` : ''}
                        <span class="card-source-badge ${source === 'golftop' ? 'source-top' : 'source-rock'}" data-index="${idx}" title="${source === 'golftop' ? '골프탑 데이터 (클릭 시 락/탑 변경)' : '골프락 데이터 (클릭 시 락/탑 변경)'}">${source === 'golftop' ? '탑' : '락'}</span>
                        <span class="card-time ${isSeonti ? 'is-seonti' : ''}" title="${isSeonti ? '선티 (확정금액)' : ''}">${time}</span>
                    </div>
                </div>
                <div class="card-row-bottom">
                    <span class="card-fee">💵 ${fee || '0'}만${hasSlashFee && slashBackVal ? ` <span style="font-size:9.5px; color:#047857; font-weight:700;">(${tr.dataset.slashFrontVal || noticePrice}만 / ${slashBackVal}만)</span>` : ''}</span>
                    <label class="card-seonti-pill ${isSeonti ? 'active' : ''}" data-index="${idx}" title="${isSeonti ? '선티방으로 지정됨 (체크 해제 시 일반 타임 복구)' : '체크 시 선티방으로 강제 인식 (공지/특정구장 할인 제외)'}">
                        <input type="checkbox" class="chk-seonti" ${isSeonti ? 'checked' : ''}>
                        <span>${isSeonti ? '선티방' : '선티'}</span>
                    </label>
                    ${noticeTagHtml}
                    ${courseAdjTagHtml}
                    ${priceDropTagHtml}
                    ${cady ? `<span class="card-tag">🏌️ ${cady}</span>` : ''}
                    ${isMeal ? `<span class="card-tag meal" title="식사포함">🍚 식사포함</span>` : ''}
                    ${condition ? `<span class="card-tag">⛳ ${condition}</span>` : ''}
                    ${roomType && roomType !== '미표시' && !roomType.includes('선티') ? `<span class="card-tag room">${roomType}</span>` : ''}
                    ${sizenum ? `<span class="card-tag pax">👥 ${sizenum}</span>` : ''}
                </div>
            </div>
            <button class="card-del-btn" title="삭제">&times;</button>
        `;

        function applySelection(targetState) {
            card.classList.toggle('selected', targetState);
            const chk = card.querySelector('input[type="checkbox"]');
            if (chk) chk.checked = targetState;
            tr.classList.toggle('selected', targetState);
        }

        // 드래그 시작 (mousedown: 클릭 즉시 토글 및 드래그 모드 활성화)
        card.addEventListener('mousedown', (e) => {
            if (e.target.classList.contains('card-del-btn') || e.target.closest('.notice-tag') || e.target.closest('.card-seonti-pill') || e.target.closest('.card-tag.meal') || e.target.closest('.card-source-badge')) return;
            e.preventDefault();

            isCardDragging = true;
            dragTargetState = !card.classList.contains('selected');
            lastHoveredIndex = idx;

            applySelection(dragTargetState);
            updateSelectedBadge();
        });

        // 드래그 중 다른 카드 위로 마우스 진입 (mouseenter)
        card.addEventListener('mouseenter', () => {
            if (isCardDragging) {
                lastHoveredIndex = idx;
                applySelection(dragTargetState);
                updateSelectedBadge();
            }
        });

        // 카드 클릭 핸들러 (출처 토글, 삭제 버튼 및 공지 태그 전문 보기, 식사포함 토글)
        card.addEventListener('click', (e) => {
            const sourceBadge = e.target.closest('.card-source-badge');
            if (sourceBadge) {
                e.stopPropagation();
                e.preventDefault();
                const cur = tr.dataset.source || 'golfrock';
                const nextSource = (cur === 'golftop') ? 'golfrock' : 'golftop';
                tr.dataset.source = nextSource;
                renderCardList();
                saveCurrentTableState();
                showToast(`출처가 [${nextSource === 'golftop' ? '골프탑(탑)' : '골프락(락)'}]으로 변경되었습니다.`);
                return;
            }
            const mealTag = e.target.closest('.card-tag.meal');
            if (mealTag) {
                e.stopPropagation();
                const cur = tr.dataset.isMeal === 'true';
                tr.dataset.isMeal = (!cur).toString();
                renderCardList();
                saveCurrentTableState();
                showToast(!cur ? '🍚 식사포함으로 지정되었습니다.' : '⚪ 식사포함이 해제되었습니다.');
                return;
            }
            const noticeTag = e.target.closest('.notice-tag');
            if (noticeTag) {
                e.stopPropagation();
                const c = noticeTag.dataset.course || golf;
                showNoticeDetailModal(c);
                return;
            }
            if (e.target.classList.contains('card-del-btn')) {
                tr.remove();
                card.remove();
                updateSelectedBadge();
                saveCurrentTableState();
                if (document.querySelectorAll('#dataTable tbody tr').length === 0) renderCardList();
            }
        });

        // 선티 수동 체크박스 변경 이벤트 연결
        const seontiPill = card.querySelector('.card-seonti-pill');
        const chkSeonti = card.querySelector('.chk-seonti');
        if (seontiPill && chkSeonti) {
            seontiPill.addEventListener('mousedown', (e) => {
                e.stopPropagation();
            });
            chkSeonti.addEventListener('change', (e) => {
                e.stopPropagation();
                toggleSeontiStatus(tr, chkSeonti.checked);
            });
        }

        cardContainer.appendChild(card);
    });

    // 고속 드래그 시 마우스 아래 카드를 실시간 감지하여 일괄 체크/해제
    cardContainer.onmousemove = (e) => {
        if (!isCardDragging) return;
        const hoveredCard = document.elementFromPoint(e.clientX, e.clientY)?.closest('.tee-card');
        if (hoveredCard) {
            const hIdx = parseInt(hoveredCard.dataset.index, 10);
            if (!isNaN(hIdx) && hIdx !== lastHoveredIndex) {
                lastHoveredIndex = hIdx;
                const targetTr = trs[hIdx];
                if (targetTr) {
                    hoveredCard.classList.toggle('selected', dragTargetState);
                    const chk = hoveredCard.querySelector('input[type="checkbox"]');
                    if (chk) chk.checked = dragTargetState;
                    targetTr.classList.toggle('selected', dragTargetState);
                    updateSelectedBadge();
                }
            }
        }
    };

    updateSelectedBadge();
}

// 창 어디서든 마우스를 떼면 드래그 종료 및 상태 저장
window.addEventListener('mouseup', () => {
    if (isCardDragging) {
        isCardDragging = false;
        lastHoveredIndex = null;
        updateSelectedBadge();
        saveCurrentTableState();
    }
});

// 특정 타임 선티방 강제 지정 / 해제 함수 (개별 토글)
function toggleSeontiStatus(tr, targetState) {
    if (!tr) return;
    const golfName = tr.cells[2]?.textContent.trim() || '';
    const timeStr = tr.cells[3]?.textContent.trim() || '';

    if (targetState) {
        if (!tr.dataset.origRoomType) {
            tr.dataset.origRoomType = tr.dataset.roomType || '미표시';
        }
        tr.dataset.isSeontiOrDaegi = 'true';
        tr.dataset.roomType = '선티방';
        tr.dataset.manualSeonti = 'true';
        showToast(`🔥 [${golfName} ${timeStr}] 선티방으로 지정되었습니다. (확정금액 적용)`);
    } else {
        tr.dataset.isSeontiOrDaegi = 'false';
        tr.dataset.roomType = tr.dataset.origRoomType || '미표시';
        delete tr.dataset.manualSeonti;
        showToast(`↩️ [${golfName} ${timeStr}] 일반 타임으로 복구되었습니다.`);
    }

    applyAllActiveNoticeRules();
    updateSelectedBadge();
}

// 선택(체크)된 타임들 일괄 선티방 지정 / 해제 함수 (일괄 토글)
function handleBatchToggleSeonti() {
    const selectedTrs = Array.from(document.querySelectorAll('#dataTable tbody tr.selected'));
    if (selectedTrs.length === 0) {
        showToast('선티로 지정할 타임을 목록에서 먼저 선택(체크)해주세요.');
        return;
    }

    // 선택된 항목 중 하나라도 선티가 아니면 -> 모두 선티로 지정
    // 모두 이미 선티라면 -> 모두 일반 타임으로 복구
    const hasNonSeonti = selectedTrs.some(tr => (
        tr.dataset.isSeontiOrDaegi !== 'true' &&
        !(tr.dataset.roomType || '').includes('선티')
    ));

    const targetState = hasNonSeonti;

    selectedTrs.forEach(tr => {
        if (targetState) {
            if (!tr.dataset.origRoomType) {
                tr.dataset.origRoomType = tr.dataset.roomType || '미표시';
            }
            tr.dataset.isSeontiOrDaegi = 'true';
            tr.dataset.roomType = '선티방';
            tr.dataset.manualSeonti = 'true';
        } else {
            tr.dataset.isSeontiOrDaegi = 'false';
            tr.dataset.roomType = tr.dataset.origRoomType || '미표시';
            delete tr.dataset.manualSeonti;
        }
    });

    applyAllActiveNoticeRules();
    updateSelectedBadge();

    if (targetState) {
        showToast(`🔥 선택된 ${selectedTrs.length}건이 선티방으로 지정되었습니다. (가격변경 제외)`);
    } else {
        showToast(`↩️ 선택된 ${selectedTrs.length}건이 일반 타임으로 복구되었습니다.`);
    }
}

// 테이블 행에서 그린피 금액 추출 헬퍼 (숫자 파싱)
function getTrFee(tr) {
    if (!tr) return 9999;
    const text = tr.cells[4]?.textContent.trim() || '';
    const match = text.match(/(\d+(?:\.\d+)?)/);
    if (match) {
        const val = parseFloat(match[1]);
        if (!isNaN(val)) return val;
    }
    if (tr.dataset.baseFee) {
        const val = parseFloat(tr.dataset.baseFee);
        if (!isNaN(val)) return val;
    }
    return 9999;
}

// 테이블 행에서 시간(분 단위 정수) 추출 헬퍼 (HH:MM 또는 0746 등 4자리/3자리 숫자 형식 모두 지원)
function getTrMinutes(tr) {
    if (!tr) return 0;
    const timeStr = tr.cells[3]?.textContent.trim() || '';
    return timeToMinutes(timeStr);
}

// 행이 조인 인원이 이미 존재하는 타임인지 판별 (대기방, 선티방, 또는 1~3인 대기)
function hasJoinedPax(tr) {
    if (!tr) return false;
    const roomType = tr.dataset.roomType || '';
    if (roomType === '대기방' || roomType === '선티방') return true;
    if (tr.dataset.isSeontiOrDaegi === 'true') return true;
    const size = tr.cells[7]?.textContent.trim() || '';
    if (/^[123]인$/.test(size)) return true;
    return false;
}

// 행이 속한 부제 판별 (1부: < 11:00, 2부: 11:00 ~ 15:59, 3부: >= 16:00)
function getTrPart(tr) {
    const mins = getTrMinutes(tr);
    if (mins < 660) return 1;
    if (mins < 960) return 2;
    return 3;
}

// 특정 부제 목록에서 최적의 1개 타임 선정
// 규칙:
// 1. 인원이 있는 타임(대기/선티/1~3인)이 있으면 해당 타임들 중에서 우선 선택
// 2. 기준 시간:
//    - 1부: 8시(480분)에 가장 가까운 타임
//    - 2부: 11시(660분)에 가장 가까운 타임
//    - 3부: 가장 빠른 타임(최소 분)
// 3. 20분 차이 내에 더 저렴한 타임이 있으면 저렴한 타임 우선 선택
function pickBestOneFromPart(pool, partNumber) {
    if (!pool || pool.length === 0) return null;
    if (pool.length === 1) return pool[0];

    // 1. 인원 있는 타임 우선 풀 (대기방, 선티방, 1~3인 조인 대기)
    const paxPool = pool.filter(tr => hasJoinedPax(tr));
    const activePool = (paxPool.length > 0) ? paxPool : pool;
    if (activePool.length === 1) return activePool[0];

    // 2. 부제별 기준 시간(targetMins) 계산
    let targetMins = 480; // 기본 8시
    if (partNumber === 1) {
        targetMins = 480; // 1부: 8시(08:00)
    } else if (partNumber === 2) {
        targetMins = 660; // 2부: 11시(11:00)
    } else if (partNumber === 3) {
        // 3부: 가장 빠른 타임
        targetMins = Math.min(...activePool.map(tr => getTrMinutes(tr)));
    }

    // 기준 시간에 가장 가까운 앵커 타임 선정 (거리 동일 시 그린피 저렴한 순, 이른 시간 순)
    const sortedByTarget = activePool.slice().sort((a, b) => {
        const distA = Math.abs(getTrMinutes(a) - targetMins);
        const distB = Math.abs(getTrMinutes(b) - targetMins);
        if (distA !== distB) return distA - distB;

        const feeA = getTrFee(a);
        const feeB = getTrFee(b);
        if (feeA !== feeB) return feeA - feeB;

        return getTrMinutes(a) - getTrMinutes(b);
    });
    const anchorTr = sortedByTarget[0];
    const anchorMins = getTrMinutes(anchorTr);
    const anchorFee = getTrFee(anchorTr);

    // 3. 20분 차이 내(앵커 타임 기준 +-20분 또는 targetMins 기준 +-20분) 후보군 선별
    const nearbyCandidates = activePool.filter(tr => {
        const mins = getTrMinutes(tr);
        return Math.abs(mins - anchorMins) <= 20 || Math.abs(mins - targetMins) <= 20;
    });

    // 20분 차이 내에 더 저렴한 타임이 있는지 확인
    const cheaperCandidates = nearbyCandidates.filter(tr => getTrFee(tr) < anchorFee);
    if (cheaperCandidates.length > 0) {
        // 더 저렴한 타임 중 가장 저렴한 타임 선택 (금액 동일 시 targetMins에 가장 가까운 순)
        cheaperCandidates.sort((a, b) => {
            const feeA = getTrFee(a);
            const feeB = getTrFee(b);
            if (feeA !== feeB) return feeA - feeB;

            const distA = Math.abs(getTrMinutes(a) - targetMins);
            const distB = Math.abs(getTrMinutes(b) - targetMins);
            if (distA !== distB) return distA - distB;

            return getTrMinutes(a) - getTrMinutes(b);
        });
        return cheaperCandidates[0];
    }

    // 더 저렴한 타임이 없으면 anchorTr 선택
    return anchorTr;
}

// 동일 부제 내에서 2개 타임을 선별할 때 (최소 15분 간격 유지 우선)
function pickTwoFromSamePart(partList, partNumber) {
    if (!partList || partList.length === 0) return [];
    if (partList.length <= 2) return partList;

    const first = pickBestOneFromPart(partList, partNumber);
    if (!first) return [];

    const remaining = partList.filter(tr => tr !== first);
    if (remaining.length === 0) return [first];

    const firstMins = getTrMinutes(first);
    const MIN_TIME_GAP = 15;

    // 15분 이상 떨어진 후보군 우선
    const spacedCandidates = remaining.filter(tr => Math.abs(getTrMinutes(tr) - firstMins) >= MIN_TIME_GAP);
    const secondPool = (spacedCandidates.length > 0) ? spacedCandidates : remaining;

    const second = pickBestOneFromPart(secondPool, partNumber);
    return second ? [first, second] : [first];
}

// 구장별 최적의 2개 타임 선별
// [사용자 지정 우선순위]
// 1순위: 1부에서 1개 + 2부에서 1개
// 2순위: 1부에서 1개 + 3부에서 1개
// 3순위: 2부에서 1개 + 3부에서 1개
// 4순위: 단일 부제만 존재하는 경우 해당 부제에서 2개 선택 (15분 이상 간격 확보)
function pickBestTwoTrs(list) {
    if (!list || list.length === 0) return [];
    if (list.length <= 2) return list;

    // 1부, 2부, 3부로 분리 (1부: < 11:00, 2부: 11:00~15:59, 3부: >= 16:00)
    const part1 = list.filter(tr => getTrPart(tr) === 1);
    const part2 = list.filter(tr => getTrPart(tr) === 2);
    const part3 = list.filter(tr => getTrPart(tr) === 3);

    // 1순위: 1부에서 1개 + 2부에서 1개
    if (part1.length > 0 && part2.length > 0) {
        const p1 = pickBestOneFromPart(part1, 1);
        const p2 = pickBestOneFromPart(part2, 2);
        if (p1 && p2) return [p1, p2];
    }

    // 2순위: 1부에서 1개 + 3부에서 1개
    if (part1.length > 0 && part3.length > 0) {
        const p1 = pickBestOneFromPart(part1, 1);
        const p3 = pickBestOneFromPart(part3, 3);
        if (p1 && p3) return [p1, p3];
    }

    // 3순위: 2부에서 1개 + 3부에서 1개
    if (part2.length > 0 && part3.length > 0) {
        const p2 = pickBestOneFromPart(part2, 2);
        const p3 = pickBestOneFromPart(part3, 3);
        if (p2 && p3) return [p2, p3];
    }

    // 4순위: 단일 부제만 존재하는 경우 해당 부제에서 2개 선택
    if (part1.length >= 2) return pickTwoFromSamePart(part1, 1);
    if (part2.length >= 2) return pickTwoFromSamePart(part2, 2);
    if (part3.length >= 2) return pickTwoFromSamePart(part3, 3);

    // 전체 중 남은 것에서 최대 2개 반환
    return list.slice(0, 2);
}

// 자동 2개 선택 (부제 조합 우선순위 1+2 > 1+3 > 2+3, 1부 8시/2부 11시/3부 빠른타임, 조인인원 우선, 20분 내 최저가 우선, 미등록 구장 제외)
function autoSelectTwo() {
    const trs = Array.from(document.querySelectorAll('#dataTable tbody tr'));
    trs.forEach(tr => tr.classList.remove('selected'));

    const groups = {};
    trs.forEach(tr => {
        // 매핑사전에 등록되지 않은 구장은 자동 선택에서 제외!
        if (tr.dataset.isMapped === 'false') return;

        const date = tr.cells[0]?.textContent || '';
        const golf = tr.cells[2]?.textContent || '';
        const key = `${date}_${golf}`;
        if (!groups[key]) groups[key] = [];
        groups[key].push(tr);
    });

    let count = 0;
    for (const key in groups) {
        const list = groups[key];
        const picked = pickBestTwoTrs(list);

        picked.forEach(tr => {
            tr.classList.add('selected');
            count++;
        });
    }

    syncCardsSelection();
    updateSelectedBadge();
    saveCurrentTableState();
    if (count > 0) {
        showToast(`구장별 최대 2개씩 총 ${count}건 자동 선택됨`);
    }
}

function syncCardsSelection() {
    const trs = Array.from(document.querySelectorAll('#dataTable tbody tr'));
    const cards = Array.from(document.querySelectorAll('#cardList .tee-card'));
    trs.forEach((tr, idx) => {
        const isSel = tr.classList.contains('selected');
        if (cards[idx]) {
            cards[idx].classList.toggle('selected', isSel);
            const chk = cards[idx].querySelector('input[type="checkbox"]');
            if (chk) chk.checked = isSel;
        }
    });
}

// ========================================================
// New GolfTee82: 등록 이력 관리 & 가격 변동 추적
// ========================================================
let registeredHistory = {};

function makeHistoryKey(dateStr, golfStr, timeStr) {
    const cleanDate = (dateStr || '').replace(/[^\d]/g, '');
    const cleanGolf = (golfStr || '').replace(/\s+/g, '').replace(/cc|gc|골프장|골프클럽/gi, '').trim().toLowerCase();
    const cleanTime = (timeStr || '').replace(/[^\d]/g, '');
    return `${cleanDate}_${cleanGolf}_${cleanTime}`;
}

function loadRegisteredHistory() {
    try {
        const local = localStorage.getItem('v2_registeredHistory');
        if (local) registeredHistory = JSON.parse(local);
    } catch(e) {}
    try {
        if (typeof chrome !== 'undefined' && chrome.storage && chrome.storage.local) {
            chrome.storage.local.get(['v2_registeredHistory'], (res) => {
                if (res && res.v2_registeredHistory && typeof res.v2_registeredHistory === 'object') {
                    registeredHistory = Object.assign({}, res.v2_registeredHistory, registeredHistory);
                }
            });
        }
    } catch(e) {}
}

function saveRegisteredHistory() {
    try {
        localStorage.setItem('v2_registeredHistory', JSON.stringify(registeredHistory));
    } catch(e) {}
    try {
        if (typeof chrome !== 'undefined' && chrome.storage && chrome.storage.local) {
            chrome.storage.local.set({ v2_registeredHistory: registeredHistory });
        }
    } catch(e) {}
}

function recordRegisteredItem(item) {
    if (!item) return;
    const feeNum = parseFloat((item.fee || '').toString().replace(/[^\d.]/g, '')) || 0;
    const entry = {
        date: item.date,
        golf: item.golf,
        rawGolf: item.rawGolf || item.golf,
        time: item.time,
        fee: feeNum,
        updatedAt: Date.now()
    };
    const k1 = makeHistoryKey(item.date, item.golf, item.time);
    const k2 = makeHistoryKey(item.date, item.rawGolf, item.time);
    if (k1) registeredHistory[k1] = entry;
    if (k2) registeredHistory[k2] = entry;
    saveRegisteredHistory();
}

function updateSelectedBadge() {
    const trs = Array.from(document.querySelectorAll('#dataTable tbody tr'));
    const selectedTrs = trs.filter(tr => tr.classList.contains('selected'));
    const totalCount = trs.length;
    const selCount = selectedTrs.length;

    // 히어로 상태 업데이트
    const heroSelected = document.getElementById('heroSelectedCount');
    const heroTotal = document.getElementById('heroTotalCountText');
    const tabCount = document.getElementById('tabCount');
    const chkSelectAll = document.getElementById('chkSelectAll');
    const textCheckAll = document.getElementById('textCheckAll');

    if (heroSelected) heroSelected.textContent = selCount;
    if (tabCount) tabCount.textContent = totalCount;
    if (heroTotal) {
        if (totalCount === 0) {
            heroTotal.textContent = '텍스트를 붙여넣고 매크로를 실행하세요';
        } else {
            heroTotal.textContent = `총 ${totalCount}개 중 ${selCount}개 선택됨`;
        }
    }

    // 전체 선택 체크박스 상태
    if (chkSelectAll) {
        chkSelectAll.checked = (totalCount > 0 && selCount === totalCount);
        chkSelectAll.indeterminate = (selCount > 0 && selCount < totalCount);
    }
    if (textCheckAll) {
        textCheckAll.textContent = (selCount === totalCount && totalCount > 0) ? '전체해제' : '전체선택';
    }

    // 인하건 개수 및 가격수정 버튼 카운트 업데이트
    const priceDroppedTrs = trs.filter(tr => tr.dataset.isPriceDropped === 'true');
    const priceDropCount = priceDroppedTrs.length;
    const selPriceDropCount = selectedTrs.filter(tr => tr.dataset.isPriceDropped === 'true').length;

    const badgePriceDropCount = document.getElementById('badgePriceDropCount');
    if (badgePriceDropCount) {
        badgePriceDropCount.textContent = priceDropCount;
    }

    const priceEditCount = document.getElementById('priceEditCount');
    if (priceEditCount) {
        // 선택된 항목이 있으면 선택된 건수(selCount)를 우선 표시, 없으면 인하건수(priceDropCount) 표시
        priceEditCount.textContent = selCount > 0 ? selCount : priceDropCount;
    }
}

// 전체 선택 / 전체 해제 토글 핸들러
function handleToggleSelectAll() {
    const trs = Array.from(document.querySelectorAll('#dataTable tbody tr'));
    if (trs.length === 0) return;
    const allSelected = trs.every(tr => tr.classList.contains('selected'));
    const targetState = !allSelected;

    trs.forEach(tr => tr.classList.toggle('selected', targetState));
    syncCardsSelection();
    updateSelectedBadge();
    saveCurrentTableState();
    showToast(targetState ? `총 ${trs.length}건 전체 선택됨` : '전체 선택 해제됨');
}

// 가격 인하건만 필터/선택 핸들러
function handleSelectPriceDropped() {
    const trs = Array.from(document.querySelectorAll('#dataTable tbody tr'));
    if (trs.length === 0) {
        showToast('변환된 티타임이 없습니다.');
        return;
    }

    const priceDroppedTrs = trs.filter(tr => tr.dataset.isPriceDropped === 'true');
    if (priceDroppedTrs.length === 0) {
        showToast('현재 인하(할인)된 티타임이 없습니다.');
        return;
    }

    const isAllDropSelected = priceDroppedTrs.every(tr => tr.classList.contains('selected'));
    const targetState = !isAllDropSelected;

    trs.forEach(tr => {
        if (tr.dataset.isPriceDropped === 'true') {
            tr.classList.toggle('selected', targetState);
        } else {
            tr.classList.remove('selected');
        }
    });

    syncCardsSelection();
    updateSelectedBadge();
    saveCurrentTableState();

    if (targetState) {
        showToast(`📉 가격 인하 타임 ${priceDroppedTrs.length}건이 선택되었습니다!`);
    } else {
        showToast('인하건 선택이 해제되었습니다.');
    }
}

// 골프몬 내글 가격수정 실행 중복 클릭 방지 플래그
let isGolfmonPriceUpdating = false;

// 골프몬 내글 가격수정 실행 핸들러
function startGolfmonPriceUpdate() {
    if (isGolfmonPriceUpdating) {
        console.warn("[Tee82] 이미 가격수정 명령이 전달 중입니다. 중복 클릭 무시.");
        return;
    }
    isGolfmonPriceUpdating = true;
    setTimeout(() => { isGolfmonPriceUpdating = false; }, 3000);

    let targetTrs = Array.from(document.querySelectorAll('#dataTable tbody tr.selected'));
    if (targetTrs.length === 0) {
        const dropTrs = Array.from(document.querySelectorAll('#dataTable tbody tr')).filter(tr => tr.dataset.isPriceDropped === 'true');
        if (dropTrs.length > 0) {
            targetTrs = dropTrs;
            dropTrs.forEach(tr => tr.classList.add('selected'));
            syncCardsSelection();
            updateSelectedBadge();
        }
    }

    if (targetTrs.length === 0) {
        alert("가격 수정할 티타임이 선택되지 않았습니다.\n수정할 타임을 목록에서 체크하거나 [인하건 선택]을 눌러주세요.");
        return;
    }

    targetTrs.forEach((tr, idx) => {
        tr.dataset.regId = `edit_gm_${Date.now()}_${idx}`;
    });

    const items = targetTrs.map(tr => {
        const cells = tr.querySelectorAll('td');
        const origGolf = cells[2]?.textContent.trim() || '';
        const rawGolf = tr.dataset.rawGolf || origGolf;
        const golfmonGolf = tr.dataset.golfmonGolf || getMappedName(rawGolf, 'golfmon').name || origGolf;

        const roomTypeRaw = (tr.dataset.roomType || '').trim();
        const sizenumRaw = (cells[7]?.textContent || '').trim();
        const conditionRaw = (cells[6]?.textContent || '').trim();

        // 골프몬 등록글 양도/조인 구별 판별
        let resolvedRoomType = '양도';
        if (roomTypeRaw === '양도') {
            resolvedRoomType = '양도';
        } else if (roomTypeRaw === '선티방' || roomTypeRaw === '대기방' || roomTypeRaw.includes('선티') || roomTypeRaw.includes('대기')) {
            resolvedRoomType = '조인';
        } else if (sizenumRaw && /^[123]인$/.test(sizenumRaw)) {
            resolvedRoomType = '조인';
        } else if (conditionRaw && conditionRaw !== '무관') {
            resolvedRoomType = '조인';
        } else if (typeof lastUsedMacroType !== 'undefined' && lastUsedMacroType === 'transfer') {
            resolvedRoomType = '양도';
        } else if (typeof lastUsedMacroType !== 'undefined' && lastUsedMacroType === 'join') {
            resolvedRoomType = '조인';
        } else if (sizenumRaw === '4인' || !sizenumRaw) {
            resolvedRoomType = '양도';
        } else {
            resolvedRoomType = '조인';
        }

        return {
            regId: tr.dataset.regId,
            date: cells[0]?.textContent.trim() || '',
            region: cells[1]?.textContent.trim() || '',
            golf: golfmonGolf,
            rawGolf: rawGolf,
            time: cells[3]?.textContent.trim() || '',
            fee: cells[4]?.textContent.trim() || '',
            cady: cells[5]?.textContent.trim() || '',
            condition: conditionRaw,
            sizenum: sizenumRaw,
            roomType: resolvedRoomType,
            origRoomType: roomTypeRaw,
            isPriceDropped: tr.dataset.isPriceDropped === 'true',
            prevFee: tr.dataset.prevFee || ''
        };
    });

    const delayPreset = document.getElementById('selRandomDelay')?.value || 'safe';
    const stepPreset = document.getElementById('selStepDelay')?.value || 'human';

    // 양도용 원클릭 vs 조인용 원클릭 모드 또는 항목 구성에 따른 구분 필터('양도' or '조인')
    const transferCount = items.filter(it => it.roomType === '양도').length;
    const joinCount = items.filter(it => it.roomType === '조인').length;
    let filterType = '조인';
    if (typeof lastUsedMacroType !== 'undefined' && lastUsedMacroType === 'transfer') {
        filterType = '양도';
    } else if (typeof lastUsedMacroType !== 'undefined' && lastUsedMacroType === 'join') {
        filterType = '조인';
    } else if (transferCount > joinCount) {
        filterType = '양도';
    } else {
        filterType = '조인';
    }

    chrome.tabs.query({ url: ["*://golfmon.net/*", "https://golfmon.net/*", "http://golfmon.net/*", "*://*.golfmon.net/*", "https://*.golfmon.net/*", "http://*.golfmon.net/*"] }, (tabs) => {
        if (tabs && tabs.length > 0) {
            const golfmonTab = tabs[0];
            chrome.tabs.update(golfmonTab.id, { active: true }, () => {
                const sendMsg = () => {
                    chrome.tabs.sendMessage(golfmonTab.id, {
                        action: 'START_GOLFMON_PRICE_UPDATE',
                        items: items,
                        filterType: filterType,
                        delayPreset: delayPreset,
                        stepPreset: stepPreset
                    }, (response) => {
                        if (chrome.runtime.lastError) {
                            console.warn("[Tee82] 골프몬 통신 재시도 및 스크립트 자동 재주입:", chrome.runtime.lastError.message);
                            if (chrome.scripting && chrome.scripting.executeScript) {
                                chrome.scripting.executeScript({
                                    target: { tabId: golfmonTab.id },
                                    files: ['content_script.js']
                                }, () => {
                                    if (chrome.runtime.lastError) {
                                        if (confirm("골프몬 탭과의 연결이 끊겼습니다.\n골프몬 사이트를 자동으로 새로고침(F5)하시겠습니까?")) {
                                            chrome.tabs.reload(golfmonTab.id);
                                        }
                                        return;
                                    }
                                    setTimeout(() => {
                                        chrome.tabs.sendMessage(golfmonTab.id, {
                                            action: 'START_GOLFMON_PRICE_UPDATE',
                                            items: items,
                                            filterType: filterType,
                                            delayPreset: delayPreset,
                                            stepPreset: stepPreset
                                        }, (res2) => {
                                            if (chrome.runtime.lastError) {
                                                if (confirm("골프몬 탭과의 연결에 실패했습니다.\n골프몬 사이트를 자동으로 새로고침(F5)하시겠습니까?")) {
                                                    chrome.tabs.reload(golfmonTab.id);
                                                }
                                            } else {
                                                document.getElementById('btnHeaderStop')?.classList.add('active');
                                                showProgressModal(items.length, 'price_update');
                                                if (items[0]) {
                                                    updateProgress(1, items.length, items[0].golf, items[0].date, items[0].time, items[0].fee);
                                                }
                                            }
                                        });
                                    }, 200);
                                });
                            } else {
                                if (confirm("골프몬 탭과의 연결에 실패했습니다.\n골프몬 사이트를 자동으로 새로고침(F5)하시겠습니까?")) {
                                    chrome.tabs.reload(golfmonTab.id);
                                }
                            }
                        } else {
                            document.getElementById('btnHeaderStop')?.classList.add('active');
                            showProgressModal(items.length, 'price_update');
                            if (items[0]) {
                                updateProgress(1, items.length, items[0].golf, items[0].date, items[0].time, items[0].fee);
                            }
                        }
                    });
                };
                sendMsg();
            });
        } else {
            if (confirm("열려 있는 골프몬(golfmon.net) 탭이 없습니다.\n골프몬 사이트를 새 탭으로 여시겠습니까?")) {
                chrome.tabs.create({ url: "https://golfmon.net/" });
            }
        }
    });
}

let lastUsedMacroType = 'join';
let unmappedModalCallback = null;

function showUnmappedCourseModal(unmappedCourses, callback) {
    const modal = document.getElementById('unmappedCourseModal');
    const container = document.getElementById('unmappedListContainer');
    if (!modal || !container) {
        callback(false);
        return;
    }

    unmappedModalCallback = callback;
    container.innerHTML = '';

    const validUnmapped = (unmappedCourses || []).filter(rawName => rawName && !isJunkDictKey(rawName));
    if (validUnmapped.length === 0) {
        callback(false);
        return;
    }

    validUnmapped.forEach(rawName => {
        const suggestedReg = getRegion('', rawName);
        const mapObj = getMappedName(rawName);
        const defGolfmon = mapObj.golfmon || rawName;
        const defGolfpang = mapObj.golfpang || rawName;
        const defGolmarket = mapObj.golmarket || getGolmarketGolfName(rawName) || rawName;
        const defGolfrock = mapObj.golfrock || rawName;

        const itemRow = document.createElement('div');
        itemRow.className = 'unmapped-item-row';
        itemRow.dataset.raw = rawName;

        itemRow.innerHTML = `
            <div class="unmapped-item-top">
                <span class="unmapped-item-badge">미등록</span>
                <span class="unmapped-item-raw">${rawName}</span>
            </div>
            <div class="unmapped-item-fields" style="display: flex; flex-direction: column; gap: 6px;">
                <div style="display: flex; gap: 6px;">
                    <div class="unmapped-field" style="width: 120px;">
                        <label>지역</label>
                        <input type="text" class="unmapped-reg-input" list="regionSuggestions" placeholder="예: 경기북부" value="${suggestedReg}">
                    </div>
                </div>
                <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 5px;">
                    <div class="unmapped-field">
                        <label>🚀 골프몬</label>
                        <input type="text" class="unmapped-gm-input" placeholder="골프몬 구장명" value="${defGolfmon}">
                    </div>
                    <div class="unmapped-field">
                        <label>⛳ 골팡</label>
                        <input type="text" class="unmapped-gp-input" placeholder="골팡 구장명" value="${defGolfpang}">
                    </div>
                    <div class="unmapped-field">
                        <label>🛒 골마켓</label>
                        <input type="text" class="unmapped-gmk-input" placeholder="골마켓 구장명" value="${defGolmarket}">
                    </div>
                    <div class="unmapped-field">
                        <label>🪨 골프락</label>
                        <input type="text" class="unmapped-grk-input" placeholder="골프락 구장명" value="${defGolfrock}">
                    </div>
                </div>
            </div>
        `;
        container.appendChild(itemRow);
    });

    modal.style.display = 'flex';
}

function closeUnmappedModal(registered) {
    const modal = document.getElementById('unmappedCourseModal');
    if (modal) modal.style.display = 'none';
    if (typeof unmappedModalCallback === 'function') {
        const cb = unmappedModalCallback;
        unmappedModalCallback = null;
        cb(registered);
    }
}

// 원클릭 매크로 (미등록 구장 자동 감지 및 등록 창 연동)
function runMacro(type) {
    lastUsedMacroType = type;

    const parsed = parseInputData(type);

    if (parsed.rowDataList.length === 0) {
        showToast('변환할 수 있는 유효한 티타임 데이터가 없습니다.');
        applyParsedData(parsed, type);
        return;
    }

    if (parsed.unmappedCourses.length > 0) {
        // 미등록 구장 발견 -> 자동으로 등록 모달 표시
        showUnmappedCourseModal(parsed.unmappedCourses, (didRegister) => {
            if (didRegister) {
                // 사전에 등록했으므로 갱신된 사전으로 재파싱 & 2개 자동 선택
                const reParsed = parseInputData(type);
                applyParsedData(reParsed, type);
                autoSelectTwo();
            } else {
                // 등록 안 함 -> 변환은 하되, 미등록 구장은 자동 선택에서 제외
                applyParsedData(parsed, type);
                autoSelectTwo();
                showToast(`총 ${parsed.rowDataList.length}건 변환 완료 (미등록 구장 ${parsed.unmappedCourses.length}개는 선택 제외됨)`);
            }
        });
    } else {
        // 미등록 구장 없음 -> 바로 변환 및 2개 자동 선택
        applyParsedData(parsed, type);
        autoSelectTwo();
    }
}

// 텍스트 복사
function copySelected() {
    const selectedTrs = Array.from(document.querySelectorAll('#dataTable tbody tr.selected'));
    if (selectedTrs.length === 0) {
        alert("선택된 항목이 없습니다.");
        return;
    }
    const lines = selectedTrs.map(tr => Array.from(tr.cells).map(td => td.textContent).join('\t'));
    navigator.clipboard.writeText(lines.join('\n')).then(() => {
        showToast(`선택된 ${selectedTrs.length}건이 클립보드에 복사되었습니다.`);
    });
}

// 등록 완료된 단일 항목 체크 해제
function uncheckItem(regId, itemInfo = null) {
    let tr = null;
    if (regId) {
        tr = document.querySelector(`#dataTable tbody tr[data-reg-id="${regId}"]`);
    }
    if (!tr && itemInfo) {
        const trs = Array.from(document.querySelectorAll('#dataTable tbody tr.selected'));
        tr = trs.find(r => {
            const cells = r.querySelectorAll('td');
            return cells[0]?.textContent.trim() === itemInfo.date &&
                   cells[2]?.textContent.trim() === itemInfo.golf &&
                   cells[3]?.textContent.trim() === itemInfo.time;
        });
    }
    if (tr && tr.classList.contains('selected')) {
        tr.classList.remove('selected');
        syncCardsSelection();
        updateSelectedBadge();
        saveCurrentTableState();
    }
}

// 스토리지에 기록된 등록 완료 항목 전체 체크 해제
function checkAndUncheckCompletedFromStorage() {
    try {
        chrome.storage.local.get(['completedItems'], (res) => {
            if (res && res.completedItems && Array.isArray(res.completedItems)) {
                res.completedItems.forEach(item => {
                    uncheckItem(item.regId, item);
                });
            }
        });
    } catch(e) {}
}

// 자동등록 중단 공통 처리 함수 (헤더 🛑 버튼 및 모달 중단 버튼에서 호출)
function stopRegistration() {
    chrome.tabs.query({ url: ["*://golfmon.net/*", "https://golfmon.net/*", "http://golfmon.net/*", "*://*.golfmon.net/*", "https://*.golfmon.net/*", "http://*.golfmon.net/*"] }, (tabs) => {
        if (tabs && tabs[0]) {
            chrome.tabs.sendMessage(tabs[0].id, { action: 'STOP_REGISTRATION' });
        }
    });

    chrome.tabs.query({ url: ["*://*.golmarket.co.kr/*", "https://golmarket.co.kr/*", "http://golmarket.co.kr/*"] }, (tabs) => {
        if (tabs) {
            tabs.forEach(tab => chrome.tabs.sendMessage(tab.id, { action: 'STOP_REGISTRATION' }));
        }
    });

    chrome.tabs.query({ url: ["*://*.golfrock.co.kr/*", "https://golfrock.co.kr/*", "http://golfrock.co.kr/*"] }, (tabs) => {
        if (tabs) {
            tabs.forEach(tab => chrome.tabs.sendMessage(tab.id, { action: 'STOP_REGISTRATION' }));
        }
    });

    const overlay = document.getElementById('progressOverlay');
    if (overlay) overlay.style.display = 'none';

    document.getElementById('btnHeaderStop')?.classList.remove('active');

    try {
        chrome.storage.local.set({
            golmarket_task: null,
            golfrock_task: null,
            isRegistrationRunning: false
        });
    } catch(e) {}

    checkAndUncheckCompletedFromStorage();
    showToast('자동등록이 중단되었습니다. (완료된 항목 체크 해제됨)');
}

// 골프몬에 등록 실행
function startGolfmonRegistration() {
    const selectedTrs = Array.from(document.querySelectorAll('#dataTable tbody tr.selected'));
    if (selectedTrs.length === 0) {
        alert("골프몬에 등록할 항목이 선택되지 않았습니다.\n목록에서 카드를 클릭하거나 [원클릭]을 먼저 실행해주세요.");
        return;
    }

    // 각 선택된 항목에 고유 등록 ID 부여
    selectedTrs.forEach((tr, idx) => {
        tr.dataset.regId = `reg_${Date.now()}_${idx}`;
    });

    const golfrockMemo = document.getElementById('golfrockMemo')?.value || document.getElementById('golfmonMemo')?.value || '';
    const golftopMemo = document.getElementById('golftopMemo')?.value || '';

    const items = selectedTrs.map(tr => {
        const cells = tr.querySelectorAll('td');
        const origGolf = cells[2].textContent.trim();
        const rawGolf = tr.dataset.rawGolf || origGolf;
        const golfmonGolf = tr.dataset.golfmonGolf || getMappedName(rawGolf, 'golfmon').name || origGolf;
        const source = tr.dataset.source || 'golfrock';
        const itemMemo = (source === 'golftop') ? golftopMemo : golfrockMemo;
        return {
            regId: tr.dataset.regId,
            date: cells[0].textContent.trim(),
            region: cells[1].textContent.trim(),
            golf: golfmonGolf,
            rawGolf: rawGolf,
            time: cells[3].textContent.trim(),
            fee: cells[4].textContent.trim(),
            cady: cells[5].textContent.trim(),
            condition: cells[6].textContent.trim(),
            sizenum: cells[7].textContent.trim(),
            isPrepaid: tr.dataset.isPrepaid === 'true',
            isMeal: tr.dataset.isMeal === 'true',
            source: source,
            memo: itemMemo
        };
    });

    try {
        chrome.storage.local.set({ completedItems: [], isRegistrationRunning: true });
    } catch(e) {}

    const memo = golfrockMemo;
    const mode = lastUsedMacroType || 'join';
    const delayPreset = document.getElementById('selRandomDelay')?.value || 'safe';
    const stepPreset = document.getElementById('selStepDelay')?.value || 'human';

    chrome.tabs.query({ url: ["*://golfmon.net/*", "https://golfmon.net/*", "http://golfmon.net/*", "*://*.golfmon.net/*", "https://*.golfmon.net/*", "http://*.golfmon.net/*"] }, (tabs) => {
        if (tabs && tabs.length > 0) {
            const golfmonTab = tabs[0];
            const sendRegMsg = () => {
                chrome.tabs.sendMessage(golfmonTab.id, {
                    action: 'START_REGISTRATION',
                    items: items,
                    memo: memo,
                    mode: mode,
                    delayPreset: delayPreset,
                    stepPreset: stepPreset
                }, (response) => {
                    if (chrome.runtime.lastError) {
                        console.warn("[Tee82] 등록 스크립트 자동 재주입 시도:", chrome.runtime.lastError.message);
                        if (chrome.scripting && chrome.scripting.executeScript) {
                            chrome.scripting.executeScript({
                                target: { tabId: golfmonTab.id },
                                files: ['content_script.js']
                            }, () => {
                                if (chrome.runtime.lastError) {
                                    if (confirm("골프몬 탭과의 연결이 끊겼습니다.\n골프몬 사이트를 자동으로 새로고침(F5)하시겠습니까?")) {
                                        chrome.tabs.reload(golfmonTab.id);
                                    }
                                    return;
                                }
                                setTimeout(() => {
                                    chrome.tabs.sendMessage(golfmonTab.id, {
                                        action: 'START_REGISTRATION',
                                        items: items,
                                        memo: memo,
                                        mode: mode,
                                        delayPreset: delayPreset,
                                        stepPreset: stepPreset
                                    }, (res2) => {
                                        if (chrome.runtime.lastError) {
                                            if (confirm("골프몬 탭과의 연결에 실패했습니다.\n골프몬 사이트를 자동으로 새로고침(F5)하시겠습니까?")) {
                                                chrome.tabs.reload(golfmonTab.id);
                                            }
                                        } else {
                                            document.getElementById('btnHeaderStop')?.classList.add('active');
                                            showProgressModal(items.length, mode);
                                        }
                                    });
                                }, 200);
                            });
                        } else {
                            if (confirm("골프몬 탭과의 연결에 실패했습니다.\n골프몬 사이트를 자동으로 새로고침(F5)하시겠습니까?")) {
                                chrome.tabs.reload(golfmonTab.id);
                            }
                        }
                    } else {
                        document.getElementById('btnHeaderStop')?.classList.add('active');
                        showProgressModal(items.length, mode);
                    }
                });
            };
            sendRegMsg();
        } else {
            if (confirm("열려 있는 골프몬(golfmon.net) 탭이 없습니다.\n골프몬 사이트를 새 탭으로 여시겠습니까?")) {
                chrome.tabs.create({ url: "https://golfmon.net/" });
            }
        }
    });
}

// 골마켓에 등록 실행
function startGolfmarketRegistration() {
    const selectedTrs = Array.from(document.querySelectorAll('#dataTable tbody tr.selected'));
    if (selectedTrs.length === 0) {
        alert("골마켓에 등록할 항목이 선택되지 않았습니다.\n목록에서 카드를 클릭하거나 [원클릭]을 먼저 실행해주세요.");
        return;
    }

    // 각 선택된 항목에 고유 등록 ID 부여
    selectedTrs.forEach((tr, idx) => {
        tr.dataset.regId = `reg_gm_${Date.now()}_${idx}`;
    });

    const golfrockMemo = document.getElementById('golfrockMemo')?.value || document.getElementById('golfmonMemo')?.value || '';
    const golftopMemo = document.getElementById('golftopMemo')?.value || '';

    const items = selectedTrs.map(tr => {
        const cells = tr.querySelectorAll('td');
        const origGolf = cells[2].textContent.trim();
        const rawGolf = tr.dataset.rawGolf || origGolf;
        const golmarketGolf = tr.dataset.golmarketGolf || getMappedName(rawGolf, 'golmarket').name || getGolmarketGolfName(origGolf) || origGolf;
        const source = tr.dataset.source || 'golfrock';
        const itemMemo = (source === 'golftop') ? golftopMemo : golfrockMemo;
        return {
            regId: tr.dataset.regId,
            date: cells[0].textContent.trim(),
            region: cells[1].textContent.trim(),
            golf: golmarketGolf,
            rawGolf: rawGolf,
            time: cells[3].textContent.trim(),
            fee: cells[4].textContent.trim(),
            cady: cells[5].textContent.trim(),
            condition: cells[6].textContent.trim(),
            sizenum: cells[7].textContent.trim(),
            roomType: tr.dataset.roomType || '',
            isPrepaid: tr.dataset.isPrepaid === 'true',
            isMeal: tr.dataset.isMeal === 'true',
            source: source,
            memo: itemMemo
        };
    });

    const memo = golfrockMemo;
    const delayPreset = document.getElementById('selRandomDelay')?.value || 'safe';
    const stepPreset = document.getElementById('selStepDelay')?.value || 'human';

    // 조인용 원클릭 vs 양도용 원클릭 모드 판별
    const isTransferMode = (lastUsedMacroType === 'transfer') || items.some(it => it.roomType === '양도');
    const mode = isTransferMode ? 'transfer' : 'join';

    const task = {
        isRunning: true,
        platform: 'golmarket',
        mode: mode,
        isTransferMode: isTransferMode,
        items: items,
        currentIndex: 0,
        totalCount: items.length,
        memo: memo,
        delayPreset: delayPreset,
        stepPreset: stepPreset,
        status: 'pending',
        startedAt: Date.now()
    };

    try {
        chrome.storage.local.set({
            golmarket_task: task,
            completedItems: [],
            isRegistrationRunning: true
        });
    } catch(e) {}

    // 즉각 진행상황 모달 표시 및 헤더 중단 버튼 활성화 (화면에 즉시 팝업 표시)
    document.getElementById('btnHeaderStop')?.classList.add('active');
    showProgressModal(items.length, isTransferMode ? 'golmarket_transfer' : 'golmarket');
    if (items[0]) {
        updateProgress(1, items.length, items[0].golf, items[0].date, items[0].time);
    }

    // 골마켓 탭 탐색 및 실행
    chrome.tabs.query({ url: ["*://*.golmarket.co.kr/*", "https://golmarket.co.kr/*", "http://golmarket.co.kr/*"] }, (tabs) => {
        if (tabs && tabs.length > 0) {
            const golmarketTab = tabs[0];
            chrome.tabs.update(golmarketTab.id, { active: true }, () => {
                const currentTabUrl = golmarketTab.url || '';

                if (isTransferMode) {
                    // 양도(부킹) 모드:
                    // 현재 탭이 이미 booking_form.php 에 있다면 바로 시작 메시지 전송
                    if (currentTabUrl.includes('booking_form.php')) {
                        chrome.tabs.sendMessage(golmarketTab.id, {
                            action: 'START_GOLMARKET_REGISTRATION',
                            items: items,
                            memo: memo,
                            mode: 'transfer',
                            isTransferMode: true,
                            delayPreset: delayPreset,
                            stepPreset: stepPreset
                        }, () => {
                            document.getElementById('btnHeaderStop')?.classList.add('active');
                            showProgressModal(items.length, 'golmarket_transfer');
                        });
                    } else {
                        // 부킹등록 작성 페이지(booking_form.php)로 직접 페이지 이동 (이동 후 content_script가 큐를 감지하여 자동 시작)
                        chrome.tabs.update(golmarketTab.id, { url: "https://golmarket.co.kr/booking_form.php" }, () => {
                            document.getElementById('btnHeaderStop')?.classList.add('active');
                            showProgressModal(items.length, 'golmarket_transfer');
                        });
                    }
                } else {
                    // 조인 모드:
                    if (currentTabUrl.includes('join_form.php')) {
                        chrome.tabs.sendMessage(golmarketTab.id, {
                            action: 'START_GOLMARKET_REGISTRATION',
                            items: items,
                            memo: memo,
                            mode: 'join',
                            isTransferMode: false,
                            delayPreset: delayPreset,
                            stepPreset: stepPreset
                        }, () => {
                            document.getElementById('btnHeaderStop')?.classList.add('active');
                            showProgressModal(items.length, 'golmarket');
                        });
                    } else {
                        // 조인 등록 폼으로 페이지 이동 (이동 후 content_script가 큐를 감지하여 자동 시작)
                        chrome.tabs.update(golmarketTab.id, { url: "https://www.golmarket.co.kr/join_form.php" }, () => {
                            document.getElementById('btnHeaderStop')?.classList.add('active');
                            showProgressModal(items.length, 'golmarket');
                        });
                    }
                }
            });
        } else {
            // 골마켓 탭이 열려있지 않은 경우
            if (isTransferMode) {
                // 양도(부킹) 모드: booking_form.php 로 직접 새 탭 열기
                chrome.tabs.create({ url: "https://golmarket.co.kr/booking_form.php" }, () => {
                    document.getElementById('btnHeaderStop')?.classList.add('active');
                    showProgressModal(items.length, 'golmarket_transfer');
                });
            } else {
                // 조인 모드: join_form.php 로 새 탭 열기
                chrome.tabs.create({ url: "https://www.golmarket.co.kr/join_form.php" }, () => {
                    document.getElementById('btnHeaderStop')?.classList.add('active');
                    showProgressModal(items.length, 'golmarket');
                });
            }
        }
    });
}

