    let tempCoursePriceAdjustments = [];

    function renderCoursePriceChips() {
        if (!coursePriceChipContainer) return;
        coursePriceChipContainer.innerHTML = '';
        const modalCount = document.getElementById('coursePriceModalCountText');
        if (modalCount) modalCount.innerText = tempCoursePriceAdjustments.length;

        if (tempCoursePriceAdjustments.length === 0) {
            coursePriceChipContainer.innerHTML = `
                <div class="prepaid-empty-notice">
                    등록된 구장별 가격 변경 규칙이 없습니다.<br>
                    (구장명과 가격 가감 수치[-2, -1, +1, +2], 부제를 선택하여 입력하세요)
                </div>
            `;
            return;
        }

        tempCoursePriceAdjustments.forEach((item, idx) => {
            const chip = document.createElement('div');
            chip.className = 'course-price-chip';
            const signStr = item.diff > 0 ? `+${item.diff}만` : `${item.diff}만`;
            const valClass = item.diff > 0 ? 'adj-val-plus' : 'adj-val-minus';
            const partDesc = getCourseAdjPartDesc(item);
            const partBadge = `<span style="font-size: 9px; background: #EEF2FF; color: #4338CA; border: 1px solid #C7D2FE; padding: 1px 4px; border-radius: 4px; font-weight: 700; margin-left: 3px;">${partDesc}</span>`;

            chip.innerHTML = `
                <span>⛳ <strong>${escapeHtml(item.course)}</strong> ${partBadge}: <span class="${valClass}">${signStr}</span></span>
                <button type="button" class="prepaid-chip-del" data-idx="${idx}" title="삭제">✕</button>
            `;
            coursePriceChipContainer.appendChild(chip);
        });

        coursePriceChipContainer.querySelectorAll('.prepaid-chip-del').forEach(btn => {
            btn.addEventListener('click', () => {
                const idx = parseInt(btn.dataset.idx, 10);
                if (!isNaN(idx) && idx >= 0 && idx < tempCoursePriceAdjustments.length) {
                    tempCoursePriceAdjustments.splice(idx, 1);
                    renderCoursePriceChips();
                }
            });
        });
    }

    function addCoursePriceDiffFromInputs() {
        if (!inputNewCourseName || !inputNewCourseDiff) return;
        const rawName = inputNewCourseName.value.trim();
        const rawDiff = inputNewCourseDiff.value.trim();
        if (!rawName) {
            showToast('구장명을 입력해주세요.');
            inputNewCourseName.focus();
            return;
        }
        const diffVal = parseDiffValue(rawDiff);
        if (diffVal === null || isNaN(diffVal) || diffVal === 0) {
            showToast('가감할 금액을 숫자로 입력해주세요 (예: -2, -1, +1, +2)');
            inputNewCourseDiff.focus();
            return;
        }

        const chk1 = document.getElementById('chkCoursePart1')?.checked ?? true;
        const chk2 = document.getElementById('chkCoursePart2')?.checked ?? true;
        const chk3 = document.getElementById('chkCoursePart3')?.checked ?? true;

        if (!chk1 && !chk2 && !chk3) {
            showToast('적용할 부제(1부, 2부, 3부)를 최소 1개 이상 체크해주세요.');
            return;
        }

        const cleanNew = rawName.replace(/[\s\-_()\[\]]/g, '').toLowerCase();
        const existingIdx = tempCoursePriceAdjustments.findIndex(item => {
            const isSame = item.course.replace(/[\s\-_()\[\]]/g, '').toLowerCase() === cleanNew;
            const isSameParts = (item.hasPart1 === chk1) && (item.hasPart2 === chk2) && (item.hasPart3 === chk3);
            return isSame && isSameParts;
        });

        const newRule = { course: rawName, diff: diffVal, hasPart1: chk1, hasPart2: chk2, hasPart3: chk3 };
        const partDesc = getCourseAdjPartDesc(newRule);

        if (existingIdx >= 0) {
            tempCoursePriceAdjustments[existingIdx] = newRule;
            showToast(`'${rawName}' [${partDesc}] 금액 변경 규칙이 갱신되었습니다.`);
        } else {
            tempCoursePriceAdjustments.push(newRule);
            showToast(`'${rawName}' [${partDesc}] (${diffVal > 0 ? `+${diffVal}` : diffVal}만) 추가되었습니다.`);
        }

        inputNewCourseDiff.value = '';
        renderCoursePriceChips();
        inputNewCourseName.focus();
    }

    function addBatchCoursePriceFromTextarea() {
        if (!textBatchCoursePrice) return;
        const text = textBatchCoursePrice.value.trim();
        if (!text) {
            showToast('붙여넣을 텍스트가 없습니다.');
            return;
        }
        const lines = text.split('\n');
        let addedCount = 0;
        let lastCourse = '';

        lines.forEach(line => {
            const trimmed = line.trim();
            if (!trimmed) return;

            // 라인 자체에 구장명만 단독으로 있는 경우 (예: "남양주cc", "[남양주cc]")
            if (!/\d+(?:\.\d+)?\s*(?:만|만원)?/.test(trimmed) && !/[-+]\d+/.test(trimmed)) {
                const pureName = trimmed.replace(/^[●■□★◆▶▷*#•\-\s]+|[\(\)\[\]]/g, '').trim();
                if (pureName && !isNonGolfLine(pureName) && !isNonCourseWord(pureName)) {
                    lastCourse = pureName;
                    return;
                }
            }

            const parsed = parseCoursePriceAdjustmentLine(trimmed, lastCourse);
            if (parsed) {
                if (parsed.course) lastCourse = parsed.course;
                const cleanNew = parsed.course.replace(/[\s\-_()\[\]]/g, '').toLowerCase();
                const existingIdx = tempCoursePriceAdjustments.findIndex(item => {
                    const isSame = item.course.replace(/[\s\-_()\[\]]/g, '').toLowerCase() === cleanNew;
                    const isSameParts = (item.hasPart1 === parsed.hasPart1) && (item.hasPart2 === parsed.hasPart2) && (item.hasPart3 === parsed.hasPart3);
                    return isSame && isSameParts;
                });
                if (existingIdx >= 0) {
                    tempCoursePriceAdjustments[existingIdx] = parsed;
                } else {
                    tempCoursePriceAdjustments.push(parsed);
                }
                addedCount++;
            }
        });

        textBatchCoursePrice.value = '';
        renderCoursePriceChips();
        if (addedCount > 0) {
            showToast(`${addedCount}개 구장/부제별 가격변경 규칙이 등록되었습니다.`);
        } else {
            showToast('인식 가능한 구장명 및 금액 형식이 없습니다. (예: 남양주cc 1~2부 -2)');
        }
    }

