    // 2. GitHub 최신 매핑사전 실시간 동기화 (네트워크 비동기 fetch)
    if (btnSyncDictFromGitHub) {
        btnSyncDictFromGitHub.addEventListener('click', async () => {
            if (syncDictStatusHint) {
                syncDictStatusHint.innerHTML = '<span style="color:#2563EB; font-weight:600;">⏳ GitHub에서 최신 사전을 불러오는 중입니다...</span>';
            }
            btnSyncDictFromGitHub.disabled = true;

            try {
                let remoteDict = null;
                try {
                    const resJson = await fetch(`https://raw.githubusercontent.com/purry85/tee82/main/dictionary.json?t=${Date.now()}`);
                    if (resJson.ok) {
                        const parsed = await resJson.json();
                        if (parsed && typeof parsed === 'object') remoteDict = parsed;
                    }
                } catch(e) {}

                if (!remoteDict) {
                    const res = await fetch(`https://raw.githubusercontent.com/purry85/tee82/main/popup.js?t=${Date.now()}`);
                    if (!res.ok) throw new Error(`HTTP 상태코드: ${res.status}`);
                    const text = await res.text();

                    const m = text.match(/const\s+DEFAULT_SYNC_CODE\s*=\s*"([^"]+)"/);
                    if (!m || !m[1]) throw new Error('사전 코드를 찾을 수 없습니다.');

                    remoteDict = decodeSyncString(m[1]);
                }
                if (!remoteDict || typeof remoteDict !== 'object') throw new Error('사전 데이터 디코딩에 실패했습니다.');

                let addedCount = 0;
                let updatedCount = 0;
                for (const [k, v] of Object.entries(remoteDict)) {
                    const norm = normalizeDictEntry(v, k);
                    if (!dictionary[k]) {
                        dictionary[k] = norm;
                        addedCount++;
                    } else {
                        dictionary[k] = norm;
                        updatedCount++;
                    }
                }

                saveDictionary();
                updateDictStats();
                updateLivePrepaidFees();

                const nextVer = incrementAppVersion();

                if (syncDictStatusHint) {
                    syncDictStatusHint.innerHTML = `
                        <span style="color:#059669; font-weight:700;">✅ 동기화 완료! (Ver ${nextVer})</span><br>
                        GitHub 최신 사전이 성공적으로 적용되었습니다. (총 ${Object.keys(dictionary).length}개 구장, 신규 ${addedCount}개 / 갱신 ${updatedCount}개)
                    `;
                }
                showToast(`최신 매핑사전 동기화 완료! (Ver ${nextVer}, 총 ${Object.keys(dictionary).length}개)`);
            } catch(err) {
                if (syncDictStatusHint) {
                    syncDictStatusHint.innerHTML = `<span style="color:#EF4444; font-weight:700;">❌ 동기화 실패: ${err.message} (인터넷 또는 GitHub 연결을 확인하세요)</span>`;
                }
                showToast('동기화 실패: ' + err.message);
            } finally {
                btnSyncDictFromGitHub.disabled = false;
            }
        });
    }

